test_review_verdicts_subcommand() {
  local dir="$TMP/verdicts"
  local run="20260611T000000Z-42"

  mkdir -p "$dir/mixed" "$dir/allpass"
  # Complete pass, complete fail, and a died-mid-run artifact. The prompt echo
  # inside Output ("...exactly one line: GATE: pass or GATE: fail.") must not
  # be read as a verdict.
  printf '# codex review\n\n## Output\n\nexactly one line: GATE: pass or GATE: fail.\nFindings: none\nCONFIDENCE: 0.9\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$dir/mixed/codex-x-$run.md"
  printf '# claude review\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' \
    > "$dir/mixed/claude-x-$run.md"
  printf '# antigravity review\n\n## Output\n\npartial output then death\n' \
    > "$dir/mixed/antigravity-x-$run.md"

  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/mixed")" && rc=0 || rc=$?
  [ "$rc" = "2" ] || fail "incomplete artifact should yield exit 2, got $rc"
  printf '%s' "$out" | grep -Fq 'codex: pass (confidence 0.9)' ||
    fail "stated confidence should ride the verdict line: $out"
  printf '%s' "$out" | grep -Fq 'claude: fail' || fail "missing claude fail"
  printf '%s' "$out" | grep -Fq 'antigravity: incomplete' || fail "missing incomplete detection"

  printf '# codex review\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$dir/allpass/codex-x-$run.md"
  printf '# synthesis\n' > "$dir/allpass/_synthesis-x-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/allpass")" && rc=0 || rc=$?
  [ "$rc" = "0" ] || fail "all-pass run should exit 0, got $rc"
  if printf '%s' "$out" | grep -q '_synthesis'; then
    fail "synthesis artifact must not be treated as a provider"
  fi

  mkdir -p "$dir/empty"
  if "$ROOT/scripts/peer-review.sh" verdicts "$dir/empty" >/dev/null 2>&1; then
    fail "empty dir should exit nonzero"
  fi

  # A seat that died after printing a GATE line: the recorded nonzero exit
  # voids the verdict — a partial transcript's pass must not open the gate.
  mkdir -p "$dir/died"
  printf '# codex review\n\n## Output\n\nGATE: pass\n\n## Exit\n\n124\n' \
    > "$dir/died/codex-x-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/died")" && rc=0 || rc=$?
  [ "$rc" = "2" ] || fail "a dead seat's GATE line must not gate (want exit 2, got $rc)"
  printf '%s' "$out" | grep -Fq 'codex: no-verdict (provider exited 124' ||
    fail "dead seat must be named with its exit: $out"

  # A max_tokens stop exits 0 with finished-looking sentences; the recorded
  # stop reason voids the GATE line the same way a dead exit does.
  mkdir -p "$dir/maxtok"
  printf '# claude review\n\n## Output\n\nstop-reason: provider=claude reason=max_tokens subtype=success is_error=0\nFindings: fine\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$dir/maxtok/claude-x-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/maxtok")" && rc=0 || rc=$?
  [ "$rc" = "2" ] || fail "a max_tokens seat's GATE line must not gate (want exit 2, got $rc)"
  printf '%s' "$out" | grep -Fq 'claude: no-verdict (incomplete answer: provider=claude reason=max_tokens' ||
    fail "truncated seat must be named with its stop reason: $out"

  # A marker quoted in the prompt (a replayed thread turn, a diff's context
  # lines) is not the transport's verdict: only the Output region counts.
  mkdir -p "$dir/quoted"
  printf '# claude review\n\n## Prompt\n\nstop-reason: provider=claude reason=max_tokens subtype=success is_error=0\n\n## Output\n\nstop-reason: provider=claude reason=end_turn subtype=success is_error=0\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$dir/quoted/claude-x-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/quoted")" && rc=0 || rc=$?
  [ "$rc" = "0" ] || fail "a prompt-quoted stop-reason must not void a healthy seat (got $rc): $out"
  q="$(printf '# a\n\n## Prompt\n\n stop-reason: provider=claude reason=max_tokens subtype=success is_error=0\n\n## Output\n\nstop-reason: provider=claude reason=end_turn subtype=success is_error=0\nA complete answer with plenty of body to clear the length floor easily.\n\n## Exit\n\n0\n' > "$dir/quoted/aq.md"; python3 "$ROOT/scripts/lib/answer-quality.py" "$dir/quoted/aq.md")"
  [ "$q" = "ok" ] || fail "answer-quality must read the stop reason from the Output region only (got $q)"

  # Debate runs: judge each provider's FINAL round, not round 1; a slug that
  # contains "-r9" must not be parsed as a round suffix.
  mkdir -p "$dir/debate"
  printf '# c\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' > "$dir/debate/codex-x-$run.md"
  printf '# c\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' > "$dir/debate/codex-x-$run-r2.md"
  printf '# c\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' > "$dir/debate/claude-x-$run.md"
  printf '# c\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' > "$dir/debate/claude-x-$run-r1.md"
  printf '# c\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' > "$dir/debate/antigravity-fix-r9-thing-$run.md"

  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/debate")" && rc=0 || rc=$?
  [ "$rc" = "1" ] || fail "debate run with a final-round fail should exit 1, got $rc"
  printf '%s' "$out" | grep -Fq 'codex: pass' || fail "codex must be judged on final round (r2 pass)"
  printf '%s' "$out" | grep -Fq 'claude: fail' || fail "claude must be judged on final round (r1 fail)"
  printf '%s' "$out" | grep -Fq 'antigravity: pass' || fail "slug containing -r9 must be treated as base artifact"
}

test_review_verdicts_json_mode() {
  local dir="$TMP/verdicts-json"
  local run="20260611T000000Z-43"
  local out
  local rc=0

  mkdir -p "$dir/mixed" "$dir/debate"
  printf '# codex review\n\n## Output\n\nexactly one line: GATE: pass or GATE: fail.\nCONFIDENCE: 0.9\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$dir/mixed/codex-x-$run.md"
  printf '# claude review\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' \
    > "$dir/mixed/claude-x-$run.md"
  printf '# antigravity review\n\n## Output\n\npartial output then death\n' \
    > "$dir/mixed/antigravity-x-$run.md"

  out="$("$ROOT/scripts/peer-review.sh" verdicts --json "$dir/mixed")" && rc=0 || rc=$?
  [ "$rc" = "2" ] || fail "json mode must keep the exit contract, got $rc"
  OMS_TEST_JSON="$out" python3 - <<'PY' || fail "json verdicts wrong: $out"
import json, os
data = json.loads(os.environ["OMS_TEST_JSON"])
seats = {s["provider"]: s for s in data["seats"]}
assert data["overall"] == 2, data
assert seats["codex"]["verdict"] == "pass", seats
assert seats["codex"]["confidence"] == 0.9, seats
assert seats["claude"]["verdict"] == "fail", seats
assert seats["claude"]["confidence"] is None, seats
assert seats["antigravity"]["verdict"] == "incomplete", seats
PY

  # Final-round selection and the -r9 slug guard hold in json mode too.
  printf '# c\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' > "$dir/debate/codex-x-$run.md"
  printf '# c\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' > "$dir/debate/codex-x-$run-r2.md"
  printf '# c\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' > "$dir/debate/antigravity-fix-r9-thing-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts --json "$dir/debate")" || true
  OMS_TEST_JSON="$out" python3 - <<'PY' || fail "json debate selection wrong: $out"
import json, os
data = json.loads(os.environ["OMS_TEST_JSON"])
seats = {s["provider"]: s for s in data["seats"]}
assert seats["codex"]["verdict"] == "pass" and seats["codex"]["round"] == 2, seats
assert seats["antigravity"]["round"] == 0, seats
PY
}

test_job_digest_wait_polls_until_empty() {
  local dir="$TMP/job-digest-wait"
  local bin="$dir/bin"
  mkdir -p "$bin"
  printf 'step 1 ok\n' > "$dir/run.log"

  # Valid log extraction is exercised on the real BSD userland by
  # bsd-portability-smoke. This case owns the argument failures and wait loop.
  if "$ROOT/scripts/job-digest.sh" "$dir/nonexistent" >/dev/null 2>"$dir/error"; then
    fail "digest should reject non-file non-jobid argument"
  fi
  assert_file_contains "$dir/error" 'not a log file or job id'
  if "$ROOT/scripts/job-digest.sh" --wait "$dir/run.log" >/dev/null 2>"$dir/werr"; then
    fail "--wait without a job id should fail"
  fi
  assert_file_contains "$dir/werr" 'requires a slurm job id'

  # Fake squeue: a state file drives queued -> error (retry) -> empty (done).
  printf '0\n' > "$dir/poll"
  # Mirrors real squeue: queued (rc0+row) -> transient controller error
  # (rc1, contact message -> retry) -> completed (rc1, "Invalid job id" -> done).
  cat > "$bin/squeue" <<EOF
#!/usr/bin/env bash
n="\$(cat "$dir/poll")"
printf '%s\n' "\$((n + 1))" > "$dir/poll"
case "\$n" in
  0) echo "  12345 part job R 0:01 1 node"; exit 0 ;;
  1) echo "slurm_load_jobs error: Unable to contact slurm controller" >&2; exit 1 ;;
  2) echo "Invalid user: nobody" >&2; exit 1 ;;
  3) echo "config file not found" >&2; exit 1 ;;
  *) echo "slurm_load_jobs error: Invalid job id specified" >&2; exit 1 ;;
esac
EOF
  chmod +x "$bin/squeue"
  cat > "$bin/sleep" <<EOF
#!/usr/bin/env bash
printf '%s\n' "\$*" >> "$dir/sleep.log"
EOF
  chmod +x "$bin/sleep"

  out="$(OMS_JOB_DIGEST_POLL=0 PATH="$bin:$PATH" "$ROOT/scripts/job-digest.sh" --wait 12345 "$dir/run.log" 2>"$dir/werr")" ||
    fail "--wait digest should succeed once the job leaves the queue"
  printf '%s' "$out" | grep -Fq '# Job digest' || fail "wait mode should still emit a digest"
  assert_file_contains "$dir/werr" "no longer queued"
  assert_file_contains "$dir/werr" "transiently"
  # Polled 5 times: queued, contact-error, invalid-user, not-found (all retry),
  # then invalid-job-id (done). Non-job errors must not fake completion.
  [ "$(cat "$dir/poll")" -ge 5 ] || fail "wait loop must retry non-job errors and stop only on invalid-job-id"
  assert_file_contains "$dir/werr" "poll 1s"
  assert_file_contains "$dir/sleep.log" "1"
}


write_fake_tsp() {
  local bin="$1"
  mkdir -p "$bin"
  cat > "$bin/tsp" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
printf '%s\n' "$*" >> "${TSP_STUB_LOG:?}"
case "${1:-}" in
  -S)
    exit 0
    ;;
  -w)
    exit 0
    ;;
  -s)
    printf 'Exit status: %s\n' "${TSP_STUB_EXIT:-0}"
    ;;
  -k)
    exit 0
    ;;
  -r)
    printf 'removed %s\n' "$2"
    ;;
  -c)
    printf 'log for %s\n' "$2"
    ;;
  -C)
    printf 'cleared\n'
    ;;
  -L)
    printf '%s\n' "${TSP_STUB_ID:-41}"
    ;;
  --)
    printf '%s\n' "${TSP_STUB_ID:-41}"
    ;;
  "")
    printf 'ID State Output\n%s finished job\n' "${TSP_STUB_ID:-41}"
    ;;
  *)
    echo "unexpected tsp args: $*" >&2
    exit 2
    ;;
esac
EOF
  chmod +x "$bin/tsp"
}

