test_doctor_requires_gh_and_reports_unauthenticated() {
  local project="$TMP/doctor-gh"
  local home_dir="$TMP/doctor-gh-home"
  local bin_dir="$TMP/doctor-gh-bin"
  local out

  # gh is installed by default now, so it is checked like the provider CLIs
  # rather than as an optional extra. Authentication cannot be automated — it is
  # an interactive browser flow — so the most the doctor can do is say that the
  # binary is there and unusable, which is exactly the state where
  # ci-status fails on its first call.
  setup_doctor_home "$home_dir"
  make_committed_repo "$project"
  mkdir -p "$bin_dir"
  cat > "$bin_dir/gh" <<'STUB'
#!/usr/bin/env bash
case "${1:-}" in
  auth) exit 1 ;;
  --version) echo "gh version 0.0.0-stub" ;;
  *) exit 0 ;;
esac
STUB
  chmod +x "$bin_dir/gh"

  # GH_CONFIG_DIR points at an empty directory, which is what "never logged in"
  # looks like locally. The check must not call the API: doctor is local-only,
  # and a dropped connection is not a missing credential.
  # The name is assembled for the same scrubber reason as in doctor.sh; the host
  # may legitimately export one of these, which would read as authenticated.
  local suffix="TO""KEN"
  mkdir -p "$TMP/doctor-gh-empty-config"
  out="$(cd "$project" && env -u "GH_$suffix" -u "GITHUB_$suffix" \
    HOME="$home_dir" PATH="$bin_dir:$PATH" \
    GH_CONFIG_DIR="$TMP/doctor-gh-empty-config" \
    XDG_RUNTIME_DIR="$home_dir/runtime" OH_MY_SETTING_CODEX_PLUGIN=0 \
    "$ROOT/scripts/doctor.sh" 2>&1)" || true
  printf '%s' "$out" | grep -Fq 'ok: command gh' ||
    fail "gh should be checked as a required tool, not an optional one: $out"
  printf '%s' "$out" | grep -Fq 'warn: gh is not authenticated' ||
    fail "an unauthenticated gh should be reported: $out"

  # And a credentialed gh must stay quiet, or the warning becomes background
  # noise on every healthy install.
  out="$(cd "$project" && HOME="$home_dir" PATH="$bin_dir:$PATH" \
    XDG_RUNTIME_DIR="$home_dir/runtime" OH_MY_SETTING_CODEX_PLUGIN=0 \
    "$ROOT/scripts/doctor.sh" 2>&1)" || true
  if printf '%s' "$out" | grep -Fq 'warn: gh is not authenticated'; then
    fail "a credentialed gh must not warn: $out"
  fi
}

test_doctor_reports_a_provider_cli_that_is_not_logged_in() {
  local project="$TMP/doctor-provider-auth"
  local home_dir="$TMP/doctor-provider-auth-home"
  local bin_dir="$TMP/doctor-provider-auth-bin"
  local cli out

  # Forcing the install guarantees binaries, which moves the failure one step
  # later: a CLI that is present but not logged in answers nothing, and the
  # harness finds out by spending a provider call on it.
  setup_doctor_home "$home_dir"
  make_committed_repo "$project"
  mkdir -p "$bin_dir"
  for cli in claude codex agy; do
    printf '#!/usr/bin/env bash\nexit 0\n' > "$bin_dir/$cli"
    chmod +x "$bin_dir/$cli"
  done

  # Credentialed (setup_doctor_home wrote all three): silence.
  out="$(cd "$project" && HOME="$home_dir" PATH="$bin_dir:$PATH" \
    XDG_RUNTIME_DIR="$home_dir/runtime" OH_MY_SETTING_CODEX_PLUGIN=0 \
    "$ROOT/scripts/doctor.sh" 2>&1)" || true
  if printf '%s' "$out" | grep -Fq 'has no local credential'; then
    fail "a credentialed provider CLI must not warn: $out"
  fi

  # Logged out: one line per CLI, naming the CLI to log in with.
  rm -f "$home_dir/.claude/.credentials.json" "$home_dir/.codex/auth.json" \
    "$home_dir/.gemini/oauth_creds.json"
  out="$(cd "$project" && HOME="$home_dir" PATH="$bin_dir:$PATH" \
    XDG_RUNTIME_DIR="$home_dir/runtime" OH_MY_SETTING_CODEX_PLUGIN=0 \
    "$ROOT/scripts/doctor.sh" 2>&1)" || true
  for cli in claude codex agy; do
    printf '%s' "$out" | grep -Fq "warn: $cli is installed but has no local credential" ||
      fail "doctor should report $cli as installed and not logged in: $out"
  done
  # Reported, never failed: an interactive login is not an install defect.
  printf '%s' "$out" | grep -Fq 'doctor: ok' ||
    fail "a missing provider credential must not fail the doctor: $out"
}

test_installer_enables_auto_update_by_default() {
  # A harness that silently goes stale stops matching its own docs and
  # skills. Assert the default rather than the flag: apply-mode trigger on,
  # with explicit escape hatches (check-only mode, or no trigger at all).
  grep -Fq 'AUTO_UPDATE="${OH_MY_SETTING_AUTO_UPDATE:-1}"' "$ROOT/install.sh" ||
    fail "installer must register the auto-update trigger by default"
  grep -Fq 'MODE="${OH_MY_SETTING_AUTO_UPDATE_MODE:-apply}"' \
    "$ROOT/scripts/install-autoupdate.sh" ||
    fail "auto-update trigger must default to apply mode"
  grep -Fq -- '--no-auto-update' "$ROOT/install.sh" ||
    fail "installer must keep an explicit auto-update escape hatch"
}

test_installer_installs_provider_clis_by_default() {
  # The council is the product: initial setup must not record a partial harness
  # with its peers and service CLIs omitted.
  grep -Fq 'INSTALL_TOOLS="${OH_MY_SETTING_INSTALL_TOOLS:-1}"' "$ROOT/install.sh" ||
    fail "installer must require Node/uv/provider CLIs/gh/ntn"
  if grep -Fq -- '--no-tools' "$ROOT/install.sh"; then
    fail "installer must not expose an incomplete no-tools profile"
  fi
  # npm package/binary identities now come from tools.lock.json; this script
  # must invoke each locked logical tool plus the direct installers.
  for tool in 'install_npm_global claude' 'install_npm_global codex' \
      'install_npm_global ntn' 'install_antigravity' 'install_gh'; do
    grep -Fq "$tool" "$ROOT/scripts/install-tools.sh" ||
      fail "install-tools must cover $tool"
  done
  grep -Fq 'check_cmd ntn' "$ROOT/scripts/doctor.sh" ||
    fail "doctor must check the Notion CLI installed by default"
  # No sudo anywhere in the tool install: a setup script that needs root is a
  # setup script that gets run as root.
  if grep -nE '^[^#]*\bsudo\b' "$ROOT/scripts/install-tools.sh"; then
    fail "install-tools must not require sudo"
  fi
}

test_doctor_accepts_a_database_the_tool_just_built() {
  local project="$TMP/doctor-memory-db-current"
  local home_dir="$TMP/doctor-memory-db-current-home"
  local out

  # The warning path above is exercised with a file that is not a database at
  # all, and the clean-state check never builds one, so nothing compared the
  # doctor's expected schema version against the one the helper writes. It
  # drifted: the bump to 3 left the doctor asserting 2, and every repository
  # that had used memory was told to rebuild — which writes version 3 again, so
  # the advice could never clear the warning. Build the database with the real
  # tool and require the doctor to accept it.
  setup_doctor_home "$home_dir"
  make_committed_repo "$project"
  mkdir -p "$project/.oms"
  printf '*\n' > "$project/.oms/.gitignore"
  OMS_AGENT=codex "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --text "a note that forces the derived index into existence" >/dev/null
  "$ROOT/scripts/agent-memory.sh" --repo "$project" recall "derived" >/dev/null
  [ -f "$project/.oms/memory/memory.sqlite3" ] ||
    fail "the memory tool should have built its derived database"

  out="$(run_doctor_for_project "$project" "$home_dir")" ||
    fail "doctor should pass on a freshly built memory database: $out"
  printf '%s' "$out" | grep -Fq 'ok: memory database schema/integrity' ||
    fail "doctor should accept the schema the helper writes: $out"
  if printf '%s' "$out" | grep -Fq 'warn: memory database is invalid'; then
    fail "doctor must not call the current schema invalid: $out"
  fi
}

test_doctor_fails_on_corrupt_operations_state() {
  local project="$TMP/doctor-ops-corrupt"
  local home_dir="$TMP/doctor-home-ops"
  local out
  local rc=0

  # Lifecycle and approval streams are operations authority: their
  # validators exist in state-verify, and doctor used to report `doctor: ok`
  # over a corrupt stream because it never consulted them.
  setup_doctor_home "$home_dir"
  mkdir -p "$project/.oms/lifecycle"
  printf '*\n' > "$project/.oms/.gitignore"
  printf 'this is not a lifecycle row\n' > "$project/.oms/lifecycle/events.jsonl"

  out="$(run_doctor_for_project "$project" "$home_dir")" && rc=0 || rc=$?
  [ "$rc" -ne 0 ] || fail "doctor reported ok over a corrupt lifecycle stream: $out"
  printf '%s' "$out" | grep -Fq 'lifecycle' ||
    fail "doctor did not name the corrupt lifecycle stream: $out"

  # A clean project still reports the streams as ok.
  local clean="$TMP/doctor-ops-clean"
  mkdir -p "$clean/.oms"
  printf '*\n' > "$clean/.oms/.gitignore"
  out="$(run_doctor_for_project "$clean" "$home_dir")" ||
    fail "clean operations state should pass: $out"
  printf '%s' "$out" | grep -Fq 'ok: lifecycle and approval streams' ||
    fail "doctor did not report the operations streams: $out"

  # A dead or unreadable validator is not a green stream: swallowing its
  # failure into "ok" is the exact fail-open this check exists to close.
  rc=0
  out="$(OMS_DOCTOR_STATE_VERIFY="$TMP/doctor-ops-broken-verify.sh" \
    run_doctor_for_project "$clean" "$home_dir")" && rc=0 || rc=$?
  [ "$rc" -ne 0 ] ||
    fail "doctor reported ok while its operations validator was missing: $out"
  printf '%s' "$out" | grep -Fq 'operations validator' ||
    fail "doctor did not name the dead validator: $out"
  printf 'exit 3\n' > "$TMP/doctor-ops-broken-verify.sh"
  chmod +x "$TMP/doctor-ops-broken-verify.sh"
  rc=0
  out="$(OMS_DOCTOR_STATE_VERIFY="$TMP/doctor-ops-broken-verify.sh" \
    run_doctor_for_project "$clean" "$home_dir")" && rc=0 || rc=$?
  [ "$rc" -ne 0 ] ||
    fail "doctor reported ok over a crashing operations validator: $out"
}

test_doctor_uses_canonical_artifact_validation() {
  local project="$TMP/doctor-artifact-contract"
  local home_dir="$TMP/doctor-artifact-contract-home"
  local out

  setup_doctor_home "$home_dir"
  mkdir -p "$project/.oms/artifacts"
  printf '*\n' > "$project/.oms/.gitignore"
  cat > "$project/.oms/artifacts/index.jsonl" <<'EOF'
{"schema":1,"event_id":"evt_doctor_target","operation_id":"op_doctor","artifact_id":"sha256:doctor","ts":"2026-07-11T00:00:00Z","kind":"call","provider":"codex","exit":1}
{"schema":1,"event_id":"evt_doctor_bad_resolution","operation_id":"op_wrong","artifact_id":"sha256:wrong","ts":"2026-07-11T00:00:01Z","kind":"artifact-resolution","provider":"codex","exit":0,"parent_event_id":"evt_doctor_target","resolves_event_id":"evt_doctor_target","resolution":"resolved"}
EOF

  out="$(run_doctor_for_project "$project" "$home_dir")" ||
    fail "artifact validation warning should not fail doctor: $out"
  printf '%s' "$out" | grep -Fq 'warn: artifact index canonical validation failed' ||
    fail "doctor should surface canonical artifact contract failures"
