test_prompt_takers_refuse_a_mistyped_option() {
  # Before the guard, a leading-dash argument arriving while the prompt was
  # still empty was silently adopted as the prompt (and then usually
  # discarded when --prompt arrived), so a typo'd flag changed nothing and
  # said nothing. Every prompt-taking front door refuses it now.
  local script out rc

  for script in advise agent-call agent-run consult peer-ask peer-review; do
    rc=0
    out="$(PATH="/usr/bin:/bin" bash "$ROOT/scripts/$script.sh" \
      --bogus-flag --prompt probe 2>&1)" || rc=$?
    [ "$rc" != "0" ] ||
      fail "$script must refuse a mistyped option, got success: $out"
    printf '%s\n' "$out" | grep -Fq 'unknown option: --bogus-flag' ||
      fail "$script must name the mistyped option: $out"
  done
}

test_peer_review_gate_covers_rides_the_mechanical_verify_receipt() {
  local project="$TMP/review-gate-covers"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local rc=0

  make_committed_repo "$project"
  mkdir -p "$home_dir"
  cat > "$project/PROJECT.md" <<'PROJECT'
# Covers fixture

## Acceptance Criteria

- [id:gate-covers-crit] The gate verify command passes on this tree.
PROJECT
  git -C "$project" add PROJECT.md
  git -C "$project" \
    -c user.email=test@example.com -c user.name='Test User' \
    commit -qm criteria
  write_fake_review_gate_provider "$bin_dir" claude pass
  write_fake_review_gate_provider "$bin_dir" antigravity pass

  # Misuse fails before any reviewer or artifact side effect: covers without
  # the gate, covers without a verify command, and an id the envelope does
  # not know.
  if HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --artifact-dir "$project/artifacts-misuse" \
    --providers claude,antigravity --no-diff \
    --covers gate-covers-crit --prompt "covers without gate" >/dev/null 2>&1; then
    fail "--covers without --gate must be rejected"
  fi
  if HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --artifact-dir "$project/artifacts-misuse" \
    --providers claude,antigravity --no-diff --gate --no-verify \
    --covers gate-covers-crit --prompt "covers without verify" >/dev/null 2>&1; then
    fail "--covers without a gate verify command must be rejected"
  fi
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --artifact-dir "$project/artifacts-misuse" \
    --providers claude,antigravity --no-diff --gate --verify true \
    --covers no-such-criterion --prompt "unknown covers id" \
    >/dev/null 2>"$project/err-unknown" && rc=0 || rc=$?
  [ "$rc" != "0" ] || fail "an unknown covers id must be rejected"
  assert_file_contains "$project/err-unknown" "unknown criterion id"
  [ ! -d "$project/artifacts-misuse" ] ||
    fail "rejected covers must not leave review artifacts behind"

  # Happy path: the explicit id rides the mechanical verify receipt beside
  # the derived plan-acceptance cover, exit-judged; reviewer prose rows carry
  # no covers at all.
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --artifact-dir "$project/artifacts" \
    --providers claude,antigravity --no-diff --gate --verify true \
    --covers gate-covers-crit --prompt "covers happy path" >"$project/out" ||
    fail "gate with covers should pass: $(cat "$project/out")"
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' ||
import json, sys
rows = [json.loads(l) for l in open(sys.argv[1], encoding="utf-8") if l.strip()]
verify = [r for r in rows if r.get("kind") == "review-verify"]
assert verify, "no review-verify row"
covers = verify[-1].get("covers", [])
assert "gate-covers-crit" in covers, covers
assert any(c.startswith("criterion-plan-acceptance-") for c in covers), covers
assert verify[-1].get("status") == "verified", verify[-1]
for row in rows:
    if row.get("kind") in ("review-outcome", "ask", "review"):
        assert "covers" not in row, row
PY
    fail "verify receipt covers are wrong: $(tail -c 2000 "$project/.oms/artifacts/index.jsonl")"
  "$ROOT/scripts/runtime.sh" --repo "$project" envelope show > "$project/envelope.json" ||
    fail "envelope show failed"
  python3 - "$project/envelope.json" <<'PY' ||
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
statuses = {item["id"]: item["status"] for item in row["criteria"]}
assert statuses.get("gate-covers-crit") == "verified", statuses
PY
    fail "explicit covers did not project the criterion to verified"

  # The derived plan-acceptance cover is equally load-bearing: a gate whose
  # verify receipt cannot be recorded fails closed even without --covers.
  local rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_ARTIFACT_INDEX=/proc/version/cannot/index.jsonl \
    "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --artifact-dir "$project/artifacts-closed" \
    --providers claude,antigravity --no-diff --gate --verify true \
    --prompt "derived cover fail closed" >/dev/null 2>"$project/err-closed" && rc=0 || rc=$?
  [ "$rc" != 0 ] || fail "a gate with an unwritable index must fail closed"
  grep -q "failing closed\|cannot create" "$project/err-closed" ||
    fail "the fail-closed refusal must be named: $(tail -2 "$project/err-closed")"
}

test_peer_review_gate_binds_complete_diff_and_refuses_truncation() {
  local project="$TMP/review-gate-complete-diff"
  local artifact_dir="$project/artifacts"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local expected_sha rc=0

  make_committed_repo "$project"
  mkdir -p "$home_dir"
  write_fake_review_gate_provider "$bin_dir" claude pass
  printf '/artifacts/\n/truncated-artifacts/\n/bin/\n/out\n/truncated.out\n/provider-called\n' >> "$project/.git/info/exclude"
  printf 'reviewed change\n' >> "$project/file.txt"
  cat > "$project/.git/hostile-external-diff" <<'EOF'
#!/usr/bin/env bash
: > "$(git rev-parse --git-dir)/external-diff-fired"
printf 'forged review diff\n'
EOF
  chmod +x "$project/.git/hostile-external-diff"
  git -C "$project" config --local diff.external "$project/.git/hostile-external-diff"
  expected_sha="$(git -c diff.external= -C "$project" diff --no-ext-diff --no-textconv HEAD -- | python3 -c 'import hashlib,sys; print(hashlib.sha256(sys.stdin.buffer.read()).hexdigest())')"

  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PROMPT_DIFF_BYTES=65536 \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$artifact_dir" \
    --providers claude --gate --no-verify --prompt "Bind the full diff" \
    >"$project/out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "complete gate diff should pass, got $rc: $(cat "$project/out")"
  [ ! -e "$project/.git/external-diff-fired" ] ||
    fail "repository diff.external executed with reviewer authority"
  python3 - "$project/.oms/artifacts/index.jsonl" "$expected_sha" <<'PY' ||
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
review = [row["review"] for row in rows if row.get("kind") == "review-outcome"][-1]
assert review["diff_sha256"] == sys.argv[2], review
seat = review["seats"][0]
assert seat["requested_model"], seat
assert seat["selected_model"], seat
assert seat["model_family"] == "anthropic", seat
PY
    fail "typed gate outcome did not bind full diff/model provenance"

  # A bounded prompt slice is useful for advisory review but is not enough for
  # a blocking gate. The gate must stop before it asks a provider to judge an
  # incomplete diff.
  awk 'BEGIN { for (i = 0; i < 200; i++) print "more-diff-evidence-" i }' >> "$project/file.txt"
  : > "$project/provider-called"
  cat > "$bin_dir/claude" <<'EOF'
#!/usr/bin/env bash
echo called >> "$HOME/provider-called"
cat >/dev/null
printf 'Findings:\nNo findings\nRisks:\nnone\nMissing tests:\nnone\nRecommendation:\nproceed\nGATE: pass\n'
EOF
  chmod +x "$bin_dir/claude"
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PROMPT_DIFF_BYTES=256 \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$project/truncated-artifacts" \
    --providers claude --gate --no-verify --prompt "Do not judge a slice" \
    >"$project/truncated.out" 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "truncated gate diff must fail closed with exit 2, got $rc"
  assert_file_contains "$project/truncated.out" "blocking gate requires the complete diff"
  [ ! -s "$home_dir/provider-called" ] || fail "provider was called with a truncated gate diff"

  # The final selected route is read from the provider artifact, not inferred
  # from the transport name or copied from the requested primary.
  local manual="$project/manual-artifacts"
  mkdir -p "$manual"
  cat > "$manual/antigravity-route-20260812T000000Z-42.md" <<'EOF'
# antigravity review

## Output

model-route: class=explicit (explicit) primary=gemini-primary fallback=claude-fallback effort=high fallback_effort=medium
model-fallback: reason=capacity selected=claude-fallback
model-result: selected=claude-fallback effort=medium fallback_used=1 reason=capacity
GATE: pass

## Exit

0
EOF
  "$ROOT/scripts/peer-review.sh" verdicts --json "$manual" > "$project/manual.json"
  python3 - "$project/manual.json" <<'PY' || fail "fallback model provenance was not extracted"
import json, sys
seat = json.load(open(sys.argv[1], encoding="utf-8"))["seats"][0]
assert seat["requested_model"] == "gemini-primary", seat
assert seat["selected_model"] == "claude-fallback", seat
assert seat["model_family"] == "anthropic", seat
PY
}

