make_committed_repo() {
  local project="$1"
  mkdir -p "$project"
  # -b main so tests are branch-deterministic: CI has no init.defaultBranch,
  # where plain `git init` yields 'master' and make_patch_repo's `git diff main`
  # would fatal.
  git -C "$project" init -b main >/dev/null
  printf 'base\n' > "$project/file.txt"
  git -C "$project" add file.txt
  git -C "$project" \
    -c user.email=test@example.com \
    -c user.name='Test User' \
    commit -m init >/dev/null
}

write_auto_update_fixture_scripts() {
  local repo="$1"
  local link_mode="${2:-ok}"
  local doctor_mode="${3:-ok}"

  mkdir -p "$repo/scripts/lib"
  cp "$ROOT/scripts/auto-update.sh" "$repo/scripts/auto-update.sh"
  cp "$ROOT/scripts/lib/file-lock.sh" "$repo/scripts/lib/file-lock.sh"
  cp "$ROOT/scripts/lib/poll.sh" "$repo/scripts/lib/poll.sh"
  chmod +x "$repo/scripts/auto-update.sh"

  case "$link_mode" in
    ok)
      cat > "$repo/scripts/link.sh" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
mkdir -p "$HOME/.oms-test"
ln -sfn "$root/README.md" "$HOME/.oms-test/readme"
printf 'linked\n' > "$HOME/.oms-test/linked"
EOF
      ;;
    fail)
      cat > "$repo/scripts/link.sh" <<'EOF'
#!/usr/bin/env bash
echo "link failed intentionally" >&2
exit 7
EOF
      ;;
    *) fail "unknown fixture link mode: $link_mode" ;;
  esac
  chmod +x "$repo/scripts/link.sh"

  case "$doctor_mode" in
    ok)
      cat > "$repo/scripts/doctor.sh" <<'EOF'
#!/usr/bin/env bash
echo "doctor ok"
EOF
      ;;
    fail)
      cat > "$repo/scripts/doctor.sh" <<'EOF'
#!/usr/bin/env bash
echo "doctor warning" >&2
exit 8
EOF
      ;;
    *) fail "unknown fixture doctor mode: $doctor_mode" ;;
  esac
  chmod +x "$repo/scripts/doctor.sh"

  cat > "$repo/scripts/install-claude-hooks.sh" <<'EOF'
#!/usr/bin/env bash
mkdir -p "$HOME/.oms-test"
printf 'claude-hooks\n' >> "$HOME/.oms-test/refresh.log"
EOF
  cat > "$repo/scripts/install-codex-plugin.sh" <<'EOF'
#!/usr/bin/env bash
mkdir -p "$HOME/.oms-test"
printf 'codex-plugin\n' >> "$HOME/.oms-test/refresh.log"
EOF
  chmod +x "$repo/scripts/install-claude-hooks.sh" "$repo/scripts/install-codex-plugin.sh"
}

setup_auto_update_fixture() {
  local origin="$1"
  local seed="$2"
  local work="$3"

  git init --bare "$origin" >/dev/null
  git init -b main "$seed" >/dev/null
  git -C "$seed" config user.email test@example.com
  git -C "$seed" config user.name 'Test User'
  write_auto_update_fixture_scripts "$seed" ok ok
  printf 'local/\n' > "$seed/.gitignore"
  printf 'one\n' > "$seed/README.md"
  git -C "$seed" add .gitignore README.md scripts >/dev/null
  git -C "$seed" commit -m 'initial' >/dev/null
  git -C "$seed" remote add origin "$origin"
  git -C "$seed" push -u origin main >/dev/null
  git clone --branch main "$origin" "$work" >/dev/null 2>&1
}

test_delegate_dry_run() {
  local project="$TMP/delegate-dry"
  local artifact_dir="$project/artifacts"

  make_committed_repo "$project"

  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --prompt "Add a helper" >/dev/null

  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'Do not run git commit'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'Search repository structure, affected call paths and contracts'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'source code, tests, official docs, issue/PR/history'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'test competing hypotheses with the cheapest discriminating probe'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'Comments/docstrings preserve task/repo-established public contracts'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'never restate code, types, tests, or names'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'Extend an existing canonical test or fixture first'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'Report What changed, Why, Evidence, Verification'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'DRY RUN: worker command skipped.'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' '(path omitted)'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'worktree: temporary (removed after run)'
  if grep -rFq "$project" "$artifact_dir"/codex-add-a-helper-*.md; then
    fail "delegate artifact must not record the absolute repo path"
  fi
  local patch
  patch="$(find "$artifact_dir" -type f -name 'codex-add-a-helper-*.patch' | head -n 1)"
  [ -n "$patch" ] || fail "missing delegate patch artifact"
  [ ! -s "$patch" ] || fail "dry-run patch should be empty"
  [ -z "$(git -C "$project" status --porcelain file.txt)" ] || fail "delegate dry-run touched main tree"
}

test_delegate_read_only_rejects_apply() {
  local project="$TMP/delegate-read-only"

  make_committed_repo "$project"
  # Authority comes from the caller, and the two flags contradict: a
  # read-only worker produces a report, never a patch to apply.
  if OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
      --to codex --repo "$project" --prompt "Audit the tree" \
      --read-only --apply >/dev/null 2>"$project/err"; then
    fail "--read-only with --apply must be rejected"
  fi
  assert_file_contains "$project/err" "--read-only produces no patch"
}

test_delegate_embeds_review_findings() {
  local project="$TMP/delegate-review-uptake"
  local artifact_dir="$project/artifacts"
  local review="$project/review-synthesis.md"

  make_committed_repo "$project"
  printf '# Review synthesis\n\nMust-fix: the loop off-by-one in foo().\n' > "$review"

  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --review-artifact "$review" \
    --prompt "Fix per review" >/dev/null

  # Findings live inside the worker brief, not in a side artifact the worker
  # may ignore; the index row keeps review->patch lineage joinable.
  assert_one_artifact_contains "$artifact_dir" 'codex-fix-per-review-*.md' 'Review findings to address'
  assert_one_artifact_contains "$artifact_dir" 'codex-fix-per-review-*.md' 'the loop off-by-one in foo()'
  assert_one_artifact_contains "$artifact_dir" 'codex-fix-per-review-*.md' 'Untrusted reviewer claims'
  grep -Fq '"source": "review-synthesis.md"' "$project/.oms/artifacts/index.jsonl" ||
    fail "delegation index row must record the review artifact as its source"

  # A missing review artifact is misuse, caught before any worker runs.
  if OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --artifact-dir "$artifact_dir" \
    --review-artifact "$project/absent.md" --prompt x >/dev/null 2>&1; then
    fail "--review-artifact with a missing file must be rejected"
  fi
}

test_delegate_fake_worker_apply() {
  local project="$TMP/delegate-apply"
  # Landing requires the main tree to stay clean, including untracked files;
  # keep caller-selected artifacts outside the repository for this success case.
  local artifact_dir="$TMP/delegate-apply-artifacts"
  local bin_dir="$TMP/delegate-apply-bin"
  local home_dir="$TMP/delegate-apply-home"

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat >/dev/null
printf 'hello from worker\n' > delegated.txt
echo "worker done"
EOF
  chmod +x "$bin_dir/codex"

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" \
    --to codex \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --apply \
    --allow-restructure \
    --prompt "Create delegated file" >/dev/null

  [ -f "$project/delegated.txt" ] || fail "applied patch should create delegated.txt in main tree"
  assert_file_contains "$project/delegated.txt" "hello from worker"
  assert_one_artifact_contains "$artifact_dir" 'codex-create-delegated-file-*.md' 'worker done'
}

test_delegate_context_manifest_reaches_worker() {
  local project="$TMP/delegate-context"
  local artifact_dir="$TMP/delegate-context-artifacts"
  local bin_dir="$TMP/delegate-context-bin"
  local home_dir="$TMP/delegate-context-home"
  local capture="$TMP/delegate-context-prompt"

  make_committed_repo "$project"
  printf '%s\n' '# Context fixture' '' '## Goal' '' \
    'delegate-context-sentinel reaches the worker from the detached snapshot.' \
    > "$project/PROJECT.md"
  git -C "$project" add PROJECT.md
  git -C "$project" commit -qm context-fixture
  mkdir -p "$bin_dir" "$home_dir"
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat > "$OMS_CONTEXT_CAPTURE"
printf 'worker done\n'
EOF
  chmod +x "$bin_dir/codex"

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" \
    OMS_CONTEXT_CAPTURE="$capture" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --artifact-dir "$artifact_dir" \
    --context-manifest --no-verify --prompt "Use compiled context" >/dev/null

  assert_file_contains "$capture" '## Compiled repository context'
  assert_file_contains "$capture" 'delegate-context-sentinel reaches the worker'
  python3 - "$project/.oms/artifacts/index.jsonl" \
    "$project/.oms/runtime/context" <<'PY'
import json, pathlib, re, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
delegates = [row for row in rows if row.get("kind") == "delegate"]
assert len(delegates) == 1, delegates
row = delegates[0]
assert re.fullmatch(r"[0-9a-f]{64}", row.get("context_manifest_digest", "")), row
assert re.fullmatch(r"[0-9a-f]{64}", row.get("context_bundle_sha256", "")), row
root = pathlib.Path(sys.argv[2])
assert len(list(root.glob("*.json"))) == 1, list(root.glob("*"))
assert len(list(root.glob("*.txt"))) == 1, list(root.glob("*"))
PY
  "$ROOT/scripts/runtime.sh" --repo "$project" benchmark show |
    python3 -c 'import json,sys; row=json.load(sys.stdin); assert row["context"]["manifests"] == 1, row["context"]'
}

test_delegate_context_debt_reaches_worker() {
  local project="$TMP/delegate-context-debt"
  local artifact_dir="$TMP/delegate-context-debt-artifacts"
  local bin_dir="$TMP/delegate-context-debt-bin"
  local home_dir="$TMP/delegate-context-debt-home"
  local capture="$TMP/delegate-context-debt-prompt"

  make_committed_repo "$project"
  python3 - "$project/large.py" <<'PY'
import sys
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    handle.write("VALUE = 1\n" * 8000)
PY
  git -C "$project" add large.py
  git -C "$project" -c user.email=test@example.com -c user.name='Test User' \
    commit -m large-context >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" add --id context-debt \
    --title "Use a bounded large target" --allowed large.py --verify true >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" claim --id context-debt \
    --provider codex >/dev/null
  mkdir -p "$bin_dir" "$home_dir"
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat > "$OMS_CONTEXT_DEBT_CAPTURE"
printf 'worker done\n'
EOF
  chmod +x "$bin_dir/codex"

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" \
    OMS_CONTEXT_DEBT_CAPTURE="$capture" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$artifact_dir" --plan-task context-debt \
    --context-manifest --no-verify >/dev/null

  assert_file_contains "$capture" 'context_debt: 1'
  assert_file_contains "$capture" 'missing_or_truncated_required: large.py'
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY'
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
row = [item for item in rows if item.get("kind") == "delegate"][-1]
assert row["context_debt"] == 1, row
assert row["context_selected_bytes"] > 0, row
PY
  "$ROOT/scripts/runtime.sh" --repo "$project" benchmark show |
    python3 -c 'import json,sys; row=json.load(sys.stdin); assert row["context"]["debt_sum"] == 1, row["context"]'
}

test_delegate_context_compile_failure_never_runs_worker() {
  local project="$TMP/delegate-context-failure"
  local artifact_dir="$TMP/delegate-context-failure-artifacts"
  local bin_dir="$TMP/delegate-context-failure-bin"
  local home_dir="$TMP/delegate-context-failure-home"
  local marker="$TMP/delegate-context-failure-worker-ran"
  local rc=0

  make_committed_repo "$project"
  mkdir -p "$project/.oms/runtime" "$bin_dir" "$home_dir"
  printf 'not a directory\n' > "$project/.oms/runtime/context"
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
printf 'ran\n' > "$OMS_CONTEXT_FAILURE_MARKER"
cat >/dev/null
EOF
  chmod +x "$bin_dir/codex"

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" \
    OMS_CONTEXT_FAILURE_MARKER="$marker" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$artifact_dir" --context-manifest --no-verify \
    --prompt "Compiler failure must block" >/dev/null 2>&1 || rc=$?

  [ "$rc" = 3 ] || fail "context compiler failure should exit 3, got $rc"
  [ ! -e "$marker" ] || fail "context compiler failure still ran the worker"
  assert_one_artifact_contains "$artifact_dir" 'codex-*.md' \
    'SKIPPED: requested context manifest compilation failed.'
}

test_delegate_apply_refuses_dirty_tree() {
  local project="$TMP/delegate-dirty"
  local artifact_dir="$project/artifacts"
  local bin_dir="$project/bin"
  local home_dir="$project/home"

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat >/dev/null
printf 'x\n' > delegated.txt
EOF
  chmod +x "$bin_dir/codex"
  printf 'dirty\n' >> "$project/file.txt"

  if HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" \
    --to codex \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --apply \
    --prompt "Apply on dirty tree" >/dev/null 2>"$project/error"; then
    fail "--apply on dirty main tree should fail"
  fi

  assert_file_contains "$project/error" 'refusing --apply'
  [ ! -f "$project/delegated.txt" ] || fail "dirty-tree apply should not modify main tree"
}

