  "$plan" --repo "$outer" init --goal outer \
    --accept "bash '$plan' --repo '$nested' accept >/dev/null" >/dev/null
  "$plan" --repo "$outer" add --id t1 --title "external work" >/dev/null
  plan_sha="$(python3 - "$outer/.oms/plan/tasks.json" <<'PY' | tr -d '\r'
