  assert_file_contains "$project/.oms/artifacts/index.jsonl" '"kind": "call-import"'
  source_rel="${export_artifact#"$project"/}"
  assert_file_contains "$project/.oms/artifacts/index.jsonl" "\"source\": \"$source_rel\""
}

