    fail "latest-run should list unparseable artifact row individually"
}

# validate reports rows whose artifact is gone and nothing could repair them:
# the retention prune is a cap on row count, so any keep value either spares
# stale rows or discards good ones, and editing .oms by hand is forbidden. Found
# by deleting 360 test-fixture artifacts and watching doctor warn with no fix
# available.
# Duration and provider-reported tokens are parsed out of the artifact body, so
# reading them used to require the artifact to still exist: retention decided
# whether past calls could be accounted for, and pruning stale artifacts silently
# erased what they had cost. The row caches them at write time now.
test_artifact_index_accounting_survives_artifact_deletion() {
  local project="$TMP/index-accounting"
  local bin="$project/bin"
  local index="$project/.oms/artifacts/index.jsonl"
  local out

  make_committed_repo "$project"
  mkdir -p "$bin"
  {
    printf '%s\n' '#!/usr/bin/env bash'
    printf '%s\n' 'cat >/dev/null'
    printf '%s\n' 'printf "a real answer body for the classifier\n\ntokens used\n1234\n"'
  } > "$bin/codex"
  chmod +x "$bin/codex"

  ( cd "$project" && PATH="$bin:$PATH" "$ROOT/scripts/agent-call.sh" \
      --to codex --repo "$project" --prompt 'accounting probe' >/dev/null 2>&1 ) ||
    fail "the stubbed call should succeed"

  python3 - "$index" <<'PY' || fail "the row should cache duration and tokens"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
row = rows[-1]
assert isinstance(row.get("duration_s"), (int, float)), row
assert isinstance(row.get("tokens"), int) and row["tokens"] > 0, row
PY

  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" telemetry)"
  printf '%s' "$out" | grep -Eq 'token-reports=[1-9]' ||
    fail "telemetry should report the token count: $out"

  # The artifact goes; the accounting stays. Coverage of artifacts drops, which
  # is the honest part — the numbers do not.
  rm -rf "$project/.oms/artifacts/call"
  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" telemetry)"
  printf '%s' "$out" | grep -Fq 'artifacts=0' ||
    fail "artifact coverage should drop once the file is gone: $out"
  printf '%s' "$out" | grep -Eq 'token-reports=[1-9]' ||
    fail "token accounting must survive artifact deletion: $out"
  printf '%s' "$out" | grep -Eq 'durations=[1-9]' ||
    fail "duration accounting must survive artifact deletion: $out"
}

test_artifact_index_prunes_stale_references() {
  local project="$TMP/artifact-index-stale"
  local index="$project/.oms/artifacts/index.jsonl"
  local out

  mkdir -p "$project/.oms/artifacts/ask"
  printf 'kept\n' > "$project/.oms/artifacts/ask/present.md"
  printf '{"ts":"2026-06-11T00:00:01Z","kind":"call","artifact":".oms/artifacts/ask/present.md"}\n' >> "$index"
  printf '{"ts":"2026-06-11T00:00:02Z","kind":"call","artifact":".oms/artifacts/ask/gone.md"}\n' >> "$index"
  printf '{"ts":"2026-06-11T00:00:03Z","kind":"call","exit":0}\n' >> "$index"

  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune --stale --dry-run)"
  printf '%s' "$out" | grep -Fq 'would drop 1 stale row' ||
    fail "dry-run should report the stale row: $out"
  [ "$(wc -l < "$index")" = "3" ] || fail "dry-run must not change the index"

  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune --stale)"
  printf '%s' "$out" | grep -Fq 'dropped 1 stale row' || fail "stale sweep should report: $out"
  [ "$(wc -l < "$index")" = "2" ] || fail "stale sweep should drop exactly the stale row"
  grep -Fq 'present.md' "$index" || fail "a row whose artifact exists must survive"
  grep -Fq 'gone.md' "$index" && fail "the stale row must be gone"
  # A row that references no file at all is not stale.
  grep -Fq '00:00:03Z' "$index" || fail "a row with no artifact reference must survive"

  # Age is not the question, so --keep must not enter into it.
  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune --stale)"
  printf '%s' "$out" | grep -Fq 'no stale references' || fail "second sweep should be a no-op: $out"
  [ "$(wc -l < "$index")" = "2" ] || fail "a clean index must be left alone"

  # A resolution explains why an earlier failure is closed, so it cannot outlive
  # the row it resolves: leaving it behind trades one dangling reference for
  # another, and validate is the only thing that would ever notice.
  printf 'temp\n' > "$project/.oms/artifacts/ask/resolved.md"
  printf '{"ts":"2026-06-11T00:00:04Z","kind":"call","event_id":"evt_target","artifact":".oms/artifacts/ask/resolved.md"}\n' >> "$index"
  printf '{"ts":"2026-06-11T00:00:05Z","kind":"artifact-resolution","event_id":"evt_res","resolves_event_id":"evt_target"}\n' >> "$index"
  rm -f "$project/.oms/artifacts/ask/resolved.md"
  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune --stale)"
  printf '%s' "$out" | grep -Fq 'dropped 2 stale row' ||
    fail "the stale row and its orphaned resolution should go together: $out"
  ! grep -Fq 'evt_res' "$index" || fail "a resolution outlived the row it resolves"
  "$ROOT/scripts/artifact-index.sh" --repo "$project" validate \
    > "$project/validate-out" 2>&1 || true
  # The fixture's minimal rows carry other schema gaps on purpose, so assert the
  # one error this sweep is capable of creating rather than a clean bill.
  ! grep -Fq 'resolution target' "$project/validate-out" ||
    fail "the stale sweep left a dangling resolution behind"
}

test_artifact_index_prune() {
  local project="$TMP/artifact-index-prune"
  local index="$project/.oms/artifacts/index.jsonl"
  local out
  local perms

  mkdir -p "$project/.oms/artifacts"
  for i in $(seq 1 10); do
    printf '{"ts":"2026-06-11T00:00:%02dZ","kind":"call","provider":"codex","exit":0}\n' "$i" >> "$index"
  done

  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune 3)"
  printf '%s' "$out" | grep -Fq 'pruned 10 -> 3' || fail "prune should report 10 -> 3"
  [ "$(wc -l < "$index")" = "3" ] || fail "prune should keep exactly 3 rows"
  # Newest rows are kept (tail).
  tail -n1 "$index" | grep -Fq '00:10Z' || fail "prune must keep the newest rows"
  grep -Fq '00:01Z' "$index" && fail "prune must drop the oldest rows"

  # Under the keep count: no-op, exit 0.
  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune 100)" || fail "prune within keep should exit 0"
  printf '%s' "$out" | grep -Fq 'nothing pruned' || fail "prune within keep should be a no-op"
  TMPDIR=/nonexistent-oms-tmp "$ROOT/scripts/artifact-index.sh" --repo "$project" prune 100 >/dev/null ||
    fail "prune no-op without --files must not require TMPDIR"

  # Prune is an in-place overwrite: file permissions survive.
  chmod 640 "$index"
  "$ROOT/scripts/artifact-index.sh" --repo "$project" prune 2 >/dev/null
  perms="$(stat -c '%a' "$index" 2>/dev/null || stat -f '%Lp' "$index" 2>/dev/null)"
  [ "$perms" = "640" ] || fail "prune must preserve file permissions (got $perms)"
}


test_artifact_index_prune_files_deletes_only_orphans() {
  local project="$TMP/artifact-index-prune-files"
  local index="$project/.oms/artifacts/index.jsonl"
  local outside="$project/outside.md"
  local out

  mkdir -p "$project/.oms/artifacts/call" "$project/.oms/artifacts/delegate"
  printf 'old artifact\n' > "$project/.oms/artifacts/call/old.md"
  printf 'old patch\n' > "$project/.oms/artifacts/delegate/old.patch"
  printf 'kept artifact\n' > "$project/.oms/artifacts/call/kept.md"
  printf 'keep me\n' > "$project/.oms/artifacts/.gitignore"
  printf 'outside\n' > "$outside"
  ln -s "$outside" "$project/.oms/artifacts/call/outside-link.md"
  cat > "$index" <<'EOF'
{"ts":"2026-06-11T00:00:01Z","kind":"delegate","provider":"codex","exit":0,"artifact":".oms/artifacts/call/old.md","patch":".oms/artifacts/delegate/old.patch"}
{"ts":"2026-06-11T00:00:02Z","kind":"call","provider":"codex","exit":0,"artifact":".oms/artifacts/call/kept.md"}
EOF

  out="$(OMS_ARTIFACT_ORPHAN_GRACE=0 \
    "$ROOT/scripts/artifact-index.sh" --repo "$project" prune 1 --files)"
  printf '%s' "$out" | grep -Fq 'deleted: .oms/artifacts/call/old.md' ||
    fail "prune --files should print deleted artifact"
  printf '%s' "$out" | grep -Fq 'deleted: .oms/artifacts/delegate/old.patch' ||
    fail "prune --files should print deleted patch"
  printf '%s' "$out" | grep -Fq 'deleted 2 orphan file(s)' ||
    fail "prune --files should print final delete count"
  assert_not_exists "$project/.oms/artifacts/call/old.md"
  assert_not_exists "$project/.oms/artifacts/delegate/old.patch"
  assert_file_contains "$project/.oms/artifacts/call/kept.md" "kept artifact"
  assert_file_contains "$project/.oms/artifacts/.gitignore" "keep me"
  assert_file_contains "$outside" "outside"
  [ -L "$project/.oms/artifacts/call/outside-link.md" ] ||
    fail "prune --files must not remove symlinks"
}

