test_consult_memory_is_opt_in() {
  local project="$TMP/consult-memory-opt-in"
  local home_dir="$project/home"
  local bin_dir="$project/bin"

  make_committed_repo "$project"
  mkdir -p "$home_dir" "$bin_dir"
  printf '%s\n' '#!/usr/bin/env bash' 'exit 0' > "$bin_dir/codex"
  chmod +x "$bin_dir/codex"
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" append --agent codex --text "Prefer narrow verification commands." >/dev/null

  # Shared memory holds prior conclusions; a consulted peer reads them only on
  # request, so the second opinion is not anchored on the first.
  HOME="$home_dir" PATH="$bin_dir:$PATH" OMS_AGENT=claude "$ROOT/scripts/consult.sh" \
    --repo "$project" --to codex --dry-run --quiet \
    --prompt "Assess this plan" >/dev/null
  if grep -R -Fq 'Prefer narrow verification commands.' "$project/.oms/artifacts/consult"; then
    fail "consult should omit shared memory by default"
  fi

  HOME="$home_dir" PATH="$bin_dir:$PATH" OMS_AGENT=claude "$ROOT/scripts/consult.sh" \
    --repo "$project" --to codex --memory --dry-run --quiet \
    --prompt "Assess this plan" >/dev/null
  grep -R -Fq 'Prefer narrow verification commands.' "$project/.oms/artifacts/consult" ||
    fail "consult --memory should attach shared memory"
}

test_claude_envelope_carries_stop_reason() {
  local project="$TMP/claude-envelope"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local artifact_dir="$project/artifacts"

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  # The stub answers in claude's print-mode JSON envelope and records its
  # argv, so the test pins both halves of the transport: the flags we send
  # and the parse of what comes back.
  cat > "$bin_dir/claude" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$@" > "$HOME/claude-argv"
cat > /dev/null
printf '{"type":"result","subtype":"success","is_error":false,"stop_reason":"end_turn","result":"Envelope answer body: pong.","usage":{"input_tokens":12,"output_tokens":3},"total_cost_usd":0.0123,"modelUsage":{"claude-opus-5":{"inputTokens":12,"outputTokens":3,"costUSD":0.0123}}}\n'
EOF
  chmod +x "$bin_dir/claude"

  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/agent-call.sh" \
    --repo "$project" --artifact-dir "$artifact_dir" --to claude \
    --prompt "Envelope probe" >/dev/null

  # The envelope is parsed back to text: the answer reads as prose, and the
  # facts plain text cannot carry — why the model stopped, which model was
  # actually served, what it cost — are kept as footer lines.
  assert_one_artifact_contains "$artifact_dir" 'claude-envelope-probe-*.md' \
    'stop-reason: provider=claude reason=end_turn subtype=success is_error=0'
  assert_one_artifact_contains "$artifact_dir" 'claude-envelope-probe-*.md' \
    'Envelope answer body: pong.'
  if grep -R -Fq '"type":"result"' "$artifact_dir"/claude-envelope-probe-*.md; then
    fail "the JSON envelope must be parsed away, not quoted as the answer"
  fi
  # A provider-default route is the one place the selected model says nothing;
  # the served model is what the envelope reports, and it rides the index row
  # so a later report can group by it without the artifact still existing.
  assert_one_artifact_contains "$artifact_dir" 'claude-envelope-probe-*.md' 'served model'
  assert_one_artifact_contains "$artifact_dir" 'claude-envelope-probe-*.md' 'claude-opus-5'
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "the index row must carry the served model, tokens, and cost"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
row = [r for r in rows if r.get("provider") == "claude"][-1]
assert row["served_model"] == "claude-opus-5", row
assert row["tokens"] == 15, row
assert abs(row["cost_usd"] - 0.0123) < 1e-9, row
PY
  grep -Fxq -- '--output-format' "$home_dir/claude-argv" ||
    fail "claude must be asked for the JSON envelope: $(cat "$home_dir/claude-argv")"
  # A read seat judges text and gets no MCP tool surface.
  grep -Fxq -- '--strict-mcp-config' "$home_dir/claude-argv" ||
    fail "a read seat must not inherit the user-scope MCP servers: $(cat "$home_dir/claude-argv")"
  # Four tools is the whole belt a judging seat carries.
  grep -Fxq -- 'Read,Grep,Glob,Bash' "$home_dir/claude-argv" ||
    fail "a read seat must carry the bounded tool belt: $(cat "$home_dir/claude-argv")"
  # Settings carry the hooks, and a judging seat inheriting the parent's hook
  # table gets the parent's resume block injected into a context stripped to
  # four tools -- and writes the parent's .oms while it judges.
  grep -Fxq -- '--setting-sources' "$home_dir/claude-argv" ||
    fail "a read seat must not inherit the user-scope hooks: $(cat "$home_dir/claude-argv")"
}

test_codex_jsonl_carries_stop_reason() {
  local project="$TMP/codex-jsonl"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local artifact_dir="$project/artifacts"
  local artifact quality

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  # A complete turn: answer item plus a closing turn.completed with usage.
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat > /dev/null
echo "ERROR rmcp::transport::worker: TRANSPORT-NOISE before the answer" >&2
printf '%s\n' '{"type":"thread.started","thread_id":"t1"}'
printf '%s\n' '{"type":"turn.started"}'
printf '%s\n' '{"type":"item.completed","item":{"id":"item_0","type":"agent_message","text":"JSONL answer body: pong."}}'
printf '%s\n' '{"type":"turn.completed","usage":{"input_tokens":10,"output_tokens":5}}'
EOF
  chmod +x "$bin_dir/codex"
  # The stream never names its model (probed live 2026-08-31: no event carries
  # one), so config.toml is useful inference, not transport-confirmed serving.
  # Real TOML parsing must accept single quotes and comments.
  printf "model = 'gpt-5.6-terra' # configured default\nmodel_reasoning_effort = 'high'\n" > "$home_dir/codex-config.toml"
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_CODEX_CONFIG="$home_dir/codex-config.toml" \
    "$ROOT/scripts/agent-call.sh" \
    --repo "$project" --artifact-dir "$artifact_dir" --to codex \
    --prompt "Jsonl probe" >/dev/null
  assert_one_artifact_contains "$artifact_dir" 'codex-jsonl-probe-*.md' \
    'stop-reason: provider=codex reason=turn_completed subtype=success is_error=0'
  assert_one_artifact_contains "$artifact_dir" 'codex-jsonl-probe-*.md' 'JSONL answer body: pong.'
  assert_one_artifact_contains "$artifact_dir" 'codex-jsonl-probe-*.md' 'tokens used'
  assert_one_artifact_contains "$artifact_dir" 'codex-jsonl-probe-*.md' 'configured model'
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "the codex index row must distinguish configured inference from a served model"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
row = [r for r in rows if r.get("provider") == "codex"][-1]
assert "served_model" not in row, row
assert row["configured_model"] == "gpt-5.6-terra", row
assert row["model_attribution"] == "configured-default", row
assert row["tokens"] == 15, row
PY
  if grep -R -Fq '"type":"item.completed"' "$artifact_dir"/codex-jsonl-probe-*.md; then
    fail "the JSONL events must be parsed away, not quoted as the answer"
  fi
  # A cleanly closed turn drops merged stderr chatter: four lines of plugin
  # MCP auth noise rode ahead of every live answer into the synthesis.
  if grep -R -Fq 'TRANSPORT-NOISE' "$artifact_dir"/codex-jsonl-probe-*.md; then
    fail "stderr chatter must not ride a successful answer"
  fi

  # A stream cut before turn.completed is codex's max_tokens: events arrived,
  # the turn never closed, and the answer only looks finished.
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat > /dev/null
printf '%s\n' '{"type":"thread.started","thread_id":"t2"}'
printf '%s\n' '{"type":"turn.started"}'
printf '%s\n' '{"type":"item.completed","item":{"id":"item_0","type":"agent_message","text":"A finished-looking sentence the stream cut right after."}}'
EOF
  chmod +x "$bin_dir/codex"
  rm -rf "$artifact_dir"
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/agent-call.sh" \
    --repo "$project" --artifact-dir "$artifact_dir" --to codex \
    --prompt "Cut probe" >/dev/null
  artifact="$(find "$artifact_dir" -type f -name 'codex-cut-probe-*.md' | head -n 1)"
  [ -n "$artifact" ] || fail "missing cut-probe artifact"
  grep -Fq 'reason=stream_truncated' "$artifact" ||
    fail "a cut stream must record its stop reason: $(cat "$artifact")"
  quality="$(python3 "$ROOT/scripts/lib/answer-quality.py" "$artifact")"
  [ "$quality" = "truncated" ] ||
    fail "a cut stream must classify as truncated (got $quality)"
}

