  assert_file_contains "$project/cleanup.out" "pruned: 1 stale git worktree registration(s)"
}

test_cleanup_removes_dead_lock_only() {
  local home_dir="$TMP/cleanup-lock-home"
  local runtime="$home_dir/runtime"
  # Locks live in a fixed per-user dir that no XDG variable moves; OMS_LOCK_DIR
  # is the one override, named here for the same reason as the doctor residue
  # fixture. See file-lock.sh.
  local lock_root="$home_dir/.cache/oh-my-setting/locks"
  local dead_lock="$lock_root/dead.lock"
  local live_lock="$lock_root/live.lock"

  # Build the dead lock through the real mkdir-path acquire rather than by hand.
  # The hand-made fixture is what let a gap hide: it produced a shape the
  # production path does not necessarily produce, so the test passed while the
  # scan missed every flock-path lock on the machine.
  mkdir -p "$lock_root"
  OMS_LOCK_DIR="$lock_root" OMS_LOCK_FORCE_MKDIR=1 bash -c "
    . '$ROOT/scripts/lib/file-lock.sh'
    oms_file_lock_mkdir_acquire /tmp/dead-state '$dead_lock' 5 dead-owner
  " >/dev/null 2>&1 || fail "the real acquire path should create a lock dir"
  [ -f "$dead_lock/pid" ] ||
    fail "the real acquire path must write a pid file the scan can read"
  printf '999999999\n' > "$dead_lock/pid"
  mkdir -p "$live_lock"
  printf '%s\n' "$$" > "$live_lock/pid"

  HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" XDG_RUNTIME_DIR="$runtime" \
    OMS_LOCK_DIR="$lock_root" \
    "$ROOT/scripts/cleanup.sh" --apply >"$home_dir/cleanup.out"
  assert_not_exists "$dead_lock"
  [ -d "$live_lock" ] || fail "cleanup should leave live lock dir"
  assert_file_contains "$home_dir/cleanup.out" "removed: $dead_lock (dead harness lock)"
}

test_agent_call_term_removes_tmp_prompt() {
  local project="$TMP/agent-call-term"
  local bin_dir="$project/bin"
  local tmp_dir="$project/tmp"
  local home_dir="$project/home"
  local pid
  local status=0

  mkdir -p "$project" "$bin_dir" "$tmp_dir" "$home_dir"
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat >/dev/null
printf '%s\n' "$$" > "$WORKER_PID_FILE"
while :; do sleep 1; done
EOF
  chmod +x "$bin_dir/codex"

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" TMPDIR="$tmp_dir" PATH="$bin_dir:/usr/bin:/bin" \
    WORKER_PID_FILE="$project/worker.pid" \
    "$ROOT/scripts/agent-call.sh" --to codex --repo "$project" --prompt "Wait for TERM" \
    >"$project/out" 2>"$project/err" &
  pid=$!
  for _ in $(seq 1 50); do
    [ "$(find "$tmp_dir" -type f | wc -l | tr -d ' ')" -gt 0 ] &&
      [ -s "$project/worker.pid" ] && break
    sleep 0.1
  done
  kill -TERM "$pid"
  wait "$pid" || status=$?
  [ "$status" -eq 143 ] || fail "agent-call TERM should exit 143, got $status"
  [ "$(find "$tmp_dir" -type f | wc -l | tr -d ' ')" = "0" ] ||
    fail "agent-call TERM should remove temp prompt file"
  [ -s "$project/worker.pid" ] || fail "fake provider should record its pid"
  if kill -0 "$(cat "$project/worker.pid")" 2>/dev/null; then
    fail "agent-call TERM should not orphan the provider process"
  fi
}

