# An out-of-band `oms auto-update install` used to leave the receipt saying
# auto_update=false, so the next `oms update` reconciled components from the
# receipt and silently uninstalled the timer it had just been asked to keep.
test_autoupdate_trigger_records_receipt_component() {
  local cron_file="$TMP/autoupdate-receipt.cron"
  local receipt="$TMP/autoupdate-receipt.json"
  local out

  python3 - "$receipt" "$ROOT" <<'PY'
import json, sys
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump({
        "schema": 2,
        "source_root": sys.argv[2],
        "commit": "0123456789abcdef0123456789abcdef01234567",
        "channel": "main",
        "version": "0.3.0",
        "profile": "custom",
        "ref": "main",
        "previous_commit": "",
        "link_mode": "symlink",
        "installed_at": "2026-07-12T00:00:00Z",
        "components": {
            "tools": False,
            "claude_hooks": True,
            "codex_plugin": False,
            "auto_update": False,
            "machine_snapshot": False,
            "slurm_snapshot": False,
        },
        "managed_targets": [".local/bin/oms"],
        "plugin": {"name": "oh-my-setting", "version": "0.1.0", "sha256": "test"},
    }, handle)
PY

  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron >/dev/null
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is True, row["components"]
assert row["component_modes"]["auto_update"] == "apply", row
assert row["components"]["claude_hooks"] is True, row["components"]
assert row["version"] == "0.3.0", row
PY

  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/uninstall-autoupdate.sh" >/dev/null
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is False, row["components"]
PY

  # --check-only records the chosen mode so a later update reinstalls check,
  # not the apply default; disabling keeps the mode for the next enable.
  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron --check-only >/dev/null
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is True, row["components"]
assert row["component_modes"]["auto_update"] == "check", row
PY
  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/uninstall-autoupdate.sh" >/dev/null
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is False, row["components"]
assert row["component_modes"]["auto_update"] == "check", row
PY

  # Dry-run previews the receipt write without performing it.
  out="$(OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron --dry-run)"
  printf '%s' "$out" | grep -Fq 'would record auto_update=true' ||
    fail "dry-run should preview the receipt write: $out"
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is False, row["components"]
PY

  # A checkout that does not own the receipt must not flip the flag.
  python3 - "$receipt" "$TMP" <<'PY'
import json, sys
with open(sys.argv[1], encoding="utf-8") as handle:
    row = json.load(handle)
row["source_root"] = sys.argv[2]
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump(row, handle)
PY
  out="$(OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron 2>&1)"
  printf '%s' "$out" | grep -Fq 'not recorded' ||
    fail "foreign-owner install should note the skipped receipt write: $out"
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is False, row["components"]
PY
}

# update.sh reinstalls the trigger on every run; before the mode lived in the
# receipt's component_modes, that reinstall silently downgraded an apply-mode
# timer to the check default.
test_update_preserves_auto_update_mode() {
  local project="$TMP/update-autoupdate-mode"
  local bin="$project/bin"
  local receipt="$TMP/update-autoupdate-mode-receipt.json"
  local marker="$project/mode-marker"
  local branch

  make_committed_repo "$project"
  mkdir -p "$project/scripts/lib" "$bin"
  cp "$ROOT/scripts/update.sh" "$project/scripts/update.sh"
  cp "$ROOT/scripts/lib/install-contract.sh" "$project/scripts/lib/install-contract.sh"
  cp "$ROOT/scripts/lib/install-lifecycle-lock.sh" "$project/scripts/lib/install-lifecycle-lock.sh"
  cp "$ROOT/scripts/lib/file-lock.sh" "$project/scripts/lib/file-lock.sh"
  cp "$ROOT/scripts/lib/poll.sh" "$project/scripts/lib/poll.sh"
  for script in link doctor uninstall-autoupdate install-tools install-claude-hooks install-mcp install-agy-plugin; do
    printf '#!/usr/bin/env bash\nexit 0\n' > "$project/scripts/$script.sh"
    chmod +x "$project/scripts/$script.sh"
  done
  cat > "$project/scripts/install-autoupdate.sh" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "${OH_MY_SETTING_AUTO_UPDATE_MODE:-unset}" > "$OMS_TEST_MODE_MARKER"
EOF
  chmod +x "$project/scripts/install-autoupdate.sh"
  cat > "$bin/git" <<'EOF'
#!/usr/bin/env bash
case "$*" in
  *' pull --ff-only') exit 0 ;;
esac
exec /usr/bin/git "$@"
EOF
  chmod +x "$bin/git"
  git -C "$project" add scripts bin
  git -C "$project" commit -qm "test: auto-update mode fixture"
  branch="$(git -C "$project" symbolic-ref --short HEAD)"
  git -C "$project" remote add origin "$project"
  git -C "$project" fetch -q origin "$branch"
  git -C "$project" branch --set-upstream-to="origin/$branch" "$branch" >/dev/null
  python3 - "$receipt" "$project" <<'PY'
import json, sys
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump({
        "schema": 2,
        "source_root": sys.argv[2],
        "commit": "0123456789abcdef0123456789abcdef01234567",
        "channel": "main",
        "version": "0.3.0",
        "profile": "custom",
        "ref": "main",
        "previous_commit": "",
        "link_mode": "symlink",
        "installed_at": "2026-07-12T00:00:00Z",
        "components": {
            "tools": False,
            "claude_hooks": False,
            "codex_plugin": False,
            "auto_update": True,
            "machine_snapshot": False,
            "slurm_snapshot": False,
        },
        "component_modes": {
            "auto_update": "apply",
            "machine_snapshot": "0",
            "slurm_snapshot": "0",
        },
        "managed_targets": [".local/bin/oms"],
        "plugin": {"name": "oh-my-setting", "version": "0.1.0", "sha256": "test"},
    }, handle)
PY

  env -u OH_MY_SETTING_AUTO_UPDATE -u OH_MY_SETTING_AUTO_UPDATE_MODE \
    PATH="$bin:/usr/bin:/bin" OMS_INSTALL_RECEIPT="$receipt" \
    OMS_TEST_MODE_MARKER="$marker" OH_MY_SETTING_CLAUDE_HOOKS=0 \
    OH_MY_SETTING_CODEX_PLUGIN=0 \
    "$project/scripts/update.sh" --no-doctor >/dev/null
  [ -f "$marker" ] || fail "update should reinstall the recorded auto-update trigger"
  grep -Fxq apply "$marker" ||
    fail "update downgraded the recorded apply mode: $(cat "$marker")"
}

test_check_gate_hard_fails_without_shellcheck() {
  # The gate must FAIL (not silently skip) when shellcheck is absent — the
  # exact false-confidence that hid a session of red CI.
  local out
  # Point the gate at a nonexistent shellcheck binary so it hits the
  # missing-tool path deterministically (no PATH surgery, no recursion).
  # --lint-only is passed explicitly: a gate with lint disabled has no reason to
  # look for shellcheck, and when the split was an inherited environment variable
  # CI's smoke job turned this test into a full recursive gate run instead of the
  # fast failure the line above promises.
  out="$(OMS_SHELLCHECK_BIN=__oms_absent_shellcheck__ \
    "$ROOT/scripts/check.sh" --lint-only 2>&1)" && \
    fail "check.sh must exit nonzero when shellcheck is missing"
  printf '%s' "$out" | grep -Fq "shellcheck is not installed" ||
    fail "check.sh missing-tool message absent: $out"
}

test_check_gate_is_hermetic_to_hook_git_env() {
  # Git exports GIT_DIR to hooks; from a linked worktree it is absolute and
  # redirects every fixture's git calls into the enclosing checkout — a
  # pre-push from a worktree rewrote the checkout with fixture commits and
  # failed autonomy-plan-run on the enclosing tree's dirtiness. The gate
  # must drop the inherited git context before any stage runs.
  grep -Fq 'unset GIT_DIR GIT_WORK_TREE GIT_COMMON_DIR GIT_INDEX_FILE' \
    "$ROOT/scripts/check.sh" ||
    fail "check.sh must unset the inherited hook git env (GIT_DIR family)"
}

# link.sh ignored its arguments and ran. `link.sh --help` therefore relinked a
# live install and moved canonical ownership to whichever checkout was asked for
# help — the receipt names an owner, so that is a transfer, not a no-op. It
# happened during this session's own analysis, cost 78 stray backup symlinks and
# a doctor: failed, and nothing would have caught it. Every entrypoint that
# writes install state must answer --help and refuse anything else.
test_state_writing_entrypoints_reject_unknown_arguments() {
  local script
  local out

  for script in link.sh install-hooks.sh check-python.sh skill-doctor.sh; do
    out="$("$ROOT/scripts/$script" --help 2>&1)" ||
      fail "$script --help should exit 0: $out"
    printf '%s' "$out" | grep -Fq "usage: $script" ||
      fail "$script --help should print its usage: $out"
    if out="$("$ROOT/scripts/$script" --definitely-not-a-flag 2>&1)"; then
      fail "$script must refuse an unknown argument instead of running: $out"
    fi
  done

  # check-bash32 takes file arguments, so a flag must be answered before the
  # loop treats it as a path — it exited 127 trying to parse a file named --help.
  out="$("$ROOT/scripts/check-bash32.sh" --help 2>&1)" ||
    fail "check-bash32.sh --help should exit 0: $out"
  printf '%s' "$out" | grep -Fq 'usage: check-bash32.sh' ||
    fail "check-bash32.sh should print usage: $out"
  if out="$("$ROOT/scripts/check-bash32.sh" --definitely-not-a-flag 2>&1)"; then
    fail "check-bash32.sh must refuse an unknown option: $out"
  fi
}

test_bash32_gate_uses_the_requested_parser() {
  local parser="$TMP/bash32-parser"
  local log="$TMP/bash32-parser.log"

  cat > "$parser" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$OMS_BASH32_LOG"
EOF
  chmod +x "$parser"

  OMS_BASH32_BIN="$parser" OMS_BASH32_LOG="$log" \
    "$ROOT/scripts/check-bash32.sh" >/dev/null
  assert_file_contains "$log" "-n $ROOT/install.sh"
  assert_file_contains "$log" "-n $ROOT/scripts/lib/peer-common.sh"
}

# Bash 3.2 cannot parse a here-document inside $( ) whose body holds an odd
# number of apostrophes, even behind a quoted delimiter. It shipped: a prose
# "operator's" inside an inline Python heredoc made peer-common.sh unparseable,
# so every peer tool died on macOS while Linux stayed green. Nothing but a real
# 3.2 parser sees it, and the only one in CI is one job away from deletion.
test_bash32_gate_rejects_an_apostrophe_heredoc_in_substitution() {
  local bad="$TMP/bash32-heredoc-bad.sh"
  local good="$TMP/bash32-heredoc-good.sh"
  local out

  cat > "$bad" <<'EOF'
#!/usr/bin/env bash
f() {
  v="$(python3 - <<'PY'
# the fix is the operator's problem
print("x")
PY
)"
}
EOF
  # Same heredoc, apostrophes balanced: this one is legal and must stay legal.
  cat > "$good" <<'EOF'
#!/usr/bin/env bash
f() {
  v="$(python3 - <<'PY'
# the fix is the operator's problem, and the operator's alone
print("x")
PY
)"
}
EOF

  if out="$("$ROOT/scripts/check-bash32.sh" "$bad" 2>&1)"; then
    fail "the gate must reject an odd-apostrophe heredoc inside \$( ): $out"
  fi
  printf '%s' "$out" | grep -Fq 'heredoc <<PY inside $( )' ||
    fail "the gate must name the offending heredoc: $out"

  "$ROOT/scripts/check-bash32.sh" "$good" >/dev/null 2>&1 ||
    fail "balanced apostrophes must still pass"

  # Even apostrophes can still hide a paren between them: the 3.2 scanner
  # skips the ")" inside the quote span and the file fails at EOF. This is
  # the exact shape that kept every macOS CI leg red while the old parity
  # rule stayed green locally.
  local sneaky="$TMP/bash32-heredoc-sneaky.sh"
  cat > "$sneaky" <<'EOF'
#!/usr/bin/env bash
f() {
  v="$(python3 - <<'PY'
# identical in fail-ledger.sh (record's repeat count) and in gc.sh's sweep
print("x")
PY
)"
}
EOF
  if out="$("$ROOT/scripts/check-bash32.sh" "$sneaky" 2>&1)"; then
    fail "the gate must reject a paren hidden inside an even quote span: $out"
  fi
  printf '%s' "$out" | grep -Fq 'paren drift: +1' ||
    fail "the gate must report the paren drift: $out"
}

# check.sh exits at the first failing stage. CI runs lint and tests as separate
# jobs so one shellcheck nit cannot suppress every test result, which only
# works if each half can run without the other.
test_check_gate_splits_lint_from_tests() {
  local out
  local shellcheck_stub="$TMP/check-split-shellcheck"

  # This is a mode-routing contract, not a second shellcheck correctness run.
  # The top-level lint gate checks every file; repeating the real linter here
  # added roughly 45 seconds to one scripts-smoke shard with no new evidence.
  cat > "$shellcheck_stub" <<'EOF'
#!/usr/bin/env bash
exit 0
EOF
  chmod +x "$shellcheck_stub"

  out="$(cd "$ROOT" && OMS_SHELLCHECK_BIN="$shellcheck_stub" \
    bash scripts/check.sh --lint-only 2>&1)" ||
    fail "lint-only gate should pass: $out"
  printf '%s' "$out" | grep -Fq 'ok: shellcheck' ||
    fail "lint-only gate must run shellcheck: $out"
  printf '%s' "$out" | grep -Fq 'check: ok (lint only)' ||
    fail "lint-only gate must say what it skipped: $out"
  if printf '%s' "$out" | grep -Fq 'ok: context-core'; then
    fail "lint-only gate must not run the test suites: $out"
  fi

  if out="$(cd "$ROOT" && bash scripts/check.sh --no-lint --lint-only 2>&1)"; then
    fail "a gate that runs nothing must be refused: $out"
  fi
  printf '%s' "$out" | grep -Fq 'leave nothing to run' ||
    fail "refusal must name the cause: $out"
}

# Every .sh here is linted; the Python helpers had nothing, and one of them now
# decides what the installer may delete.
test_python_helpers_are_syntax_checked() {
  local out

  out="$(cd "$ROOT" && bash scripts/check-python.sh 2>&1)" ||
    fail "python syntax gate should pass: $out"
  printf '%s' "$out" | grep -Eq 'python-syntax: ok \([0-9]+ files\)' ||
    fail "python syntax gate must report what it checked: $out"
}

test_ci_status_reports_conclusion() {
  local d="$TMP/ci-status" out
  mkdir -p "$d/bin"
  # Stub gh: a failed latest run -> ci-status must exit nonzero.
  cat > "$d/bin/gh" <<'EOF'
#!/usr/bin/env bash
echo '[{"status":"completed","conclusion":"failure","workflowName":"test","url":"http://x"}]'
EOF
  chmod +x "$d/bin/gh"
  out="$(OMS_GH_BIN="$d/bin/gh" "$ROOT/scripts/ci-status.sh" main 2>&1)" && \
    fail "ci-status must exit nonzero on a failed run"
  printf '%s' "$out" | grep -Fq "failure" || fail "ci-status missing conclusion: $out"

  # A successful latest run -> exit 0.
  cat > "$d/bin/gh" <<'EOF'
#!/usr/bin/env bash
echo '[{"status":"completed","conclusion":"success","workflowName":"test","url":"http://x"}]'
EOF
  OMS_GH_BIN="$d/bin/gh" "$ROOT/scripts/ci-status.sh" main >/dev/null 2>&1 ||
    fail "ci-status should exit 0 on a successful run"

  # Missing gh -> exit 2 (clear, not a silent pass).
  if OMS_GH_BIN=__oms_absent_gh__ "$ROOT/scripts/ci-status.sh" main >/dev/null 2>&1; then
    fail "ci-status should fail when gh is absent"
  fi
}

test_install_hooks_writes_pre_push() {
  local repo="$TMP/install-hooks"
  mkdir -p "$repo/scripts"
  git -C "$repo" init -b main >/dev/null
  cp "$ROOT/scripts/install-hooks.sh" "$repo/scripts/install-hooks.sh"
  ( cd "$repo" && bash scripts/install-hooks.sh >/dev/null ) || fail "install-hooks failed"
  [ -x "$repo/.git/hooks/pre-push" ] || fail "pre-push hook not installed/executable"
  grep -Fq 'scripts/check.sh' "$repo/.git/hooks/pre-push" || fail "hook does not call check.sh"

  ( cd "$repo" && bash scripts/install-hooks.sh --quick >/dev/null ) ||
    fail "install-hooks --quick failed"
  grep -Fq 'scripts/pre-push-check.sh' "$repo/.git/hooks/pre-push" ||
    fail "quick hook does not route through pre-push-check.sh"
  grep -Fq 'full GitHub Actions gate' "$repo/.git/hooks/pre-push" ||
    fail "quick hook must say that its local result is partial"
}

test_pre_push_quick_gate_uses_the_exact_push_range() {
  local repo="$TMP/pre-push-quick"
  local first second zero

  mkdir -p "$repo/scripts"
  git -C "$repo" init -b main >/dev/null
  git -C "$repo" config user.email test@example.com
  git -C "$repo" config user.name Test
  cp "$ROOT/scripts/pre-push-check.sh" "$repo/scripts/pre-push-check.sh"
  cat > "$repo/scripts/check.sh" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" > "$OMS_TEST_CHECK_ARGS"
EOF
  chmod +x "$repo/scripts/check.sh" "$repo/scripts/pre-push-check.sh"
  printf 'one\n' > "$repo/tracked.txt"
  git -C "$repo" add scripts tracked.txt
  git -C "$repo" commit -m first >/dev/null
  first="$(git -C "$repo" rev-parse HEAD)"
  printf 'two\n' > "$repo/tracked.txt"
  git -C "$repo" add tracked.txt
  git -C "$repo" commit -m second >/dev/null
  second="$(git -C "$repo" rev-parse HEAD)"

  printf 'refs/heads/main %s refs/heads/main %s\n' "$second" "$first" |
    (cd "$repo" && OMS_TEST_CHECK_ARGS="$repo/check.args" \
      bash scripts/pre-push-check.sh origin example.invalid >/dev/null)
  [ "$(cat "$repo/check.args")" = "--quick --changed-from $first --changed-to $second" ] ||
    fail "quick pre-push did not preserve the exact update range: $(cat "$repo/check.args")"

  zero=0000000000000000000000000000000000000000
  rm -f "$repo/check.args"
  printf 'refs/heads/old %s refs/heads/old %s\n' "$zero" "$second" |
    (cd "$repo" && OMS_TEST_CHECK_ARGS="$repo/check.args" \
      bash scripts/pre-push-check.sh origin example.invalid >/dev/null)
  [ ! -e "$repo/check.args" ] || fail "a deletion-only push should not run a gate"
}

test_install_skills_detects_name_mismatch() {
  local repo="$TMP/install-skills-mismatch"

  mkdir -p "$repo/custom-skills/demo" "$repo/scripts"
  cp "$ROOT/scripts/install-skills.sh" "$repo/scripts/install-skills.sh"
