  cat > "$repo/skills.manifest.json" <<'EOF'
{
  "skills": [
    {
      "name": "expected-name",
      "source": "custom-skills/demo",
      "enabled": true
    }
  ]
}
EOF
  cat > "$repo/custom-skills/demo/SKILL.md" <<'EOF'
