test_session_handoff_blocks_sensitive_digest() {
  local home="$TMP/sh-sensitive-home"
  local cwd="/proj/sens-app"
  local proj="$home/projects/-proj-sens-app"
  local SH="$ROOT/scripts/session-handoff.sh"

  mkdir -p "$proj"
  # A user turn carrying a credential-shaped value, assembled at runtime so the
  # test source itself stays scrubber-clean (split literal; plain var name).
  local vector="AK""IAIOSFODNN7EXAMPLE"
  printf '{"type":"user","message":{"role":"user","content":"deploy with %s"}}\n' \
    "$vector" > "$proj/sess.jsonl"
  printf '{"type":"user","message":{"role":"user","content":"then roll it back"}}\n' \
    >> "$proj/sess.jsonl"

  # Default: refuse to write, nonzero exit, no file.
  if ( OMS_CLAUDE_HOME="$home" "$SH" capture --agent claude --cwd "$cwd" \
       --out "$home/d.md" >/dev/null 2>&1 ); then
    fail "sensitive handoff digest must be refused by default"
  fi
  [ -f "$home/d.md" ] && fail "refused digest must not be left on disk"

  # --allow-sensitive: writes it.
  OMS_CLAUDE_HOME="$home" "$SH" capture --agent claude --cwd "$cwd" \
    --out "$home/d.md" --allow-sensitive >/dev/null 2>&1 ||
    fail "--allow-sensitive should write the digest"
  [ -f "$home/d.md" ] || fail "--allow-sensitive digest not written"

  # Regression: a CLEAN transcript must NOT self-block just because the harness
  # writes an absolute home path into the digest header. --cwd under /home/ would
  # trip the scrubber if the whole digest (not just user content) were scanned.
  # Build the /home cwd at runtime so this test source stays scrubber-clean,
  # and place the session under that cwd's encoded project dir.
  local hcwd="/ho""me/researcher/proj"
  local hdir
  hdir="$home/projects/$(printf '%s' "$hcwd" | sed 's#/#-#g')"
  mkdir -p "$hdir"
  {
    printf '{"type":"user","message":{"role":"user","content":"refactor the loader"}}\n'
    printf '{"type":"user","message":{"role":"user","content":"then add a test"}}\n'
  } > "$hdir/h.jsonl"
  OMS_CLAUDE_HOME="$home" "$SH" capture --agent claude --cwd "$hcwd" \
    --out "$home/clean.md" >/dev/null 2>&1 ||
    fail "clean transcript must not self-block on a /home header path"
  [ -f "$home/clean.md" ] || fail "clean digest with /home cwd not written"

  # Machine tier in USER content (a /home path in a turn) no longer refuses the
  # digest: it is normalized and written. This was the PreCompact killer — on
  # Linux every real transcript cites /home paths, so auto-capture always
  # refused and .oms/handoffs stayed empty.
  local pdir="$home/projects/-proj-pathy-app"
  mkdir -p "$pdir"
  printf '{"type":"user","message":{"role":"user","content":"fix /ho%s/researcher/proj/loader.py"}}\n' \
    "me" > "$pdir/p.jsonl"
  printf '{"type":"user","message":{"role":"user","content":"then run the loader tests"}}\n' \
    >> "$pdir/p.jsonl"
  OMS_CLAUDE_HOME="$home" "$SH" capture --agent claude --cwd "/proj/pathy-app" \
    --out "$home/pathy.md" >/dev/null 2>&1 ||
    fail "machine-tier user content must capture, not refuse"
  assert_file_contains "$home/pathy.md" 'fix ~/proj/loader.py'
  if grep -q '/ho''me/researcher' "$home/pathy.md"; then
    fail "raw home path must not survive into the digest body"
  fi
}

test_session_handoff_claude_digest() {
  local home="$TMP/sh-claude-home"
  local cwd="/proj/demo-app"
  local proj="$home/projects/-proj-demo-app"
  local sess="$proj/aaaaaaaa-1111-2222-3333-444444444444.jsonl"
  local out

  mkdir -p "$proj"
  {
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"<local-command-caveat>noise</local-command-caveat>"}}'
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"build the widget feature"}}'
    printf '%s\n' '{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"working on it"},{"type":"tool_use","name":"Edit","input":{"file_path":"/proj/demo-app/widget.py"}}]}}'
    printf '%s\n' '{"type":"user","message":{"role":"user","content":[{"type":"tool_result","content":"ok"}]}}'
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"now add tests"}}'
    printf '%s\n' '{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"done: widget plus tests"}]}}'
  } > "$sess"

  out="$(OMS_CLAUDE_HOME="$home" "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd" --out "$home/digest.md" 2>/dev/null)"
  [ -f "$out" ] || fail "claude handoff digest not written"
  assert_file_contains "$out" "build the widget feature"
  assert_file_contains "$out" "now add tests"
  assert_file_contains "$out" "widget.py (1 edits)"
  assert_file_contains "$out" "done: widget plus tests"
  # Slash-command caveat noise must not become the goal.
  if grep -Fq "local-command-caveat" "$out"; then
    fail "claude digest leaked command-caveat noise"
  fi
  # tool_result-only turns are not real user prose.
  if grep -Fq '"tool_result"' "$out"; then
    fail "claude digest leaked tool_result content"
  fi
}

test_session_handoff_carries_resume_contract_and_dissents() {
  local home="$TMP/sh-resume-home"
  local cwd="$TMP/sh-resume-proj"
  local run="20260611T000000Z-77"
  local proj sess out

  # A repo with an active packet carrying a Verify contract and a review
  # round that ended split: both must ride the digest.
  mkdir -p "$cwd/.oms/task" "$cwd/.oms/artifacts/review"
  printf '# Task\n\n## Verify\n\nbash scripts/check.sh --focused-only\n\n## Goal\n\nship\n' \
    > "$cwd/.oms/task/current.md"
  printf '# codex review\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$cwd/.oms/artifacts/review/codex-x-$run.md"
  printf '# claude review\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' \
    > "$cwd/.oms/artifacts/review/claude-x-$run.md"

  proj="$home/projects/$(printf '%s' "$cwd" | tr -c 'A-Za-z0-9.' '-')"
  sess="$proj/bbbbbbbb-1111-2222-3333-444444444444.jsonl"
  mkdir -p "$proj"
  {
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"continue the feature"}}'
    printf '%s\n' '{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"paused at review"}]}}'
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"resume where it stopped"}}'
  } > "$sess"

  out="$(OMS_CLAUDE_HOME="$home" "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd" --out "$home/digest.md" 2>/dev/null)"
  [ -f "$out" ] || fail "resume-contract digest not written"
  assert_file_contains "$out" "## Resume contract"
  assert_file_contains "$out" "bash scripts/check.sh --focused-only"
  assert_file_contains "$out" "## Open dissents"
  assert_file_contains "$out" "codex: pass"
  assert_file_contains "$out" "claude: fail"
}

test_session_handoff_dissents_from_typed_outcome() {
  local home="$TMP/sh-typed-home"
  local cwd="$TMP/sh-typed-proj"
  local proj sess out

  # Typed review-outcome rows and NO review artifacts: the dissent block must
  # come from the typed rows, not from re-parsing rendered Markdown, and it
  # must select the latest UNRESOLVED genuine split — a resolved split (an
  # artifact-resolution receipt names its event) and an incomplete round
  # (overall=2) are not open dissents, and a later non-split gate must not
  # bury an older split that nobody acknowledged.
  mkdir -p "$cwd/.oms/artifacts"
  python3 - "$cwd/.oms/artifacts/index.jsonl" <<'PY'
import json, sys

rows = [
    # A resolved split: its receipt below retires it.
    {"schema": 1, "kind": "review-outcome", "provider": "local", "exit": 1,
     "event_id": "evt_resolved_split",
     "review": {"overall": 1, "gate_verify_exit": 0, "seats": [
         {"provider": "codex", "verdict": "pass", "confidence": 0.9, "round": 1},
         {"provider": "claude", "verdict": "fail", "confidence": None, "round": 1}]}},
    {"schema": 1, "kind": "artifact-resolution", "provider": "local", "exit": 0,
     "event_id": "evt_receipt", "resolves_event_id": "evt_resolved_split"},
    # The open split this digest must carry.
    {"schema": 1, "kind": "review-outcome", "provider": "local", "exit": 1,
     "event_id": "evt_open_split",
     "review": {"overall": 1, "gate_verify_exit": 0, "seats": [
         {"provider": "codex", "verdict": "pass", "confidence": 0.8, "round": 2},
         {"provider": "claude", "verdict": "fail", "confidence": None, "round": 2}]}},
    # An incomplete later round: pass+fail+incomplete is overall=2, not a split.
    {"schema": 1, "kind": "review-outcome", "provider": "local", "exit": 2,
     "event_id": "evt_incomplete",
     "review": {"overall": 2, "gate_verify_exit": 0, "seats": [
         {"provider": "codex", "verdict": "pass", "confidence": 0.7, "round": 1},
         {"provider": "claude", "verdict": "fail", "confidence": None, "round": 1},
         {"provider": "antigravity", "verdict": "incomplete", "confidence": None, "round": 1}]}},
    # A later all-pass gate must not bury the unacknowledged split above.
    {"schema": 1, "kind": "review-outcome", "provider": "local", "exit": 0,
     "event_id": "evt_green",
     "review": {"overall": 0, "gate_verify_exit": 0, "seats": [
         {"provider": "codex", "verdict": "pass", "confidence": 0.9, "round": 1}]}},
]
with open(sys.argv[1], "w", encoding="utf-8") as fh:
    for row in rows:
        fh.write(json.dumps(row) + "\n")
PY
  proj="$home/projects/$(printf '%s' "$cwd" | tr -c 'A-Za-z0-9.' '-')"
  sess="$proj/cccccccc-1111-2222-3333-444444444444.jsonl"
  mkdir -p "$proj"
  {
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"continue the feature"}}'
    printf '%s\n' '{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"paused at review"}]}}'
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"resume where it stopped"}}'
  } > "$sess"

  out="$(OMS_CLAUDE_HOME="$home" "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd" --out "$home/digest.md" 2>/dev/null)"
  [ -f "$out" ] || fail "typed-dissent digest not written"
  assert_file_contains "$out" "## Open dissents"
  assert_file_contains "$out" "codex: pass (confidence 0.8)"
  assert_file_contains "$out" "claude: fail"
  # The selected split names its event and the exact resolution entrance.
  assert_file_contains "$out" "evt_open_split"
  assert_file_contains "$out" "artifact-index"
  if grep -Fq "evt_resolved_split" "$out"; then
    fail "a resolved split reached the digest despite its receipt"
  fi
  if grep -Fq "confidence 0.9" "$out"; then
    fail "a resolved or non-split row's seats reached the digest"
  fi
  if grep -Fq "antigravity: incomplete" "$out"; then
    fail "an incomplete round was rendered as an open split"
  fi
}

