test_file_lock_dir_is_stable_across_xdg() {
  local baseline
  local with_xdg
  local var

  # OMS_LOCK_DIR is the sanctioned override and check.sh exports it, so it has
  # to come off first or every reading below is the same constant.
  baseline="$(env -u OMS_LOCK_DIR -u XDG_RUNTIME_DIR -u XDG_CACHE_HOME \
    bash -c ". '$ROOT/scripts/lib/file-lock.sh'; oms_file_lock_dir")"

  # Two processes holding the same state file must agree on the lock path. A
  # desktop shell and the auto-update systemd timer disagree about every XDG
  # variable, so keying the lock dir on one lets both enter the same critical
  # section — the failure this test exists to prevent, once introduced through
  # XDG_RUNTIME_DIR and once through XDG_CACHE_HOME.
  for var in XDG_RUNTIME_DIR XDG_CACHE_HOME; do
    with_xdg="$(env -u OMS_LOCK_DIR "$var=$TMP/xdg-$var" \
      bash -c ". '$ROOT/scripts/lib/file-lock.sh'; oms_file_lock_dir")"
    [ "$with_xdg" = "$baseline" ] ||
      fail "lock dir must not depend on $var ($with_xdg vs $baseline)"
  done

  # The one variable that may move it, so a test run can stay hermetic.
  with_xdg="$(OMS_LOCK_DIR="$TMP/explicit-locks" \
    bash -c ". '$ROOT/scripts/lib/file-lock.sh'; oms_file_lock_dir")"
  [ "$with_xdg" = "$TMP/explicit-locks" ] ||
    fail "OMS_LOCK_DIR must select the lock dir: $with_xdg"
}

# A copy install puts a real file at ~/.local/bin/oms, so the dispatcher cannot
# find its checkout by following a link and reads the receipt instead. That
# receipt has to be validated the way the rest of the harness validates it, and
# when nothing resolves the failure must name the broken contract — falling
# through reports a missing file for whatever subcommand was asked for, which
# sends the reader after entirely the wrong thing.
test_oms_dispatcher_refuses_an_unusable_receipt() {
  local dir="$TMP/oms-dispatch"
  local receipt="$dir/install.json"
  local out

  mkdir -p "$dir/bin"
  cp "$ROOT/scripts/oms" "$dir/bin/oms"

  # No receipt at all.
  if out="$(OMS_INSTALL_RECEIPT="$dir/absent.json" "$dir/bin/oms" list 2>&1)"; then
    fail "oms must not dispatch with no checkout and no receipt: $out"
  fi
  printf '%s' "$out" | grep -Fq 'cannot locate its checkout' ||
    fail "oms must name the broken contract: $out"

  # A pre-v0.4 receipt names a root but not under the contract this reads.
  printf '{"schema": 1, "source_root": "%s"}\n' "$ROOT" > "$receipt"
  if out="$(OMS_INSTALL_RECEIPT="$receipt" "$dir/bin/oms" list 2>&1)"; then
    fail "oms must not trust a schema-1 receipt: $out"
  fi

  # The supported shape resolves and dispatches.
  printf '{"schema": 2, "source_root": "%s"}\n' "$ROOT" > "$receipt"
  out="$(OMS_INSTALL_RECEIPT="$receipt" "$dir/bin/oms" list 2>&1)" ||
    fail "oms must dispatch through a schema-2 receipt: $out"
  printf '%s' "$out" | grep -Fq plan-run ||
    fail "receipt dispatch did not reach the real tool list: $out"
}

# Two unrelated families are both named index.jsonl: artifacts/index.jsonl is
# read by `kind`, runs/index.jsonl by `id`. Keying the contract on the basename
# demanded `kind` from every run-capsule row, so a healthy runs index was
# reported invalid by the tool that certifies state validity.
test_validate_separates_the_two_index_families() {
  local project="$TMP/validate-index"
  local out

  mkdir -p "$project/.oms/runs" "$project/.oms/artifacts"
  printf '{"id": "20260101T000000Z-1", "ts": "2026-01-01T00:00:00Z", "exit": 0}\n' \
    > "$project/.oms/runs/index.jsonl"
  printf '{"kind": "artifact-resolution", "operation_id": "o", "artifact_id": "a"}\n' \
    > "$project/.oms/artifacts/index.jsonl"

  out="$("$ROOT/scripts/run.sh" validate --dir "$project/.oms" 2>&1)" ||
    fail "both index families should validate: $out"
  printf '%s' "$out" | grep -Fq '0 with errors or invalid rows' ||
    fail "a run-capsule index must not be reported invalid: $out"

  # Each family still enforces its own required field.
  printf '{"ts": "2026-01-01T00:00:00Z"}\n' > "$project/.oms/runs/index.jsonl"
  if out="$("$ROOT/scripts/run.sh" validate --dir "$project/.oms" 2>&1)"; then
    fail "a runs index row without an id must be rejected: $out"
  fi
  printf '%s' "$out" | grep -Fq "missing required field 'id'" ||
    fail "the runs index must be checked for id: $out"

  printf '{"id": "20260101T000000Z-1"}\n' > "$project/.oms/runs/index.jsonl"
  printf '{"operation_id": "o"}\n' > "$project/.oms/artifacts/index.jsonl"
  if out="$("$ROOT/scripts/run.sh" validate --dir "$project/.oms" 2>&1)"; then
    fail "an artifact index row without a kind must be rejected: $out"
  fi
  printf '%s' "$out" | grep -Fq "missing required field 'kind'" ||
    fail "the artifact index must still be checked for kind: $out"
}

test_oms_run_link_records_calling_agent() {
  local d="$TMP/oms-run-agent"
  local SH="$ROOT/scripts/run.sh"
  local id

  mkdir -p "$d"
  id="$(cd "$d" && OMS_AGENT=codex "$SH" new 2>/dev/null)"
  (cd "$d" && "$SH" show "$id" 2>/dev/null | grep -Fq "agent=codex") ||
    fail "spine rows should record the calling agent from OMS_AGENT"

  # The generic fallback is not an identity and must not be stamped.
  id="$(cd "$d" && env -u OMS_AGENT -u CLAUDECODE -u CLAUDE_CODE_ENTRYPOINT -u CODEX_SANDBOX "$SH" new 2>/dev/null)"
  if (cd "$d" && "$SH" show "$id" 2>/dev/null | grep -Fq "agent="); then
    fail "spine rows should omit the agent field when no identity is known"
  fi
}

test_agent_plan_normalizes_provider() {
  local project="$TMP/plan-provider"

  make_committed_repo "$project"
  (cd "$project" && "$ROOT/scripts/agent-plan.sh" add --id t1 --title "one" >/dev/null)
  (cd "$project" && "$ROOT/scripts/agent-plan.sh" claim --id t1 --provider agy >/dev/null)
  python3 -c '
import json, sys
d = json.load(open(sys.argv[1]))
sys.exit(0 if d["tasks"]["t1"]["provider"] == "antigravity" else 1)
' "$project/.oms/plan/tasks.json" || fail "claim should canonicalize agy to antigravity"

  (cd "$project" && "$ROOT/scripts/agent-plan.sh" add --id t2 --title "two" >/dev/null)
  if (cd "$project" && "$ROOT/scripts/agent-plan.sh" claim --id t2 --provider gpt5 >/dev/null 2>&1); then
    fail "claim must reject an unknown provider name"
  fi
}

test_oms_run_current_pointer_joins_and_expires() {
  local d="$TMP/oms-run-current"
  local SH="$ROOT/scripts/run.sh"
  local id
  local cur

  mkdir -p "$d"
  id="$(cd "$d" && env -u OMS_RUN_ID "$SH" new 2>/dev/null)"
  cur="$(cd "$d" && env -u OMS_RUN_ID "$SH" current 2>/dev/null)" ||
    fail "current should resolve the freshly minted run"
  [ "$cur" = "$id" ] || fail "current should print the freshly minted run id"

  # A second process with no OMS_RUN_ID in its env joins via CURRENT.
  (cd "$d" && env -u OMS_RUN_ID "$SH" link --tool probe --event join >/dev/null 2>&1) ||
    fail "link should fall back to the fresh CURRENT pointer"
  (cd "$d" && "$SH" show "$id" 2>/dev/null | grep -Fq "join") ||
    fail "the fallback link should join the minted run"

  # A stale pointer must not misjoin later work.
  awk '{print $1, $2 - 999999}' "$d/.oms/runs/CURRENT" > "$d/.oms/runs/CURRENT.tmp"
  mv "$d/.oms/runs/CURRENT.tmp" "$d/.oms/runs/CURRENT"
  if (cd "$d" && env -u OMS_RUN_ID "$SH" current >/dev/null 2>&1); then
    fail "a stale CURRENT pointer must expire"
  fi
  if (cd "$d" && env -u OMS_RUN_ID "$SH" link --tool probe --event late >/dev/null 2>&1); then
    fail "link must not join through a stale CURRENT pointer"
  fi
}

test_oms_dispatcher_lists_and_dispatches() {
  local bin="$TMP/oms-dispatch-bin"
  local d="$TMP/oms-dispatch-repo"
  local out

  mkdir -p "$bin" "$d"
  ln -sfn "$ROOT/scripts/oms" "$bin/oms"

  # Capture first: grep -q on a live pipe SIGPIPEs the dispatcher under
  # pipefail as soon as the match is found.
  out="$("$bin/oms" list)" || fail "oms list should succeed"
  printf '%s' "$out" | grep -Eq '^run-ledger ' || fail "oms list should include run-ledger"
  printf '%s' "$out" | grep -Eq '^agent-run ' || fail "oms list should include agent-run"
  for public in agent-events agent-supervisor approval-inbox autopilot draft-pr \
    execution-profile herdr-adapter open-in ops-cockpit otel-export semantic-eval; do
    printf '%s\n' "$out" | grep -Eq "^${public} " ||
      fail "oms list should include new public tool: $public"
    "$bin/oms" "$public" --help >/dev/null 2>&1 ||
      fail "oms should dispatch new public tool: $public"
  done
  for hidden in skill-router turn-guard check-bash32 install-tools multi-agent-ask multi-agent-review multi-agent-delegate \
    generate-slurm-reference generate-slurm-skill github-source import-agent-result install-autoupdate run-capsule tool-lock uninstall-autoupdate write-machine-snapshot; do
    if printf '%s' "$out" | grep -Eq "^${hidden} "; then
      fail "oms list should hide internal/deprecated tool: $hidden"
    fi
  done
  printf '%s' "$out" | grep -Eq '^snapshot ' || fail "oms list should include snapshot"
  "$bin/oms" run-ledger --help >/dev/null 2>&1 || fail "oms should dispatch run-ledger via its symlink"
  (cd "$d" && "$bin/oms" run ls >/dev/null 2>&1) || fail "oms run door broke"
  # One spelling per verb: the dispatcher used to accept both a short alias
  # and a long name for five tools, which is the same shim this project
  # refuses everywhere else. The long spellings are gone, not redirected.
  for retired in oms-run oms-init repo-state agent-thread runtime-core; do
    if "$bin/oms" "$retired" --help >/dev/null 2>&1; then
      fail "the retired second spelling must not dispatch: $retired"
    fi
  done
  # One entrance per capability: the consolidated front doors work, and the
  # retired direct names are refused outright — no compat dispatch.
  "$bin/oms" run capsule --help >/dev/null 2>&1 || fail "oms run capsule door broke"
  "$bin/oms" artifact-index import --help >/dev/null 2>&1 || fail "artifact-index import door broke"
  "$bin/oms" snapshot --help >/dev/null 2>&1 || fail "snapshot front door broke"
  if "$bin/oms" no-such-tool >/dev/null 2>&1; then
    fail "oms must reject an unknown tool"
  fi
  if "$bin/oms" ../oms >/dev/null 2>&1; then
    fail "oms must reject path-like tool names"
  fi
  if "$bin/oms" lib/tool-lock >/dev/null 2>&1; then
    fail "oms must reject the internal lib/tool-lock implementation"
  fi
  for hidden in skill-router turn-guard check-bash32 install-tools \
    run-capsule generate-slurm-skill generate-slurm-reference github-source \
    import-agent-result install-autoupdate uninstall-autoupdate \
    write-machine-snapshot; do
    rc=0
    "$bin/oms" "$hidden" --help >/dev/null 2>&1 || rc=$?
    [ "$rc" = 2 ] || fail "oms should reject hidden tool $hidden with exit 2, got $rc"
  done
}

test_oms_frontdoor_routes_primary_subsystems() {
  local bin="$TMP/oms-frontdoor-bin"
  local frontdoors all_tools help_text review_help primary compatibility duplicate

  mkdir -p "$bin"
  ln -sfn "$ROOT/scripts/oms" "$bin/oms"

  frontdoors="$("$bin/oms" list --frontdoor)" || fail "oms list --frontdoor should succeed"
  all_tools="$("$bin/oms" list --all)" || fail "oms list --all should succeed"
  help_text="$("$bin/oms" --help)" || fail "oms --help should succeed"
  review_help="$("$bin/oms" peer-review --help)" || fail "peer-review --help should succeed"
  printf '%s\n' "$help_text" | grep -Fq 'full public catalog' ||
    fail "oms help should distinguish the full public catalog from subsystem front doors"
  printf '%s\n' "$review_help" | grep -Fq 'Plain review persists seat answers as artifacts.' ||
    fail "peer-review help should not promise a typed gate outcome in plain mode"
  printf '%s\n' "$review_help" | grep -Fq 'With --gate, enforce and record the typed gate outcome.' ||
    fail "peer-review help should scope its typed outcome to gate mode"

  for primary in autopilot consult doctor inbox journal land patch-admit patch-land \
    peer-delegate peer-review runtime tick update; do
    printf '%s\n' "$frontdoors" | grep -Eq "^${primary} " ||
      fail "frontdoor catalog should route the canonical workflow: $primary"
  done

  for compatibility in agent-call agent-run research-runner; do
    if printf '%s\n' "$frontdoors" | grep -Eq "^${compatibility} "; then
      fail "compatibility primitive should stay behind list --all: $compatibility"
    fi
    printf '%s\n' "$all_tools" | grep -Eq "^${compatibility} " ||
      fail "list --all should retain compatibility primitive: $compatibility"
  done

  duplicate="$(printf '%s\n' "$frontdoors" | awk '{ seen[$1]++ } END { for (name in seen) if (seen[name] > 1) print name }')"
  [ -z "$duplicate" ] || fail "frontdoor catalog contains duplicate tools: $duplicate"
  printf '%s\n' "$frontdoors" | grep -Eq '^peer-review .*diff' ||
    fail "peer-review catalog description should distinguish diff review from peer-ask"
}

test_doctor_detects_foreign_config_link() {
  local project="$TMP/doctor-foreign-link"
  local home_dir="$TMP/doctor-home-foreign-link"
  local out
  local rc=0

  setup_doctor_home "$home_dir"
  mkdir -p "$project"
  # A live link resolving to a foreign file used to pass as "ok" via [ -e ];
  # existence is not parity — the agent would run different rules.
  printf 'not the harness rules\n' > "$home_dir/foreign.md"
  ln -sfn "$home_dir/foreign.md" "$home_dir/.claude/CLAUDE.md"

  out="$(run_doctor_for_project "$project" "$home_dir" 2>&1)" && rc=0 || rc=$?
  [ "$rc" -ne 0 ] || fail "doctor must fail when a config link resolves to a foreign file"
  printf '%s' "$out" | grep -Fq "linked elsewhere: $home_dir/.claude/CLAUDE.md" ||
    fail "doctor should diagnose the foreign link target"
}

test_doctor_rejects_same_name_foreign_plugin() {
  local home_dir="$TMP/doctor-plugin-collision-home"
  local bin_dir="$TMP/doctor-plugin-collision-bin"
  local out="$TMP/doctor-plugin-collision-out"

  mkdir -p "$home_dir" "$bin_dir"
  HOME="$home_dir" "$ROOT/scripts/link.sh" >/dev/null
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
if [ "$1 $2 $3" = "plugin list --json" ]; then
  printf '%s\n' '{"installed":[{"name":"oh-my-setting","pluginId":"oh-my-setting@foreign","installed":true}]}'
fi
EOF
  chmod +x "$bin_dir/codex"

  if HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OH_MY_SETTING_REQUIRE_TOOLS=0 \
    OH_MY_SETTING_CODEX_PLUGIN=1 "$ROOT/scripts/doctor.sh" >"$out" 2>&1; then
    fail "doctor should reject a same-name plugin from a foreign marketplace"
  fi
  assert_file_contains "$out" "expected codex plugin not installed"
}

