test_fail_ledger_names_an_advisor_after_a_repeat() {
  local project="$TMP/fail-ledger-advise"
  local gate='uv run pytest tests/broken.py'
  local out

  # The rules ask for an outside read after repeated failures, peer-delegate does
  # it from the second repair round, and the primary agent's own gate failures
  # escalated nowhere: it filed the row and tried the same thing again.
  make_committed_repo "$project"
  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" record \
    --cmd "$gate" --exit 1 --summary "assert failed" 2>&1)" ||
    fail "first record should succeed"
  if printf '%s' "$out" | grep -Fq 'oms advise'; then
    fail "a single failure is not a pattern; no advisor yet: $out"
  fi

  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" record \
    --cmd "$gate" --exit 1 --summary "assert failed" 2>&1)" ||
    fail "second record should succeed"
  printf '%s' "$out" | grep -Fq 'has failed 2x unresolved' ||
    fail "the second unresolved failure should be named as a repeat: $out"
  printf '%s' "$out" | grep -Fq 'oms advise' ||
    fail "the repeat should name the advisor: $out"

  # `check` gates the retry, so it carries the same escalation and keeps exit 3.
  local rc=0
  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" check --cmd "$gate" 2>&1)" || rc=$?
  [ "$rc" = 3 ] || fail "check must still exit 3 for a known failure, got $rc"
  printf '%s' "$out" | grep -Fq 'oms advise' ||
    fail "check should name the advisor on a repeat: $out"

  # A resolve zeroes the run: the next failure is a first failure again.
  ( cd "$project" && "$ROOT/scripts/fail-ledger.sh" resolve --cmd "$gate" ) >/dev/null 2>&1 ||
    fail "resolve should succeed"
  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" record \
    --cmd "$gate" --exit 1 2>&1)" || fail "record after resolve should succeed"
  if printf '%s' "$out" | grep -Fq 'oms advise'; then
    fail "a resolved fingerprint must start counting again: $out"
  fi

  # Threshold is configurable, and 0 turns it off for a caller that does not
  # want an advisor named at all.
  out="$(cd "$project" && OMS_ADVISE_AFTER_FAILURES=0 "$ROOT/scripts/fail-ledger.sh" record \
    --cmd "$gate" --exit 1 2>&1)" || fail "record with the hint disabled should succeed"
  if printf '%s' "$out" | grep -Fq 'oms advise'; then
    fail "OMS_ADVISE_AFTER_FAILURES=0 must silence the hint: $out"
  fi
}

test_fail_ledger_hook_gives_failed_commands_a_memory() {
  local project="$TMP/fail-ledger-hook"
  local SH="$ROOT/scripts/fail-ledger-hook.sh"
  local payload='{"tool_name":"Bash","tool_input":{"command":"uv run pytest tests/broken.py"},"tool_response":{"exit_code":2}}'
  local out

  # The ledger only ever spoke when something called it, and the primary agent
  # mid-failure-loop never did. The hook is that call: silent on a first
  # failure, prior context plus the advise hint on the repeat. Speech rides
  # stderr with exit 2 — the channel Claude Code shows to the model on this
  # event without blocking; stdout would reach only the debug log.
  make_committed_repo "$project"
  mkdir -p "$project/.oms"
  out="$(cd "$project" && printf '%s' "$payload" | bash "$SH" 2>&1)" ||
    fail "a first failure has nothing to say, so the hook must exit 0"
  [ -z "$out" ] || fail "a first failure has no context to surface: $out"
  [ "$(wc -l < "$project/.oms/failures.jsonl" | tr -d ' ')" = 1 ] ||
    fail "the hook should have recorded the failure"

  local rc=0 err="$TMP/fail-ledger-hook.err"
  out="$(cd "$project" && printf '%s' "$payload" | bash "$SH" 2>"$err")" || rc=$?
  [ "$rc" = 2 ] || fail "ledger speech must use the exit-2 feedback channel, got exit $rc"
  [ -z "$out" ] || fail "speech on stdout is invisible to the model: $out"
  grep -Fq 'already failed 1x' "$err" ||
    fail "the repeat should surface prior ledger context: $(cat "$err")"
  grep -Fq 'oms advise' "$err" ||
    fail "the repeat should name the advisor: $(cat "$err")"
  if grep -Fq 'recorded ' "$err"; then
    fail "bookkeeping receipts are not agent context: $(cat "$err")"
  fi

  # Non-Bash failures, interrupts, disabled hook, and unadopted repos are
  # exact no-ops — and the hook must never seed .oms as a side effect.
  out="$(cd "$project" && printf '%s' '{"tool_name":"Edit","tool_input":{}}' | bash "$SH")"
  [ -z "$out" ] || fail "non-Bash failures are not ledger material: $out"
  out="$(cd "$project" && printf '%s' \
    '{"tool_name":"Bash","tool_input":{"command":"sleep 999"},"tool_response":{"exit_code":130}}' |
    bash "$SH")"
  [ -z "$out" ] || fail "an interrupt is not a failure worth remembering: $out"
  [ "$(wc -l < "$project/.oms/failures.jsonl" | tr -d ' ')" = 2 ] ||
    fail "no-op paths must not append rows"
  before="$(wc -l < "$project/.oms/failures.jsonl" | tr -d ' ')"
  out="$(cd "$project" && printf '%s' "$payload" | OMS_FAIL_LEDGER_HOOK=0 bash "$SH")"
  [ -z "$out" ] || fail "the opt-out must silence the hook: $out"
  [ "$(wc -l < "$project/.oms/failures.jsonl" | tr -d ' ')" = "$before" ] ||
    fail "the opt-out must not record"
  local plain="$TMP/fail-ledger-hook-plain"
  mkdir -p "$plain"
  out="$(cd "$plain" && printf '%s' "$payload" | bash "$SH")"
  [ -z "$out" ] || fail "an unadopted repo gets no ledger speech: $out"
  [ ! -d "$plain/.oms" ] || fail "the hook must not seed .oms"
}

# The edit-time syntax guard is feedback in the same turn: a file that does not
# parse after an Edit/Write comes back as additionalContext (plain stdout on
# PostToolUse never reaches the model), a clean file stays silent, and the
# hook never blocks, never exits nonzero, and never writes anything.
test_syntax_guard_hook_reports_broken_edits() {
  local project="$TMP/syntax-guard-hook"
  local SH="$ROOT/scripts/syntax-guard-hook.sh"
  local out

  make_committed_repo "$project"
  mkdir -p "$project/.oms"
  payload_for() {  # payload_for TOOL FILE
    printf '{"tool_name":"%s","tool_input":{"file_path":"%s"},"tool_response":{"filePath":"%s"},"hook_event_name":"PostToolUse","cwd":"%s"}' \
      "$1" "$2" "$2" "$project"
  }
  context_of() {  # context_of HOOK_OUTPUT -> additionalContext
    printf '%s' "$1" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["hookSpecificOutput"]["hookEventName"] == "PostToolUse", row
print(row["hookSpecificOutput"]["additionalContext"])
'
  }

  printf 'if true; then\n  echo unclosed\n' > "$project/broken.sh"
  out="$(cd "$project" && payload_for Write "$project/broken.sh" | bash "$SH")" ||
    fail "the hook must never exit nonzero"
  out="$(context_of "$out")" || fail "a broken shell file must come back as additionalContext: $out"
  case "$out" in
    "syntax-guard: broken.sh does not parse after this Write"*"bash -n"*) ;;
    *) fail "the finding must name the file, the tool, and the check: $out" ;;
  esac
  case "$out" in
    *"$project"*) fail "the finding shows a repo-relative path, not the machine path: $out" ;;
  esac

  printf 'echo fine\n' > "$project/fine.sh"
  out="$(cd "$project" && payload_for Edit "$project/fine.sh" | bash "$SH")"
  [ -z "$out" ] || fail "a clean file must stay silent: $out"

  printf 'def f(:\n    pass\n' > "$project/broken.py"
  out="$(cd "$project" && payload_for Edit "$project/broken.py" | bash "$SH")"
  out="$(context_of "$out")" || fail "a broken python file must come back as additionalContext"
  case "$out" in *"broken.py"*"python:"*) ;; *) fail "python finding is wrong: $out" ;; esac
  [ ! -d "$project/__pycache__" ] || fail "the check must not write bytecode"

  printf '{"a": 1,}\n' > "$project/broken.json"
  out="$(cd "$project" && payload_for Write "$project/broken.json" | bash "$SH")"
  out="$(context_of "$out")" || fail "a broken json file must come back as additionalContext"
  case "$out" in *"broken.json"*"json:"*) ;; *) fail "json finding is wrong: $out" ;; esac
  printf '{\n  // comments are the point of this file\n  "a": 1\n}\n' > "$project/tsconfig.json"
  out="$(cd "$project" && payload_for Write "$project/tsconfig.json" | bash "$SH")"
  [ -z "$out" ] || fail "JSON-with-comments files are not findings: $out"

  printf '#!/usr/bin/env bash\nfor x in; do\n' > "$project/tool"
  out="$(cd "$project" && payload_for Write "$project/tool" | bash "$SH")"
  out="$(context_of "$out")" || fail "a shebang script without an extension is still checked"
  case "$out" in *"tool does not parse"*"bash -n"*) ;; *) fail "shebang finding is wrong: $out" ;; esac

  # Non-edit tools, missing files, unknown kinds, the opt-out, and unadopted
  # repos are exact no-ops — and the hook never seeds .oms.
  out="$(cd "$project" && printf '%s' '{"tool_name":"Bash","tool_input":{"command":"true"}}' | bash "$SH")"
  [ -z "$out" ] || fail "a Bash call is not edit material: $out"
  out="$(cd "$project" && payload_for Write "$project/missing.sh" | bash "$SH")"
  [ -z "$out" ] || fail "a file that is gone has nothing to parse: $out"
  printf 'not code\n' > "$project/notes.md"
  out="$(cd "$project" && payload_for Write "$project/notes.md" | bash "$SH")"
  [ -z "$out" ] || fail "an unjudged file kind must stay silent: $out"
  out="$(cd "$project" && payload_for Write "$project/broken.sh" | OMS_SYNTAX_GUARD_HOOK=0 bash "$SH")"
  [ -z "$out" ] || fail "the opt-out must silence the hook: $out"
  local plain="$TMP/syntax-guard-plain"
  mkdir -p "$plain"
  printf 'if true; then\n' > "$plain/broken.sh"
  out="$(cd "$plain" && printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' "$plain/broken.sh" | bash "$SH")"
  [ -z "$out" ] || fail "an unadopted repo gets no guard speech: $out"
  [ ! -d "$plain/.oms" ] || fail "the hook must not seed .oms"

  # Codex edits arrive as apply_patch with the patch text in tool_input.command
  # and no file_path: the files the patch names are the ones to check, each
  # finding names its file, and a patch that touches only prose stays silent.
  mkdir -p "$project/src"
  printf 'def g(:\n    pass\n' > "$project/src/bad.py"
  printf 'echo ok\n' > "$project/src/good.sh"
  patch_payload() {  # patch_payload PATCH-TEXT
    python3 -c 'import json, sys; print(json.dumps({"tool_name": "apply_patch", "tool_input": {"command": sys.argv[1]}, "hook_event_name": "PostToolUse", "cwd": sys.argv[2]}))' "$1" "$project"
  }
  out="$(cd "$project" && patch_payload $'*** Begin Patch\n*** Add File: src/bad.py\n+def g(:\n+    pass\n*** Update File: src/good.sh\n@@\n-echo\n+echo ok\n*** End Patch' | bash "$SH")"
  out="$(context_of "$out")" || fail "a codex patch that leaves a broken file must come back as additionalContext"
  case "$out" in *"src/bad.py"*"python:"*) ;; *) fail "the finding names the patched file: $out" ;; esac
  case "$out" in *"good.sh"*) fail "a clean patched file is not a finding: $out" ;; *) ;; esac
  out="$(cd "$project" && patch_payload $'*** Begin Patch\n*** Update File: notes.md\n@@\n-not code\n+still prose\n*** End Patch' | bash "$SH")"
  [ -z "$out" ] || fail "a patch touching only prose stays silent: $out"
}

# The tier guard is the one hard edge of model tiering: an edit the session
# model itself makes to implementation in an adopted repo is advised once per
# session by default, asked or refused when OMS_TIER_GUARD says so, and never
# touched after delegation to a subagent or harness worker. Prose, .oms state,
# and files outside the repo pass.
test_tier_guard_hook_routes_implementation_to_workers() {
  local project="$TMP/tier-guard-hook"
  local SH="$ROOT/scripts/tier-guard-hook.sh"
  local out

  make_committed_repo "$project"
  mkdir -p "$project/.oms" "$project/docs"
  payload_for() {  # payload_for TOOL FILE SESSION [EXTRA-JSON-FIELDS]
    printf '{"tool_name":"%s","tool_input":{"file_path":"%s"},"hook_event_name":"PreToolUse","session_id":"%s","cwd":"%s"%s}' \
      "$1" "$2" "$3" "$project" "${4:-}"
  }
  decision_of() {  # decision_of HOOK_OUTPUT -> permissionDecision|context-flag
    printf '%s' "$1" | python3 -c '
import json, sys
row = json.load(sys.stdin)["hookSpecificOutput"]
assert row["hookEventName"] == "PreToolUse", row
print(row["permissionDecision"] + ("|context" if row.get("additionalContext") else "|") + ("|reason" if row.get("permissionDecisionReason") else "|"))
'
  }

  # advise (default): context once per session, allow always.
  out="$(cd "$project" && payload_for Write "$project/src/main.py" s1 | bash "$SH")" ||
    fail "the hook must never exit nonzero"
  [ "$(decision_of "$out")" = 'allow|context|' ] || fail "the first implementation edit in a session is advised: $out"
  printf '%s' "$out" | grep -Fq 'src/main.py is implementation' || fail "the advice names the file: $out"
  out="$(cd "$project" && payload_for Edit "$project/src/other.py" s1 | bash "$SH")"
  [ -z "$out" ] || fail "the same session is advised once: $out"
  out="$(cd "$project" && payload_for Edit "$project/src/other.py" s2 | bash "$SH")"
  [ "$(decision_of "$out")" = 'allow|context|' ] || fail "a new session is advised again: $out"

  # ask and deny carry the reason; off is silent.
  out="$(cd "$project" && payload_for Write "$project/src/main.py" s3 | OMS_TIER_GUARD=ask bash "$SH")"
  [ "$(decision_of "$out")" = 'ask||reason' ] || fail "ask mode must ask with a reason: $out"
  out="$(cd "$project" && payload_for Write "$project/src/main.py" s3 | OMS_TIER_GUARD=deny bash "$SH")"
  [ "$(decision_of "$out")" = 'deny||reason' ] || fail "deny mode must refuse with a reason: $out"
  out="$(cd "$project" && payload_for Write "$project/src/main.py" s4 | OMS_TIER_GUARD=off bash "$SH")"
  [ -z "$out" ] || fail "off must be silent: $out"

  # Delegated work passes even under deny. Only an OMS harness worker carries a
  # guaranteed worker-tier route; a native subagent may inherit unless pinned.
  out="$(cd "$project" && payload_for Write "$project/src/main.py" s5 ',"agent_id":"sub-1","agent_type":"build-error-resolver"' | OMS_TIER_GUARD=deny bash "$SH")"
  [ -z "$out" ] || fail "a subagent's edit is the policy working, not a violation: $out"
  out="$(cd "$project" && payload_for Write "$project/src/main.py" s5 | OMS_TIER_GUARD=deny OMS_HARNESS_CHILD=1 bash "$SH")"
  [ -z "$out" ] || fail "a harness worker's edit passes: $out"

  # session_id is a required Claude hook field. A malformed payload must not
  # create one permanent marker shared by every malformed/future invocation.
  out="$(cd "$project" && printf '{"tool_name":"Write","tool_input":{"file_path":"%s"},"cwd":"%s"}' "$project/src/main.py" "$project" | bash "$SH")"
  [ -z "$out" ] || fail "a payload without session identity must fail open: $out"
  [ ! -e "$project/.oms/hooks/tier-guard-session" ] ||
    fail "a missing session id created a cross-session marker"

  # Prose, harness state, files outside the repo, non-edit tools, unadopted repos.
  for path in "$project/docs/design.md" "$project/README.md" "$project/.oms/task/current.md" "$TMP/outside-the-repo.py"; do
    out="$(cd "$project" && payload_for Write "$path" s6 | OMS_TIER_GUARD=deny bash "$SH")"
    [ -z "$out" ] || fail "$path is not guarded implementation: $out"
  done
  out="$(cd "$project" && printf '%s' '{"tool_name":"Bash","tool_input":{"command":"true"},"session_id":"s7"}' | OMS_TIER_GUARD=deny bash "$SH")"
  [ -z "$out" ] || fail "a Bash call is not an edit: $out"
  local plain="$TMP/tier-guard-plain"
  mkdir -p "$plain"
  out="$(cd "$plain" && printf '{"tool_name":"Write","tool_input":{"file_path":"%s"},"session_id":"s8"}' "$plain/main.py" | OMS_TIER_GUARD=deny bash "$SH")"
  [ -z "$out" ] || fail "an unadopted repo is not guarded: $out"
  [ ! -d "$plain/.oms" ] || fail "the hook must not seed .oms"
}

test_fail_ledger_records_checks_resolves() {
  local project="$TMP/fail-ledger"
  local SH="$ROOT/scripts/fail-ledger.sh"

  make_committed_repo "$project"
  ( cd "$project" && OMS_AGENT=codex "$SH" record --cmd "uv run pytest -k foo" --exit 1 --summary "ModuleNotFoundError" >/dev/null 2>&1 )
  ( cd "$project" && OMS_AGENT=claude "$SH" record --cmd "uv run pytest -k foo" --exit 1 >/dev/null 2>&1 )
  # A known unresolved failure makes check exit nonzero for any agent.
  if ( cd "$project" && "$SH" check --cmd "uv run pytest -k foo" >/dev/null 2>&1 ); then
    fail "check must flag a known unresolved failure"
  fi
  ( cd "$project" && "$SH" list | grep -q "count=2" ) || fail "the same command must dedupe to one fingerprint"
  local fp
  fp="$(cd "$project" && "$SH" list | awk '{print $1; exit}')"
  ( cd "$project" && "$SH" resolve --fingerprint "$fp" >/dev/null 2>&1 )
  ( cd "$project" && "$SH" check --cmd "uv run pytest -k foo" >/dev/null 2>&1 ) ||
    fail "resolve must clear the warning"
  # An unseen command passes; a sensitive command is refused. The literal is
  # split with '' so this test source stays clean of a real-looking secret
  # (the harness-source scrubber self-review scans tests/ too).
  ( cd "$project" && "$SH" check --cmd "echo never" >/dev/null 2>&1 ) || fail "unseen command must pass"
  local secret_cmd='export aws_secret_access_''key=EXAMPLEVALUE1234567'
  if ( cd "$project" && "$SH" record --cmd "$secret_cmd" --exit 1 >/dev/null 2>&1 ); then
    fail "a sensitive-looking command must be refused"
  fi
}

test_fail_ledger_records_machine_paths_normalized() {
  local project="$TMP/fail-ledger-paths"
  local SH="$ROOT/scripts/fail-ledger.sh"
  local path_cmd
  # Failed commands routinely carry absolute paths; the ledger must keep the
  # failure (normalized), not refuse it — refusal silently lost the memory.
  path_cmd="python /ho""me/researcher/proj/train.py --epochs 3"

  make_committed_repo "$project"
  ( cd "$project" && "$SH" record --cmd "$path_cmd" --exit 1 \
      --summary "OOM at /ho""me/researcher/proj/data" >/dev/null 2>&1 ) ||
    fail "a path-bearing failed command must be recordable"
  ( cd "$project" && "$SH" list --json | grep -q 'python ~/proj/train.py' ) ||
    fail "stored command must have its home prefix normalized"
  if ( cd "$project" && "$SH" list --json | grep -q '/ho''me/researcher' ); then
    fail "raw home path must not reach the ledger"
  fi
  # Lookup consistency: checking the RAW command must hit the stored row
  # because both sides normalize before fingerprinting.
  if ( cd "$project" && "$SH" check --cmd "$path_cmd" >/dev/null 2>&1 ); then
    fail "check must flag the normalized fingerprint for the raw command"
  fi
}

test_fail_ledger_kind_next_how_and_legacy_rows() {
  local project="$TMP/fail-ledger-fields"
  local SH="$ROOT/scripts/fail-ledger.sh"
  local out fp rc=0

  make_committed_repo "$project"
  out="$(cd "$project" && "$SH" --repo "$project" record --cmd "false" --exit 1 --kind invalid 2>&1)" &&
    fail "unknown fail-ledger kind must fail"
  printf '%s' "$out" | grep -Fq 'cmd, hook, verify, plan-run, delegate, patch-land' ||
    fail "kind rejection must name the allowed set: $out"

  ( cd "$project" && "$SH" --repo "$project" record --cmd "bash broken.sh" --exit 1 \
      --kind verify --next "inspect the failing assertion" ) >/dev/null 2>&1 ||
    fail "record with --next should succeed"
  out="$(cd "$project" && "$SH" --repo "$project" check --cmd "bash broken.sh" 2>&1)" || rc=$?
  [ "$rc" = 3 ] || fail "check must still return 3 with --next, got $rc"
  printf '%s' "$out" | grep -Fq 'next: inspect the failing assertion' ||
    fail "check must surface the recommended next action: $out"
  out="$(cd "$project" && "$SH" --repo "$project" list)" || fail "list with --next should succeed"
  printf '%s' "$out" | grep -Fq '  next: inspect the failing assertion' ||
    fail "list must surface --next: $out"
  fp="$(printf '%s\n' "$out" | awk 'NR == 1 { print $1 }')"
  ( cd "$project" && "$SH" --repo "$project" resolve --fingerprint "$fp" --how "fixed the assertion" ) \
    >/dev/null 2>&1 || fail "resolve with --how should succeed"
  out="$(cd "$project" && "$SH" --repo "$project" list)" || fail "list after --how should succeed"
  printf '%s' "$out" | grep -Fq '  fixed: fixed the assertion' ||
    fail "list must surface --how on resolved rows: $out"
  out="$(cd "$project" && "$SH" --repo "$project" list --json)" || fail "list --json should succeed"
  printf '%s' "$out" | python3 -c '
import json, sys
row = json.load(sys.stdin)["failures"][0]
assert row["next"] == "inspect the failing assertion", row
assert row["how"] == "fixed the assertion", row
' || fail "list --json must retain --next and --how"

  printf '{"schema":1,"event":"fail","fingerprint":"legacy-row","kind":"cmd","cmd":"old command","exit":1}\n' \
    >> "$project/.oms/failures.jsonl"
  printf '{"event":"fail","fingerprint":"implicit-schema-row","cmd":"older command","exit":1}\n' \
    >> "$project/.oms/failures.jsonl"
  out="$(cd "$project" && "$SH" --repo "$project" list)" || fail "list should parse old rows"
  printf '%s' "$out" | grep -Fq 'old command' ||
    fail "old rows without new fields must still list: $out"
  printf '%s' "$out" | grep -Fq 'older command' ||
    fail "legacy rows without an explicit schema must still list: $out"
}

test_ci_status_record_and_state() {
  local project="$TMP/ci-record"
  local bin="$TMP/ci-record-bin"

  make_committed_repo "$project"
  mkdir -p "$bin"
  cat > "$bin/gh" <<'EOF'
#!/usr/bin/env bash
echo '[{"status":"completed","conclusion":"failure","workflowName":"test","headSha":"deadbeef1234","url":"https://x/1"}]'
EOF
  chmod +x "$bin/gh"
  ( cd "$project" && OMS_GH_BIN="$bin/gh" "$ROOT/scripts/ci-status.sh" record main >/dev/null 2>&1 ) && \
    fail "ci-status record should exit nonzero on a failing run"
  [ -f "$project/.oms/ci.jsonl" ] || fail "record should write .oms/ci.jsonl"
  grep -Fq '"conclusion": "failure"' "$project/.oms/ci.jsonl" || fail "the failure conclusion should be recorded"
  # Dedupe: same sha+conclusion is not re-appended.
  ( cd "$project" && OMS_GH_BIN="$bin/gh" "$ROOT/scripts/ci-status.sh" record main >/dev/null 2>&1 ) || true
  [ "$(grep -c '' "$project/.oms/ci.jsonl")" -eq 1 ] || fail "identical CI result must not be re-appended"
  ( cd "$project" && "$ROOT/scripts/state.sh" ) | grep -Fq "## CI" || fail "oms state should surface CI"
}

test_delegation_liveness_in_state() {
  local project="$TMP/deleg-live"

  make_committed_repo "$project"
  mkdir -p "$project/.oms/delegations"
  printf '{"schema":1,"id":"d1","provider":"codex","role":"","pid":999999,"started_at":"2026-01-01T00:00:00Z","state":"running","worktree":"/x"}\n' \
    > "$project/.oms/delegations/d1.json"
  printf '{"schema":1,"id":"d2","provider":"claude","role":"","pid":%s,"started_at":"2026-01-02T00:00:00Z","state":"running","worktree":"/y"}\n' "$$" \
    > "$project/.oms/delegations/d2.json"
  local out
  out="$(cd "$project" && "$ROOT/scripts/state.sh")"
  printf '%s' "$out" | grep -Eq "d1.*ORPHAN" || fail "a dead-pid delegation must be flagged as ORPHAN"
  printf '%s' "$out" | grep -Eq "d2.*live" || fail "a live-pid delegation must show as live"
}

test_gc_reclaims_safely() {
  local project="$TMP/gc"
  local gc_err="$project/gc.err"

  make_committed_repo "$project"
  mkdir -p "$project/.oms/delegations" "$project/.oms/task/archive" "$project/.oms/runs/oldrun"
  printf '{"schema":1,"id":"d1","pid":999999,"state":"running"}\n' > "$project/.oms/delegations/d1.json"
  printf '{"schema":1,"id":"d2","pid":%s,"state":"running"}\n' "$$" > "$project/.oms/delegations/d2.json"
  printf 'x\n' > "$project/.oms/task/archive/current-old.md"
  printf '{}' > "$project/.oms/runs/oldrun/capsule.json"
  printf '%s\n' \
    '{"ts":"2020-01-01T00:00:00Z","fingerprint":"old","event":"fail"}' \
    '{"ts":"2020-01-01T00:00:01Z","fingerprint":"old","event":"resolved"}' \
    > "$project/.oms/failures.jsonl"
  touch -t 202601010000 "$project/.oms/task/archive/current-old.md" "$project/.oms/runs/oldrun"

  # Dry-run changes nothing.
  ( cd "$project" && "$ROOT/scripts/gc.sh" --days 30 >/dev/null 2>&1 )
  [ -f "$project/.oms/delegations/d1.json" ] || fail "dry-run must not delete anything"
  # Apply reclaims the orphan/old, keeps the live delegation.
  ( cd "$project" && "$ROOT/scripts/gc.sh" --days 0 --apply >/dev/null 2>"$gc_err" )
  [ ! -s "$gc_err" ] || fail "gc should compact an all-resolved ledger without stderr: $(cat "$gc_err")"
  [ ! -f "$project/.oms/delegations/d1.json" ] || fail "gc --apply should remove the dead-pid delegation"
  [ -f "$project/.oms/delegations/d2.json" ] || fail "gc must keep a live delegation"
  [ ! -f "$project/.oms/task/archive/current-old.md" ] || fail "gc should remove an aged task archive"
  [ ! -d "$project/.oms/runs/oldrun" ] || fail "gc should remove an aged capsule"
  [ ! -s "$project/.oms/failures.jsonl" ] || fail "gc should compact an all-resolved old ledger to empty"
}

test_gc_reclaims_aged_handoffs() {
  local project="$TMP/gc-handoffs"
  local out

  make_committed_repo "$project"
  mkdir -p "$project/.oms/handoffs"
  printf 'old\n' > "$project/.oms/handoffs/old.md"
  printf 'fresh\n' > "$project/.oms/handoffs/fresh.md"
  touch -t 202601010000 "$project/.oms/handoffs/old.md"

  out="$(cd "$project" && "$ROOT/scripts/gc.sh" --days 30 2>&1)"
  printf '%s' "$out" | grep -Fq "handoff: $project/.oms/handoffs/old.md" ||
    fail "dry-run should list the aged handoff: $out"
  [ -f "$project/.oms/handoffs/old.md" ] || fail "dry-run must keep aged handoffs"
  [ -f "$project/.oms/handoffs/fresh.md" ] || fail "dry-run must keep fresh handoffs"

  ( cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply >/dev/null 2>&1 )
  [ ! -f "$project/.oms/handoffs/old.md" ] || fail "gc should remove an aged handoff"
  [ -f "$project/.oms/handoffs/fresh.md" ] || fail "gc must keep a fresh handoff"
}

test_oms_init_seeds_and_guides() {
  local project="$TMP/oms-init"
  local registry="$XDG_CONFIG_HOME/oh-my-setting/tick-repos.txt"

  make_committed_repo "$project"
  printf 'import torch\n' > "$project/model.py"
  local out
  out="$(cd "$project" && "$ROOT/scripts/init.sh")"
  [ -f "$project/.oms/.gitignore" ] || fail "init should create the .oms/.gitignore guard"
  [ -f "$project/.oms/memory/shared.md" ] || fail "init should seed shared memory"
  [ -f "$project/.oms/memory/memory.sqlite3" ] ||
    fail "init should create the project memory database"
  printf '%s' "$out" | grep -Fq 'tick registry registered' ||
    fail "init should report tick registration: $out"
  [ "$(grep -Fxc "$project" "$registry")" = 1 ] ||
    fail "init should register the repo exactly once"
  printf '%s' "$out" | grep -Fq "ML repo" || fail "init should tailor the checklist to an ML repo"
  printf '%s' "$out" | grep -Fq "oms state" || fail "init should point at oms state"
  printf '%s' "$out" | grep -Fq "oms data-manifest check --name <manifest>" ||
    fail "init should show a valid named manifest check command"
  printf '%s' "$out" | grep -Fq "oms data-manifest leakage --name <manifest>" ||
    fail "init should show a valid named leakage command"
  # Idempotent and migratory: a Markdown-only project gets its derived index
  # back on the next init without changing the source.
  rm -f "$project/.oms/memory/memory.sqlite3"
  out="$(cd "$project" && "$ROOT/scripts/init.sh")" || fail "init must be idempotent"
  [ -f "$project/.oms/memory/memory.sqlite3" ] ||
    fail "init should migrate an existing Markdown-only memory"
  printf '%s' "$out" | grep -Fq 'tick registry already registered' ||
    fail "an idempotent init should report the existing tick registration: $out"
  [ "$(grep -Fxc "$project" "$registry")" = 1 ] ||
    fail "an idempotent init should not duplicate the registry entry"
}

test_gc_closes_stale_open_run() {
  local project="$TMP/gc-run-close"

  make_committed_repo "$project"
  local rid
  rid="$(cd "$project" && "$ROOT/scripts/run.sh" new)"
  # Backdate every spine event so the run reads as abandoned.
  python3 - "$project/.oms/runs/spine.jsonl" <<'PY'
import json, sys
rows = [json.loads(l) for l in open(sys.argv[1]) if l.strip()]
for r in rows:
    r["ts"] = "2020-01-01T00:00:00Z"
open(sys.argv[1], "w").write("\n".join(json.dumps(r) for r in rows) + "\n")
PY
  local out
  out="$(cd "$project" && "$ROOT/scripts/gc.sh" --days 30 2>&1)"
  printf '%s' "$out" | grep -Fq "stale-run-close: $rid" || fail "dry-run should report the stale open run"
  ( cd "$project" && "$ROOT/scripts/run.sh" ls --open | grep -Fq "$rid" ) ||
    fail "dry-run must not close the run"
  ( cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply >/dev/null 2>&1 )
  ( cd "$project" && "$ROOT/scripts/run.sh" ls | grep -F "$rid" | grep -Fq "closed" ) ||
    fail "gc --apply should append a close event for the stale run"
}

test_gc_releases_plan_task_of_dead_delegation() {
  local project="$TMP/gc-plan-release"
  local lease_t1

  make_committed_repo "$project"
  "$ROOT/scripts/agent-plan.sh" --repo "$project" init --goal "gc release" >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" add --id t1 --title "one" >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" claim --id t1 --provider codex >/dev/null
  lease_t1="$("$ROOT/scripts/agent-plan.sh" --repo "$project" show --id t1 |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$ROOT/scripts/agent-plan.sh" --repo "$project" add --id t2 --title "two" >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" claim --id t2 --provider codex >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" review --id t2 --patch /tmp/p >/dev/null
  mkdir -p "$project/.oms/delegations"
  printf '{"schema":2,"id":"d1","pid":999999,"task_id":"t1","lease_id":"%s"}\n' "$lease_t1" > "$project/.oms/delegations/d1.json"
  printf '{"schema":1,"id":"d2","pid":999999,"task_id":"t2"}\n' > "$project/.oms/delegations/d2.json"

  ( cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply >/dev/null 2>&1 )
  "$ROOT/scripts/agent-plan.sh" --repo "$project" show --id t1 | grep -Fq '"state": "ready"' ||
    fail "gc should release the claimed task of a dead delegation"
  # review holds a finished artifact awaiting a reviewer; gc must not requeue it.
  "$ROOT/scripts/agent-plan.sh" --repo "$project" show --id t2 | grep -Fq '"state": "review"' ||
    fail "gc must not release a task in review"
  assert_not_exists "$project/.oms/delegations/d1.json"
}

test_gc_old_marker_cannot_release_new_lease() {
  local project="$TMP/gc-stale-lease"
  local sh="$ROOT/scripts/agent-plan.sh"
  local old_lease

  make_committed_repo "$project"
  "$sh" --repo "$project" init --goal "stale marker" >/dev/null
  "$sh" --repo "$project" add --id t1 --title "one" >/dev/null
  "$sh" --repo "$project" claim --id t1 --provider codex --ttl 0 >/dev/null
  old_lease="$("$sh" --repo "$project" show --id t1 |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" reclaim >/dev/null
  "$sh" --repo "$project" claim --id t1 --provider claude >/dev/null
  mkdir -p "$project/.oms/delegations"
  printf '{"schema":2,"id":"old","pid":999999,"task_id":"t1","lease_id":"%s"}\n' \
    "$old_lease" > "$project/.oms/delegations/old.json"

  (cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply >/dev/null)
  "$sh" --repo "$project" show --id t1 | grep -Fq '"state": "claimed"' ||
    fail "an old delegation marker must not release a newer claim"
  assert_not_exists "$project/.oms/delegations/old.json"
}

test_gc_dead_marker_cannot_release_live_same_lease() {
  local project="$TMP/gc-live-same-lease"
  local sh="$ROOT/scripts/agent-plan.sh"
  local lease dry_out

  make_committed_repo "$project"
  "$sh" --repo "$project" init --goal "live retry marker" >/dev/null
  "$sh" --repo "$project" add --id t1 --title "one" >/dev/null
  "$sh" --repo "$project" claim --id t1 --provider codex >/dev/null
  lease="$("$sh" --repo "$project" show --id t1 |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  mkdir -p "$project/.oms/delegations"
  # Alphabetical order makes GC encounter the stale marker first. The live
  # retry owns the same task+lease and must veto recovery under the plan lock.
  printf '{"schema":3,"id":"old","pid":999999,"task_id":"t1","lease_id":"%s"}\n' \
    "$lease" > "$project/.oms/delegations/a-old.json"
  printf '{"schema":3,"id":"retry","pid":%d,"task_id":"t1","lease_id":"%s"}\n' \
    "$$" "$lease" > "$project/.oms/delegations/z-live.json"

  dry_out="$(cd "$project" && "$ROOT/scripts/gc.sh" --days 30 2>&1)"
  printf '%s' "$dry_out" | grep -Fq 'live exact worker; kept it' ||
    fail "gc dry-run did not apply the locked live-marker veto: $dry_out"
  if printf '%s' "$dry_out" | grep -Fq 'task t1 (claimed) -> ready'; then
    fail "gc dry-run falsely planned release of a live same-lease retry: $dry_out"
  fi
  "$sh" --repo "$project" show --id t1 | grep -Fq '"state": "claimed"' ||
    fail "gc dry-run changed the live retry"
  [ -f "$project/.oms/delegations/a-old.json" ] ||
    fail "gc dry-run removed the stale marker"

  (cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply >/dev/null)
  "$sh" --repo "$project" show --id t1 | grep -Fq '"state": "claimed"' ||
    fail "a dead marker stole a live retry holding the same lease"
  assert_not_exists "$project/.oms/delegations/a-old.json"
  [ -f "$project/.oms/delegations/z-live.json" ] ||
    fail "gc removed the live retry marker"
}

test_process_liveness_uses_non_destructive_windows_probe() {
  local project native_pid rc=0 plan lease
  for producer in "$ROOT/scripts/autopilot.sh" "$ROOT/scripts/peer-delegate.sh"; do
    grep -Fq 'oms_process_native_pid "$$"' "$producer" ||
      fail "$(basename "$producer") bypassed the shared native pid resolver"
    if grep -Fq 'os.getppid()' "$producer"; then
      fail "$(basename "$producer") derives owner identity from a native child"
    fi
  done
  if ! python3 - "$ROOT/scripts/lib/process_liveness.py" <<'PY'
import importlib.util
import errno
import os
import subprocess
import sys

path = sys.argv[1]
spec = importlib.util.spec_from_file_location("oms_process_liveness", path)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)

class Function:
    def __init__(self, result):
        self.result = result
        self.calls = []
    def __call__(self, *args):
        self.calls.append(args)
        return self.result

class Kernel:
    def __init__(self, handle, wait):
        self.OpenProcess = Function(handle)
        self.WaitForSingleObject = Function(wait)
        self.CloseHandle = Function(1)

def probe(handle, wait, error, native_pid=654):
    kernel = Kernel(handle, wait)
    def forbidden_kill(_pid, _signal):
        raise AssertionError("Windows liveness must never call os.kill(pid, 0)")
    alive = module.pid_alive(
        321, native_pid=native_pid, os_name="nt", kernel32=kernel,
        get_last_error=lambda: error, posix_kill=forbidden_kill,
    )
    valid_native = (isinstance(native_pid, int)
                    and not isinstance(native_pid, bool)
                    and 0 < native_pid <= 0xffffffff)
    if valid_native:
        assert kernel.OpenProcess.calls == [(module.SYNCHRONIZE, False, native_pid)]
    else:
        assert kernel.OpenProcess.calls == []
    if handle and valid_native:
        assert kernel.WaitForSingleObject.calls == [(handle, 0)]
        assert kernel.CloseHandle.calls == [(handle,)]
    else:
        assert kernel.WaitForSingleObject.calls == []
        assert kernel.CloseHandle.calls == []
    return alive

assert probe(41, module.WAIT_TIMEOUT, 0) is True
assert probe(42, module.WAIT_OBJECT_0, 0) is False
assert probe(43, module.WAIT_FAILED, 0) is True
assert probe(0, module.WAIT_FAILED, module.ERROR_INVALID_PARAMETER) is False
assert probe(0, module.WAIT_FAILED, module.ERROR_ACCESS_DENIED) is True
# A Git Bash/MSYS pid is not a Win32 pid. Legacy, missing, or untyped native
# identity can never prove death on Windows and must not reach OpenProcess.
for missing in (None, 0, -1, True, "654", 0x100000000):
    assert probe(0, module.WAIT_FAILED, module.ERROR_INVALID_PARAMETER, missing) is True

posix_calls = []
assert module.pid_alive(
    321, native_pid=654, os_name="posix",
    posix_kill=lambda pid, sig: posix_calls.append((pid, sig)),
) is True
assert posix_calls == [(321, 0)]
assert module.pid_alive(1 << 100, os_name="posix") is True
def ambiguous_kill(_pid, _signal):
    raise OSError(errno.EINVAL, "ambiguous")
assert module.pid_alive(321, os_name="posix", posix_kill=ambiguous_kill) is True

if os.name == "nt":
    assert module.pid_alive(123, native_pid=os.getpid()) is True
    child = subprocess.Popen([sys.executable, "-c", "pass"])
    dead_pid = child.pid
    child.wait(timeout=10)
    assert module.pid_alive(123, native_pid=dead_pid) is False
PY
  then
    fail "Windows process liveness probe contract failed"
  fi

  case "$(uname -s 2>/dev/null || true)" in
    MINGW*|MSYS*|CYGWIN*)
      project="$TMP/windows-native-pid-recovery"
      make_committed_repo "$project"
      python3 -c 'import os; assert os.name == "nt", os.name' ||
        fail "Git Bash test did not use native Windows Python"
      [ -r "/proc/$$/winpid" ] || fail "Git Bash did not expose /proc/$$/winpid"
      proc_winpid=""
      IFS= read -r proc_winpid < "/proc/$$/winpid"
      proc_winpid="${proc_winpid//$'\r'/}"
      native_pid="$(
        # shellcheck source=scripts/lib/file-lock.sh
        . "$ROOT/scripts/lib/file-lock.sh"
        oms_process_native_pid "$$"
      )" || fail "shared native pid resolver rejected the owning Git Bash"
      native_pid="${native_pid//$'\r'/}"
      case "$native_pid" in *[!0-9]*|"") fail "native Git Bash pid capture is invalid" ;; esac
      [ "$native_pid" = "$proc_winpid" ] ||
        fail "resolved native pid $native_pid differs from /proc/$$/winpid $proc_winpid"
      mkdir -p "$project/.oms/executors/native" "$project/.oms/delegations"
      printf '{"schema":1,"executor_id":"native","state":"running"}\n' \
        > "$project/.oms/executors/native/meta.json"
      # A marker from the pre-provenance producer can carry a well-typed but
      # already-dead launcher pid. That number cannot prove that the still-live
      # logical owner is dead.
      printf '{"schema":4,"id":"native","pid":%d,"native_pid":999999,"executor_id":"native"}\n' \
        "$$" > "$project/.oms/delegations/native.json"
      rc=0
      "$ROOT/scripts/agent-executor.sh" recover --repo "$project" --id native \
        --expected-state running --markers-dir "$project/.oms/delegations" --check \
        > "$project/unproven.out" 2>&1 || rc=$?
      [ "$rc" = 3 ] ||
        fail "legacy Windows marker became dead proof, got $rc: $(cat "$project/unproven.out")"
      grep -Fq 'unproven' "$project/unproven.out" ||
        fail "legacy Windows marker was not labeled unproven"
      plan="$ROOT/scripts/agent-plan.sh"
      "$plan" --repo "$project" init --goal "native marker recovery" >/dev/null
      "$plan" --repo "$project" add --id native-task --title native >/dev/null
      "$plan" --repo "$project" claim --id native-task --provider codex >/dev/null
      lease="$("$plan" --repo "$project" show --id native-task |
        python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
      lease="${lease//$'\r'/}"
      "$plan" --repo "$project" start --id native-task --lease-id "$lease" >/dev/null
      printf '{"schema":4,"id":"native-plan","pid":%d,"native_pid":999999,"task_id":"native-task","lease_id":"%s"}\n' \
        "$$" "$lease" > "$project/.oms/delegations/native-plan.json"
      rc=0
      "$plan" --repo "$project" recover-lease --id native-task --lease-id "$lease" \
        --expected-state running --markers-dir "$project/.oms/delegations" --check \
        > "$project/plan-unproven.out" 2>&1 || rc=$?
      [ "$rc" = 3 ] ||
        fail "legacy Windows plan marker became dead proof, got $rc: $(cat "$project/plan-unproven.out")"
      grep -Fq 'unproven' "$project/plan-unproven.out" ||
        fail "legacy Windows plan marker was not labeled unproven"
      state_out="$("$ROOT/scripts/state.sh" --repo "$project" --json)" ||
        fail "state could not read a native Git Bash marker"
      OMS_T_NATIVE_STATE="$state_out" python3 - <<'PY' ||
        fail "state labeled a live native Git Bash marker as orphaned"
import json, os
row = json.loads(os.environ["OMS_T_NATIVE_STATE"])
delegations = row.get("delegations") or []
assert any(item.get("id") == "native" and item.get("live") is True
           for item in delegations), delegations
PY
      verify_out="$("$ROOT/scripts/state-verify.sh" --repo "$project" --json 2>/dev/null || true)"
      OMS_T_NATIVE_VERIFY="$verify_out" python3 - <<'PY' ||
        fail "state-verify labeled a live native Git Bash marker as orphaned"
import json, os
row = json.loads(os.environ["OMS_T_NATIVE_VERIFY"])
findings = row.get("findings") or []
assert not any(item.get("family") == "delegations" for item in findings), findings
PY
      printf '{"schema":4,"id":"native","pid":%d,"native_pid":%d,"native_pid_source":"msys-proc-v1","executor_id":"native"}\n' \
        "$$" "$native_pid" > "$project/.oms/delegations/native.json"
      rc=0
      "$ROOT/scripts/agent-executor.sh" recover --repo "$project" --id native \
        --expected-state running --markers-dir "$project/.oms/delegations" --check \
        >/dev/null 2>&1 || rc=$?
      [ "$rc" = 3 ] || fail "live sourced WINPID marker did not veto recovery, got $rc"
      python3 - "$ROOT/scripts/lib/agent-events.py" "$project/lock-owner" <<'PY' ||
        fail "agent-events could not preserve its live native lock owner"
import importlib.util, json, os, sys
spec = importlib.util.spec_from_file_location("agent_events", sys.argv[1])
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
with module.file_lock(module.Path(sys.argv[2])):
    owner = json.loads((module.runtime_lock_dir(module.Path(sys.argv[2])) /
                        "owner.json").read_text(encoding="utf-8"))
    assert owner["pid"] == os.getpid()
    assert module.pid_alive(owner["pid"]) is True
PY
      kill -0 "$$" 2>/dev/null || fail "the Windows recovery probe harmed its owning Git Bash"
      ;;
  esac
}

test_autopilot_windows_reenter_launch_keeps_parent_anchor() {
  local dir="$TMP/autopilot-reenter-anchor"
  local anchor_lib="$dir/anchor.sh"
  local child_script="$dir/child.py"
  local child_wrapper="$dir/child-wrapper.sh"
  local signal expected parent_pid child_pid grandchild_pid logical_pid
  local pid_file grandchild_pid_file logical_pid_file rc i windows_tree_test=0

  mkdir -p "$dir"
  sed -n '/^# OMS_REENTER_ANCHOR_BEGIN$/,/^# OMS_REENTER_ANCHOR_END$/p' \
    "$ROOT/scripts/autopilot.sh" > "$anchor_lib"
  [ -s "$anchor_lib" ] || fail "autopilot reenter anchor helper is not extractable"
  if ! python3 - "$anchor_lib" <<'PY'
import sys

source = open(sys.argv[1], encoding="utf-8").read()
assert "trap ''" not in source
handlers = source.index("trap 'reenter_forward_signal HUP 129' HUP")
defaults = source.index("trap - HUP INT TERM", handlers)
spawn = source.index('exec "$@"', defaults)
capture = source.index('REENTER_CONTINUATION_PID=$!', spawn)
pending = source.index('REENTER_PENDING_SIGNAL', capture)
wait = source.index('wait "$REENTER_CONTINUATION_PID"', pending)
assert handlers < defaults < spawn < capture < pending < wait
PY
  then
    fail "Windows reenter anchor ordering can inherit or lose a signal"
  fi

  # The pre-capture handler must defer termination instead of exiting while
  # the continuation pid is still empty.
  (
    set -euo pipefail
    # shellcheck source=/dev/null
    . "$anchor_lib"
    # Read by the extracted production helper.
    # shellcheck disable=SC2034
    REENTER_CONTINUATION_PID=""
    REENTER_PENDING_SIGNAL=""
    REENTER_PENDING_EXIT=""
    reenter_forward_signal TERM 143
    [ "$REENTER_PENDING_SIGNAL" = TERM ]
    [ "$REENTER_PENDING_EXIT" = 143 ]
  ) || fail "pre-capture TERM was not retained for the continuation"

  # A Windows signal result is only trustworthy when the native tree-stop
  # command itself succeeded. Losing the logical anchor is not that proof.
  rc=0
  (
    set -uo pipefail
    # shellcheck source=/dev/null
    . "$anchor_lib"
    uname() { printf '%s\n' MINGW64_NT; }
    reenter_capture_continuation_native_pid() { return 0; }
    reenter_continuation_native_pid_is_current() { return 0; }
    reenter_taskkill_continuation_tree() { return 1; }
    reenter_continuation_stopped() { return 0; }
    # Read by the dynamically sourced production helper.
    # shellcheck disable=SC2034
    REENTER_CONTINUATION_PID=31337
    reenter_forward_signal HUP 129
  ) > "$dir/unproven.out" 2> "$dir/unproven.err" || rc=$?
  [ "$rc" = 2 ] ||
    fail "an unproven Windows tree stop returned signal status $rc"

  # If a logical pid loses its frozen Win32 mapping after taskkill, do not
  # send a numeric fallback signal that could hit a reused MSYS pid.
  rc=0
  (
    set -uo pipefail
    # shellcheck source=/dev/null
    . "$anchor_lib"
    mapping_checks=0
    stop_checks=0
    kill_calls=0
    uname() { printf '%s\n' MINGW64_NT; }
    reenter_capture_continuation_native_pid() { return 0; }
    reenter_continuation_native_pid_is_current() {
      mapping_checks=$((mapping_checks + 1))
      [ "$mapping_checks" -lt 3 ]
    }
    reenter_taskkill_continuation_tree() {
      printf '%s\n' "$2" >> "$dir/reuse-taskkill-forces"
      return 0
    }
    reenter_wait_continuation_stop() {
      stop_checks=$((stop_checks + 1))
      [ "$stop_checks" -gt 1 ]
    }
    kill() {
      kill_calls=$((kill_calls + 1))
      printf '%s\n' "$kill_calls" >> "$dir/reuse-kill-calls"
      return 0
    }
    # Read by the dynamically sourced production helper.
    # shellcheck disable=SC2034
    REENTER_CONTINUATION_PID=31337
    reenter_forward_signal HUP 129
  ) > "$dir/reuse.out" 2> "$dir/reuse.err" || rc=$?
  [ "$rc" = 129 ] || fail "fenced Windows tree stop returned $rc"
  [ "$(tr '\n' ' ' < "$dir/reuse-taskkill-forces")" = "0 1 " ] ||
    fail "Windows tree stop did not use graceful-then-forced escalation"
  [ ! -s "$dir/reuse-kill-calls" ] ||
    fail "Windows tree stop signaled a reused logical pid"

  # The Windows parent anchor is transparent on ordinary completion too: it
  # must return the continuation's status rather than converting every
  # non-zero child result into a generic wrapper failure.
  for expected in 0 37; do
    rc=0
    (
      set -uo pipefail
      # shellcheck source=/dev/null
      . "$anchor_lib"
      run_reenter_continuation bash -c "exit $expected"
    ) || rc=$?
    [ "$rc" = "$expected" ] ||
      fail "Windows reenter anchor returned $rc for ordinary child exit $expected"
  done

  cat > "$child_script" <<'PY'
import os
import subprocess
import sys
import time

with open(sys.argv[1], "w", encoding="utf-8") as handle:
    handle.write(str(os.getpid()) + "\n")
    handle.flush()
    os.fsync(handle.fileno())
if os.name == "nt":
    grandchild = subprocess.Popen(
        [sys.executable, "-c", "import time\nwhile True: time.sleep(1)"],
        stdin=subprocess.DEVNULL,
    )
    with open(sys.argv[2], "w", encoding="utf-8") as handle:
        handle.write(str(grandchild.pid) + "\n")
        handle.flush()
        os.fsync(handle.fileno())
while True:
    time.sleep(1)
PY
  cat > "$child_wrapper" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
printf '%s\n' "$$" > "$1"
exec python3 "$2" "$3" "$4"
EOF
  chmod +x "$child_wrapper"
  anchored_child_alive() {  # LOGICAL_PID NATIVE_PID
    python3 - "$ROOT/scripts/lib/process_liveness.py" "$1" "$2" <<'PY'
import runpy
import sys

pid_alive = runpy.run_path(sys.argv[1])["pid_alive"]
raise SystemExit(0 if pid_alive(int(sys.argv[2]), native_pid=int(sys.argv[3])) else 1)
PY
  }
  anchor_wait_stopped() {  # PID ATTEMPTS
    local watched_pid="$1" attempts="$2" n=0
    while [ "$n" -lt "$attempts" ]; do
      kill -0 "$watched_pid" 2>/dev/null || return 0
      sleep 0.05
      n=$((n + 1))
    done
    ! kill -0 "$watched_pid" 2>/dev/null
  }
  anchor_taskkill_tree() {  # NATIVE_PID
    python3 - "$1" <<'PY'
import subprocess
import sys

try:
    completed = subprocess.run(
        ["taskkill.exe", "/PID", sys.argv[1], "/T", "/F"],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        timeout=2,
        check=False,
    )
except (OSError, subprocess.TimeoutExpired):
    raise SystemExit(1)
raise SystemExit(completed.returncode)
PY
  }
  anchor_cleanup() {  # PARENT_PID LOGICAL_PID NATIVE_PID GRANDCHILD_PID
    local watched_parent="$1" watched_logical="$2"
    local watched_native="$3" watched_grandchild="$4"
    case "$(uname -s 2>/dev/null || true)" in
      MINGW*|MSYS*|CYGWIN*)
        [ -z "$watched_native" ] || anchor_taskkill_tree "$watched_native" || true
        [ -z "$watched_grandchild" ] || anchor_taskkill_tree "$watched_grandchild" || true
        ;;
    esac
    [ -z "$watched_logical" ] || kill -KILL "$watched_logical" 2>/dev/null || true
    kill -KILL "$watched_parent" 2>/dev/null || true
    anchor_wait_stopped "$watched_parent" 100 || return 1
    wait "$watched_parent" 2>/dev/null || true
  }
  case "$(uname -s 2>/dev/null || true)" in
    MINGW*|MSYS*|CYGWIN*) windows_tree_test=1 ;;
  esac
  for signal in HUP INT TERM; do
    case "$signal" in
      HUP) expected=129 ;;
      INT) expected=130 ;;
      TERM) expected=143 ;;
    esac
    pid_file="$dir/child-$signal.pid"
    grandchild_pid_file="$dir/child-$signal.grandchild-pid"
    logical_pid_file="$dir/child-$signal.logical-pid"
    child_pid=""
    grandchild_pid=""
    logical_pid=""
    (
      set -euo pipefail
      # shellcheck source=/dev/null
      . "$anchor_lib"
      run_reenter_continuation bash "$child_wrapper" \
        "$logical_pid_file" "$child_script" "$pid_file" "$grandchild_pid_file"
    ) > "$dir/$signal.out" 2> "$dir/$signal.err" &
    parent_pid=$!
    i=0
    while [ "$i" -lt 100 ]; do
      if [ -s "$pid_file" ] && [ -s "$logical_pid_file" ] &&
          { [ "$windows_tree_test" = 0 ] || [ -s "$grandchild_pid_file" ]; }; then
        break
      fi
      kill -0 "$parent_pid" 2>/dev/null || break
      sleep 0.05
      i=$((i + 1))
    done
    [ -s "$pid_file" ] && [ -s "$logical_pid_file" ] &&
        { [ "$windows_tree_test" = 0 ] || [ -s "$grandchild_pid_file" ]; } || {
      [ ! -s "$pid_file" ] || IFS= read -r child_pid < "$pid_file"
      [ ! -s "$grandchild_pid_file" ] ||
        IFS= read -r grandchild_pid < "$grandchild_pid_file"
      [ ! -s "$logical_pid_file" ] || IFS= read -r logical_pid < "$logical_pid_file"
      anchor_cleanup "$parent_pid" "$logical_pid" "$child_pid" "$grandchild_pid" || true
      fail "$signal anchor child did not start"
    }
    IFS= read -r child_pid < "$pid_file"
    if [ "$windows_tree_test" = 1 ]; then
      IFS= read -r grandchild_pid < "$grandchild_pid_file"
    fi
    IFS= read -r logical_pid < "$logical_pid_file"
    if ! kill -s "$signal" "$parent_pid" 2>/dev/null; then
      anchor_cleanup "$parent_pid" "$logical_pid" "$child_pid" "$grandchild_pid" || true
      fail "could not signal the $signal anchor parent"
    fi
    if ! anchor_wait_stopped "$parent_pid" 160; then
      anchor_cleanup "$parent_pid" "$logical_pid" "$child_pid" "$grandchild_pid" || true
      fail "$signal anchor parent did not exit after handling"
    fi
    rc=0
    wait "$parent_pid" 2>/dev/null || rc=$?
    if [ "$rc" != "$expected" ]; then
      anchor_cleanup "$parent_pid" "$logical_pid" "$child_pid" "$grandchild_pid" || true
      fail "$signal anchor parent exited $rc instead of $expected"
    fi
    i=0
    while [ "$i" -lt 100 ]; do
      anchored_child_alive "$logical_pid" "$child_pid" || break
      sleep 0.05
      i=$((i + 1))
    done
    if anchored_child_alive "$logical_pid" "$child_pid"; then
      anchor_cleanup "$parent_pid" "$logical_pid" "$child_pid" "$grandchild_pid" || true
      fail "handled $signal left the continuation alive"
    fi
    if [ "$windows_tree_test" = 1 ]; then
      i=0
      while [ "$i" -lt 100 ]; do
        anchored_child_alive "$logical_pid" "$grandchild_pid" || break
        sleep 0.05
        i=$((i + 1))
      done
      if anchored_child_alive "$logical_pid" "$grandchild_pid"; then
        anchor_cleanup "$parent_pid" "$logical_pid" "$child_pid" "$grandchild_pid" || true
        fail "handled $signal left a native grandchild alive"
      fi
    fi
  done
}

test_autopilot_receipt_windows_claim_identity_is_fail_closed() {
  if ! python3 - "$ROOT/scripts/lib/autopilot-receipt.py" \
      "$TMP/receipt-native-identity" <<'PY'
import importlib.util
import json
import os
import pathlib
import sys

helper = pathlib.Path(sys.argv[1])
sys.path.insert(0, str(helper.parent))
spec = importlib.util.spec_from_file_location("autopilot_receipt", helper)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
root = pathlib.Path(sys.argv[2])
root.mkdir(parents=True)
receipt = root / "autopilot-run.json"
ledger = root / "autopilot-reentries.jsonl"
row = {"stage": "proposing", "spec_sha256": "a" * 64,
       "branch": "main", "owner_id": "owner_" + "1" * 32}
module.validate_live = lambda _row, _repo: None
original_os_name = module.os.name
module.os.name = "nt"
try:
    for native in (None, "123", True, 0x100000000):
        claim = {"schema": 1, "kind": "autopilot-drive-claim",
                 "spec_sha256": row["spec_sha256"], "branch": "main",
                 "owner_id": row["owner_id"], "claim_pid": 123}
        if native is not None:
            claim["claim_native_pid"] = native
        ledger.write_text(json.dumps(claim) + "\n", encoding="utf-8")
        result = module.reenter_judgment(receipt, row, str(root), 456, 789, True)
        assert "unproven legacy session claim" in result[0], result
        assert result[1] == 0, result

    claim["claim_pid"] = 1 << 40
    claim["claim_native_pid"] = 321
    ledger.write_text(json.dumps(claim) + "\n", encoding="utf-8")
    result = module.reenter_judgment(receipt, row, str(root), 456, 789, True)
    assert "unproven legacy session claim" in result[0], result
    claim["claim_pid"] = 123

    observed = []
    module.pid_alive = lambda pid, *, native_pid=None: (
        observed.append((pid, native_pid)) or True
    )
    claim["claim_native_pid"] = 321
    for source in (None, "", "native-child-ppid", 7):
        claim.pop("claim_native_pid_source", None)
        if source is not None:
            claim["claim_native_pid_source"] = source
        ledger.write_text(json.dumps(claim) + "\n", encoding="utf-8")
        result = module.reenter_judgment(
            receipt, row, str(root), 456, 789, True)
        assert "unproven legacy session claim" in result[0], result
        assert observed == [], observed

    claim["claim_native_pid_source"] = "msys-proc-v1"
    ledger.write_text(json.dumps(claim) + "\n", encoding="utf-8")
    result = module.reenter_judgment(
        receipt, row, str(root), 456, 789, True)
    assert observed == [(123, 321)], observed
    assert result[3:] == (123, 321), result
finally:
    module.os.name = original_os_name
PY
  then
    fail "autopilot receipt accepted an unproven Windows claim identity"
  fi
}

test_autopilot_receipt_corrupt_lineage_is_fail_closed() {
  if ! python3 - "$ROOT/scripts/lib/autopilot-receipt.py" \
      "$TMP/receipt-corrupt-lineage" <<'PY'
import importlib.util
import json
import pathlib
import shutil
import sys

helper = pathlib.Path(sys.argv[1])
sys.path.insert(0, str(helper.parent))
spec = importlib.util.spec_from_file_location("autopilot_receipt", helper)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
root = pathlib.Path(sys.argv[2])
root.mkdir(parents=True)
receipt = root / "autopilot-run.json"
ledger = root / "autopilot-reentries.jsonl"
row = {"stage": "proposing", "spec_sha256": "a" * 64,
       "branch": "main", "owner_id": "owner_" + "1" * 32}
module.validate_live = lambda _row, _repo: None

def reset_ledger():
    if ledger.is_dir():
        ledger.rmdir()
    elif ledger.exists() or ledger.is_symlink():
        ledger.unlink()

def judgment():
    return module.reenter_judgment(receipt, row, str(root), 456, 789, True)

def assert_unproven(payload=None, directory=False):
    reset_ledger()
    if directory:
        ledger.mkdir()
    else:
        ledger.write_bytes(payload)
    result = judgment()
    assert "unproven" in result[0] and "claim" in result[0], result
    assert result[1:] == (0, 0, 0, 0), result

module.pid_alive = lambda *_args, **_kwargs: (_ for _ in ()).throw(
    AssertionError("unproven lineage must refuse before a liveness probe"))
assert_unproven(b'{"schema":1,"kind":"autopilot-drive-claim"')
assert_unproven(b'[]\n')
assert_unproven(json.dumps({
    "schema": 2, "kind": "autopilot-drive-claim",
    "spec_sha256": row["spec_sha256"], "branch": "main",
    "owner_id": row["owner_id"], "claim_pid": 123,
    "claim_native_pid": 321,
}).encode("utf-8") + b"\n")
assert_unproven(json.dumps({
    "schema": 1, "kind": "autopilot-unknown-record",
    "spec_sha256": row["spec_sha256"], "branch": "main",
}).encode("utf-8") + b"\n")
assert_unproven(directory=True)

reset_ledger()
ledger.write_text("\n", encoding="utf-8")
assert judgment() == ("", 0, 0, 0, 0)
ledger.write_text("\n".join([
    json.dumps({"schema": 1, "kind": "autopilot-reenter", "disposition": "refused",
                "spec_sha256": row["spec_sha256"], "branch": "main"}),
    json.dumps({"schema": 1, "kind": "autopilot-reenter-requeue",
                "spec_sha256": row["spec_sha256"], "branch": "main"}),
]) + "\n", encoding="utf-8")
assert judgment() == ("", 0, 0, 0, 0)

observed = []
module.pid_alive = lambda pid, *, native_pid=None: (
    observed.append((pid, native_pid)) or True)
ledger.write_text(json.dumps({
    "schema": 1, "kind": "autopilot-drive-claim",
    "spec_sha256": row["spec_sha256"], "branch": "main",
    "claim_pid": 123, "claim_native_pid": 321,
}) + "\n", encoding="utf-8")
result = judgment()
assert "unproven" in result[0] and observed == [], (result, observed)
PY
  then
    fail "autopilot receipt ignored corrupt or ambiguous lineage evidence"
  fi
}

test_gc_preserves_unproven_delegation_markers() {
  local project="$TMP/gc-unproven-delegations"
  local markers="$project/.oms/delegations"
  local outside="$project/outside-marker.json"
  local gc_error rc=0

  make_committed_repo "$project"
  mkdir -p "$markers"
  printf '{"schema":4,"id":"outside","pid":999999,"native_pid":999999}\n' > "$outside"
  ln -s "$outside" "$markers/symlink.json"
  printf '{not-json\n' > "$markers/malformed.json"
  printf '{"schema":4,"id":"huge","pid":1099511627776,"native_pid":999999}\n' \
    > "$markers/huge.json"
  python3 - "$markers/oversize.json" <<'PY'
import json, sys
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump({"schema": 4, "id": "oversize", "pid": 999999,
               "native_pid": 999999, "padding": "x" * (65 * 1024)}, handle)
PY

  gc_error="$project/gc-unproven.err"
  (cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply \
    >/dev/null 2>"$gc_error") || fail "gc failed while preserving unproven markers"
  [ -L "$markers/symlink.json" ] || fail "gc followed or deleted a marker symlink"
  [ -f "$markers/malformed.json" ] || fail "gc deleted malformed marker evidence"
  [ -f "$markers/huge.json" ] || fail "gc deleted oversized-pid marker evidence"
  [ -f "$markers/oversize.json" ] || fail "gc deleted oversized marker evidence"
  grep -Fq 'unproven delegation marker' "$gc_error" ||
    fail "gc did not explain preserved marker evidence: $(cat "$gc_error")"

  if command -v mkfifo >/dev/null 2>&1 && mkfifo "$markers/fifo.json" 2>/dev/null; then
    rc=0
    python3 - "$ROOT/scripts/gc.sh" "$project" <<'PY' || rc=$?
import subprocess, sys
try:
    completed = subprocess.run(
        ["bash", sys.argv[1], "--repo", sys.argv[2], "--days", "30", "--apply"],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=5,
    )
except subprocess.TimeoutExpired:
    raise SystemExit(124)
raise SystemExit(completed.returncode)
PY
    [ "$rc" = 0 ] || fail "gc blocked on a FIFO delegation marker, got $rc"
    [ -p "$markers/fifo.json" ] || fail "gc deleted FIFO marker evidence"
  fi

  local linked_project="$TMP/gc-linked-delegation-dir"
  local external_dir="$TMP/gc-external-delegations"
  local external_marker="$external_dir/outside.json"
  make_committed_repo "$linked_project"
  mkdir -p "$linked_project/.oms" "$external_dir"
  printf '{"schema":4,"id":"outside","pid":999999,"native_pid":999999}\n' \
    > "$external_marker"
  ln -s "$external_dir" "$linked_project/.oms/delegations"
  (cd "$linked_project" && "$ROOT/scripts/gc.sh" --days 30 --apply \
    >/dev/null 2> "$linked_project/gc-linked.err") ||
    fail "gc failed while rejecting a linked delegation directory"
  [ -f "$external_marker" ] || fail "gc escaped through the delegation directory symlink"
  grep -Fq 'delegation directory is not a real repo-local directory' \
    "$linked_project/gc-linked.err" ||
    fail "gc did not explain the linked delegation directory refusal"

  local bounded_project="$TMP/gc-bounded-delegation-dir"
  make_committed_repo "$bounded_project"
  mkdir -p "$bounded_project/.oms/delegations"
  python3 - "$bounded_project/.oms/delegations" <<'PY'
import os, sys
for index in range(4097):
    with open(os.path.join(sys.argv[1], "m%04d.json" % index), "w", encoding="utf-8") as handle:
        handle.write('{"schema":4,"id":"m%04d","pid":999999,"native_pid":999999}\n' % index)
PY
  (cd "$bounded_project" && "$ROOT/scripts/gc.sh" --days 30 --apply \
    >/dev/null 2> "$bounded_project/gc-bounded.err") ||
    fail "gc failed while rejecting an over-budget delegation directory"
  [ -f "$bounded_project/.oms/delegations/m0000.json" ] ||
    fail "gc partially swept an over-budget delegation directory"
  grep -Fq 'delegation directory exceeds bounds or changed' \
    "$bounded_project/gc-bounded.err" ||
    fail "gc did not explain the delegation entry bound"
}

test_gc_marker_delete_cas_preserves_atomic_live_replacement() {
  local project="$TMP/gc-marker-delete-cas"
  local plan="$ROOT/scripts/agent-plan.sh"
  local marker lease native_pid real_python python_bin
  local snapshot_ready="$project/marker-snapshot-ready"
  local snapshot_release="$project/marker-snapshot-release"
  local i gc_pid

  make_committed_repo "$project"
  "$plan" --repo "$project" init --goal "marker delete CAS" >/dev/null
  "$plan" --repo "$project" add --id t1 --title one >/dev/null
  "$plan" --repo "$project" claim --id t1 --provider codex >/dev/null
  lease="$("$plan" --repo "$project" show --id t1 |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  mkdir -p "$project/.oms/delegations"
  marker="$project/.oms/delegations/same.json"
  printf '{"schema":4,"id":"dead","pid":999999,"native_pid":999999,"task_id":"t1","lease_id":"%s"}\n' \
    "$lease" > "$marker"

  # Pause the exact bounded snapshot after it has read the dead generation but
  # before its shared marker-set lock is released. The replacement below is
  # deliberately non-cooperative so the final digest+identity CAS is exercised.
  real_python="$(command -v python3)"
  python_bin="$project/python-bin"
  mkdir -p "$python_bin"
  cat > "$python_bin/python3" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
if [ "${1:-}" = - ] && [ "${4:-}" = "$OMS_T_LIVENESS_HELPER" ]; then
  snapshot_script="$(mktemp)"
  cat > "$snapshot_script"
  snapshot_rc=0
  "$OMS_T_REAL_PYTHON" "$@" < "$snapshot_script" || snapshot_rc=$?
  : > "$OMS_T_SNAPSHOT_READY"
  while [ ! -f "$OMS_T_SNAPSHOT_RELEASE" ]; do sleep 0.05; done
  rm -f "$snapshot_script"
  exit "$snapshot_rc"
fi
exec "$OMS_T_REAL_PYTHON" "$@"
EOF
  chmod +x "$python_bin/python3"

  (cd "$project" && \
    PATH="$python_bin:$PATH" OMS_T_REAL_PYTHON="$real_python" \
    OMS_T_LIVENESS_HELPER="$ROOT/scripts/lib/process_liveness.py" \
    OMS_T_SNAPSHOT_READY="$snapshot_ready" \
    OMS_T_SNAPSHOT_RELEASE="$snapshot_release" \
    "$ROOT/scripts/gc.sh" --days 30 --apply \
    > "$project/gc-cas.out" 2> "$project/gc-cas.err") &
  gc_pid=$!
  for i in $(seq 1 100); do
    [ -f "$snapshot_ready" ] && break
    kill -0 "$gc_pid" 2>/dev/null || break
    sleep 0.05
  done
  [ -f "$snapshot_ready" ] || {
    : > "$snapshot_release"
    wait "$gc_pid" 2>/dev/null || true
    fail "gc never completed the bounded delegation marker snapshot"
  }

  native_pid="$(
    # shellcheck source=scripts/lib/file-lock.sh
    . "$ROOT/scripts/lib/file-lock.sh"
    oms_process_native_pid "$$"
  )" || fail "could not resolve the replacement marker's native pid"
  native_pid="${native_pid//$'\r'/}"
  python3 - "$marker" "$$" "$native_pid" <<'PY'
import json, os, sys, tempfile
path = sys.argv[1]
row = {"schema": 4, "id": "replacement", "pid": int(sys.argv[2]),
       "native_pid": int(sys.argv[3])}
fd, temporary = tempfile.mkstemp(dir=os.path.dirname(path))
with os.fdopen(fd, "w", encoding="utf-8") as handle:
    json.dump(row, handle)
    handle.flush()
    os.fsync(handle.fileno())
os.replace(temporary, path)
PY
  : > "$snapshot_release"
  wait "$gc_pid" || fail "gc failed during marker replacement race"

  [ -f "$marker" ] || fail "gc deleted an atomic live replacement by stale pathname"
  grep -Fq '"id": "replacement"' "$marker" ||
    fail "gc did not preserve the replacement marker generation"
  "$plan" --repo "$project" show --id t1 | grep -Fq '"state": "ready"' ||
    fail "gc did not recover the exact dead lease before the marker CAS"
  grep -Fq 'delegation marker generation changed; kept it' "$project/gc-cas.err" ||
    fail "gc did not report the failed marker generation CAS"
}

test_gc_dead_marker_cannot_fail_live_same_executor() {
  local project="$TMP/gc-live-same-executor"
  local executor="$ROOT/scripts/agent-executor.sh"
  local meta markers dry_out rc=0

  make_committed_repo "$project"
  meta="$project/.oms/executors/exact/meta.json"
  markers="$project/.oms/delegations"
  mkdir -p "$(dirname "$meta")" "$markers"
  printf '{"schema":1,"executor_id":"exact","state":"running","updated_at":"2026-01-01T00:00:00Z"}\n' > "$meta"
  printf '{"schema":3,"id":"old","pid":999999,"executor_id":"exact"}\n' \
    > "$markers/a-old.json"
  printf '{"schema":3,"id":"retry","pid":%d,"executor_id":"exact"}\n' "$$" \
    > "$markers/z-live.json"

  dry_out="$(cd "$project" && "$ROOT/scripts/gc.sh" --days 30 2>&1)"
  printf '%s' "$dry_out" | grep -Fq 'executor exact changed or has a live exact worker; kept it' ||
    fail "executor dry-run did not apply the locked live-marker veto: $dry_out"
  if printf '%s' "$dry_out" | grep -Fq 'orphan-delegation-executor: exact running -> failed'; then
    fail "executor dry-run falsely planned failure of a live retry: $dry_out"
  fi
  grep -Fq '"state":"running"' "$meta" || fail "executor dry-run changed metadata"
  [ -f "$markers/a-old.json" ] || fail "executor dry-run removed its trigger marker"

  (cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply >/dev/null 2>&1)
  grep -Fq '"state":"running"' "$meta" || fail "a dead marker failed a live same-id executor"
  assert_not_exists "$markers/a-old.json"
  [ -f "$markers/z-live.json" ] || fail "gc removed the live executor marker"

  mkdir -p "$project/.oms/executors/gcdead"
  printf '{"schema":1,"executor_id":"gcdead","state":"running"}\n' \
    > "$project/.oms/executors/gcdead/meta.json"
  printf '{"schema":3,"id":"gcdead","pid":999999,"executor_id":"gcdead"}\n' \
    > "$markers/gcdead.json"
  dry_out="$(cd "$project" && "$ROOT/scripts/gc.sh" --days 30 2>&1)"
  printf '%s' "$dry_out" | grep -Fq 'orphan-delegation-executor: gcdead running -> failed' ||
    fail "gc dry-run omitted an eligible exact executor recovery: $dry_out"
  grep -Fq '"state":"running"' "$project/.oms/executors/gcdead/meta.json" ||
    fail "eligible executor dry-run mutated metadata"
  (cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply >/dev/null 2>&1)
  grep -Fq '"state": "failed"' "$project/.oms/executors/gcdead/meta.json" ||
    fail "gc did not apply eligible exact executor recovery"
  assert_not_exists "$markers/gcdead.json"

  # A malformed exact marker is not evidence of death.
  printf '{"schema":1,"executor_id":"malformed","state":"running"}\n' \
    > "$project/.oms/executors/malformed-meta.json"
  mkdir -p "$project/.oms/executors/malformed"
  mv "$project/.oms/executors/malformed-meta.json" \
    "$project/.oms/executors/malformed/meta.json"
  printf '{"schema":3,"id":"bad","pid":"?","executor_id":"malformed"}\n' \
    > "$markers/malformed.json"
  rc=0
  "$executor" recover --repo "$project" --id malformed --expected-state running \
    --markers-dir "$markers" --check >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "malformed exact executor marker must veto recovery, got $rc"
  grep -Fq '"state":"running"' "$project/.oms/executors/malformed/meta.json" ||
    fail "malformed marker recovery changed executor state"

  mkdir -p "$project/.oms/executors/hugepid"
  printf '{"schema":1,"executor_id":"hugepid","state":"running"}\n' \
    > "$project/.oms/executors/hugepid/meta.json"
  printf '{"schema":4,"id":"hugepid","pid":1099511627776,"native_pid":999999,"executor_id":"hugepid"}\n' \
    > "$markers/hugepid.json"
  rc=0
  "$executor" recover --repo "$project" --id hugepid --expected-state running \
    --markers-dir "$markers" --check >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "oversized exact executor pid must veto recovery, got $rc"

  # The state read by GC is a CAS input, not a hint: a later terminal state
  # must survive the exact locked recovery verb.
  printf '{"schema":1,"executor_id":"drift","state":"done"}\n' \
    > "$project/.oms/executors/drift-meta.json"
  mkdir -p "$project/.oms/executors/drift"
  mv "$project/.oms/executors/drift-meta.json" "$project/.oms/executors/drift/meta.json"
  rc=0
  "$executor" recover --repo "$project" --id drift --expected-state running \
    --markers-dir "$markers" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "executor state-CAS drift must exit 3, got $rc"
  grep -Fq '"state":"done"' "$project/.oms/executors/drift/meta.json" ||
    fail "executor recovery overwrote a terminal transition"

  mkdir -p "$project/.oms/executors/deadonly"
  printf '{"schema":1,"executor_id":"deadonly","state":"running"}\n' \
    > "$project/.oms/executors/deadonly/meta.json"
  printf '{"schema":3,"id":"deadonly","pid":999999,"executor_id":"deadonly"}\n' \
    > "$markers/deadonly.json"
  local windows_bin="$project/executor-windows-bin"
  mkdir -p "$windows_bin"
  printf '%s\n' '#!/usr/bin/env bash' 'printf "MINGW64_NT-10.0\\n"' > "$windows_bin/uname"
  cat > "$windows_bin/cygpath" <<'EOF'
#!/usr/bin/env bash
if [ "${1:-}" = -m ] && [ "${2:-}" = /c/oms-executor-fixture/.oms/delegations ]; then
  printf '%s\r\n' "$OMS_T_EXECUTOR_WINDOWS_MARKERS"
else
  printf '%s\r\n' "${2:-}"
fi
EOF
  chmod +x "$windows_bin/uname" "$windows_bin/cygpath"
  PATH="$windows_bin:$PATH" OMS_T_EXECUTOR_WINDOWS_MARKERS="$markers" \
    "$executor" recover --repo "$project" --id deadonly --expected-state running \
      --markers-dir /c/oms-executor-fixture/.oms/delegations --check >/dev/null ||
    fail "executor check did not normalize Git Bash /c path and CRLF"
  grep -Fq '"state":"running"' "$project/.oms/executors/deadonly/meta.json" ||
    fail "executor check-only changed an eligible executor"
  "$executor" recover --repo "$project" --id deadonly --expected-state running \
    --markers-dir "$markers" >/dev/null || fail "eligible dead executor did not recover"
  grep -Fq '"state": "failed"' "$project/.oms/executors/deadonly/meta.json" ||
    fail "executor apply did not fail the exact dead worker"

  rc=0
  OMS_HARNESS_CHILD=1 "$executor" recover --repo "$project" --id malformed \
    --expected-state running --markers-dir "$markers" --check \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "a harness child reached parent executor recovery, got $rc"

  local outside="$TMP/executor-recovery-outside"
  mkdir -p "$outside" "$project/.oms/executors"
  printf '{"schema":1,"executor_id":"escape","state":"running"}\n' \
    > "$outside/meta.json"
  ln -s "$outside" "$project/.oms/executors/escape"
  rc=0
  "$executor" recover --repo "$project" --id escape --expected-state running \
    --markers-dir "$markers" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "executor recovery followed a symlinked metadata directory, got $rc"
  grep -Fq '"state":"running"' "$outside/meta.json" ||
    fail "executor recovery mutated metadata outside the repository"
  printf '{"schema":4,"id":"escape","pid":999999,"native_pid":999999,"executor_id":"escape"}\n' \
    > "$markers/escape.json"
  (cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply \
    >/dev/null 2> "$project/gc-escape.err") ||
    fail "gc failed while refusing escaped executor metadata"
  [ -f "$markers/escape.json" ] ||
    fail "gc deleted trigger evidence after executor recovery rc=2"
  grep -Fq 'delegation recovery was unproven' "$project/gc-escape.err" ||
    fail "gc did not explain preserved recovery evidence"

  printf '{"schema":1,"executor_id":"..","state":"running","sentinel":"keep"}\n' \
    > "$project/.oms/meta.json"
  printf 'executor soul\n' > "$project/dotdot-soul.md"
  for dotdot_action in show recover create; do
    rc=0
    case "$dotdot_action" in
      show)
        "$executor" show --repo "$project" --id .. >/dev/null 2>&1 || rc=$?
        ;;
      recover)
        "$executor" recover --repo "$project" --id .. --expected-state running \
          --markers-dir "$markers" >/dev/null 2>&1 || rc=$?
        ;;
      create)
        "$executor" create --repo "$project" --id .. --provider codex \
          --soul-file "$project/dotdot-soul.md" >/dev/null 2>&1 || rc=$?
        ;;
    esac
    [ "$rc" = 2 ] || fail "executor $dotdot_action accepted traversal id .., got $rc"
  done
  grep -Fq '"sentinel":"keep"' "$project/.oms/meta.json" ||
    fail "executor traversal id mutated repository metadata"
}

test_gc_preserves_trigger_when_referenced_state_is_unproven() {
  local project="$TMP/gc-unproven-referenced-state"
