test_agent_plan_owner_recovery_is_fenced() {
  local project="$TMP/plan-owner-recovery"
  local sh="$ROOT/scripts/agent-plan.sh"
  local markers="$project/.oms/delegations"
  local owner="owner_11111111111111111111111111111111"
  local other="owner_22222222222222222222222222222222"
  local dead_pid lease_live lease_dead lease_other lease_review lease_markerless lease_badmarker
  local out rc=0

  make_committed_repo "$project"
  "$sh" --repo "$project" init --goal "owner-fenced recovery" >/dev/null
  for id in claimed live dead other review markerless badmarker; do
    "$sh" --repo "$project" add --id "$id" --title "$id" >/dev/null
  done

  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id claimed --provider codex >/dev/null
  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id live --provider codex >/dev/null
  lease_live="$("$sh" --repo "$project" show --id live |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" start --id live --lease-id "$lease_live" >/dev/null

  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id dead --provider codex >/dev/null
  lease_dead="$("$sh" --repo "$project" show --id dead |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" start --id dead --lease-id "$lease_dead" >/dev/null

  OMS_AUTOPILOT_OWNER_ID="$other" \
    "$sh" --repo "$project" claim --id other --provider claude >/dev/null
  lease_other="$("$sh" --repo "$project" show --id other |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" start --id other --lease-id "$lease_other" >/dev/null

  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id review --provider codex >/dev/null
  lease_review="$("$sh" --repo "$project" show --id review |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" review --id review --lease-id "$lease_review" >/dev/null

  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id markerless --provider codex >/dev/null
  lease_markerless="$("$sh" --repo "$project" show --id markerless |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" start --id markerless --lease-id "$lease_markerless" >/dev/null

  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id badmarker --provider codex >/dev/null
  lease_badmarker="$("$sh" --repo "$project" show --id badmarker |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" start --id badmarker --lease-id "$lease_badmarker" >/dev/null

  sh -c ':' & dead_pid=$!
  wait "$dead_pid" 2>/dev/null || true
  mkdir -p "$markers"
  printf '{"schema":3,"id":"live","pid":%d,"task_id":"live","lease_id":"%s","autopilot_owner_id":"%s"}\n' \
    "$$" "$lease_live" "$owner" > "$markers/live.json"
  printf '{"schema":3,"id":"dead","pid":%d,"task_id":"dead","lease_id":"%s","autopilot_owner_id":"%s"}\n' \
    "$dead_pid" "$lease_dead" "$owner" > "$markers/dead.json"
  printf '{"schema":3,"id":"review","pid":%d,"task_id":"review","lease_id":"%s","autopilot_owner_id":"%s"}\n' \
    "$dead_pid" "$lease_review" "$owner" > "$markers/review.json"
  printf '{"schema":3,"id":"badmarker","pid":"not-a-pid","task_id":"badmarker","lease_id":"%s","autopilot_owner_id":"%s"}\n' \
    "$lease_badmarker" "$owner" > "$markers/badmarker.json"

  rc=0
  OMS_HARNESS_CHILD=1 "$sh" --repo "$project" recover-owner \
    --owner-id "$owner" --markers-dir "$markers" --json \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "a harness child reached owner recovery, got $rc"
  "$sh" --repo "$project" show --id claimed | grep -Fq '"state": "claimed"' ||
    fail "child owner recovery changed parent authority"

  out="$("$sh" --repo "$project" recover-owner --owner-id "$owner" \
    --markers-dir "$markers" --json)" ||
    fail "owner recovery failed: $out"
  OMS_OWNER_RECOVERY="$out" python3 - <<'PY' || fail "owner recovery returned the wrong task set: $out"
import json
import os

row = json.loads(os.environ["OMS_OWNER_RECOVERY"])
assert row["recovered"] == ["claimed", "dead"], row
assert sorted(row["preserved"]) == ["badmarker", "live", "markerless", "review"], row
PY
  for id in claimed dead; do
    "$sh" --repo "$project" show --id "$id" | grep -Fq '"state": "ready"' ||
      fail "owner recovery did not requeue $id"
  done
  for id in live markerless badmarker; do
    "$sh" --repo "$project" show --id "$id" | grep -Fq '"state": "running"' ||
      fail "owner recovery stole live or unproven task $id"
  done
  "$sh" --repo "$project" show --id other | grep -Fq '"state": "running"' ||
    fail "owner recovery stole another owner's task"
  "$sh" --repo "$project" show --id review | grep -Fq '"state": "review"' ||
    fail "owner recovery requeued review evidence"

  rc=0
  "$sh" --repo "$project" recover-lease --id review --lease-id "$lease_review" \
    --expected-state review --markers-dir "$markers" \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "atomic lease recovery must refuse review, got $rc"
  "$sh" --repo "$project" show --id review | grep -Fq '"state": "review"' ||
    fail "atomic lease recovery changed review state"

  rc=0
  "$sh" --repo "$project" recover-lease --id other --lease-id stale-lease \
    --expected-state running --markers-dir "$markers" \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "atomic lease recovery must refuse a stale lease, got $rc"
  "$sh" --repo "$project" show --id other | grep -Fq '"state": "running"' ||
    fail "stale lease recovery changed the current worker"

  rc=0
  "$sh" --repo "$project" recover-lease --id live --lease-id "$lease_live" \
    --expected-state running --markers-dir "$markers" \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "a live exact marker must veto lease recovery, got $rc"
  "$sh" --repo "$project" show --id live | grep -Fq '"state": "running"' ||
    fail "lease recovery stole a task with an exact live marker"

  rc=0
  "$sh" --repo "$project" recover-lease --id markerless --lease-id "$lease_markerless" \
    --expected-state claimed --markers-dir "$markers" \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "an expected-state mismatch must veto lease recovery, got $rc"
  "$sh" --repo "$project" show --id markerless | grep -Fq '"state": "running"' ||
    fail "state-CAS recovery changed a task after its observed transition"

  # Simulate native Windows Git Bash without depending on a Windows runner:
  # /c/... is translated by cygpath and its CRLF output must be stripped before
  # the embedded native Python compares the physical marker directory.
  local windows_bin="$project/windows-bin"
  mkdir -p "$windows_bin"
  printf '%s\n' '#!/usr/bin/env bash' 'printf "MINGW64_NT-10.0\\n"' > "$windows_bin/uname"
  cat > "$windows_bin/cygpath" <<'EOF'
#!/usr/bin/env bash
if [ "${1:-}" = -m ] && [ "${2:-}" = /c/oms-owner-fixture/.oms/delegations ]; then
  printf '%s\r\n' "$OMS_T_WINDOWS_MARKERS"
else
  printf '%s\r\n' "${2:-}"
fi
EOF
  chmod +x "$windows_bin/uname" "$windows_bin/cygpath"
  PATH="$windows_bin:$PATH" OMS_T_WINDOWS_MARKERS="$markers" \
    "$sh" --repo "$project" recover-owner --owner-id "$owner" \
      --markers-dir /c/oms-owner-fixture/.oms/delegations --json >/dev/null ||
    fail "Git Bash /c marker path did not reach native Python canonically"
}

test_gc_keeps_orphan_artifacts_unless_asked() {
  local project="$TMP/gc-orphan-artifacts"
  local index orphan out

  make_committed_repo "$project"
  mkdir -p "$project/.oms/artifacts/ask"
  index="$project/.oms/artifacts/index.jsonl"
  orphan="$project/.oms/artifacts/ask/council-answer.md"
  printf 'a council answer a later round still cites\n' > "$orphan"
  printf '{"ts":"2026-06-11T00:00:01Z","kind":"call","event_id":"evt_kept","artifact":".oms/artifacts/ask/kept.md"}\n' > "$index"
  printf 'kept\n' > "$project/.oms/artifacts/ask/kept.md"

  # Rows are retention; an orphaned file is the evidence itself, and its row was
  # retired by an earlier prune at a lower floor. Riding that deletion along
  # with the routine sweep is what made the sweep unrunnable here: seventeen
  # artifacts, including 08-02 council answers, would have gone with it.
  out="$(cd "$project" && OMS_ARTIFACT_ORPHAN_GRACE=0 "$ROOT/scripts/gc.sh" --days 0 --apply)"
  [ -f "$orphan" ] ||
    fail "the routine sweep must not delete an unreferenced artifact: $out"
  printf '%s' "$out" | grep -Fq 'would delete' &&
    fail "the routine sweep must not even plan a file deletion: $out"

  out="$(cd "$project" && OMS_ARTIFACT_ORPHAN_GRACE=0 "$ROOT/scripts/gc.sh" --days 0 --apply --delete-orphan-files)"
  [ ! -f "$orphan" ] ||
    fail "--delete-orphan-files must remove the unreferenced artifact: $out"
  [ -f "$project/.oms/artifacts/ask/kept.md" ] ||
    fail "a referenced artifact must survive either way: $out"
}

test_gc_maintains_the_lifecycle_stream() {
  local project="$TMP/gc-lifecycle"
  local events="$ROOT/scripts/agent-events.sh"
  local stuck finished out state

  make_committed_repo "$project"
  stuck="$("$events" --repo "$project" start --provider codex --tool peer-delegate)"
  "$events" --repo "$project" transition --attempt "$stuck" --state starting --actor test >/dev/null
  "$events" --repo "$project" transition --attempt "$stuck" --state working --actor test >/dev/null
  finished="$("$events" --repo "$project" start --provider codex --tool ask)"
  for state in starting working verifying review "done"; do
    "$events" --repo "$project" transition --attempt "$finished" --state "$state" --actor test >/dev/null
  done

  # Backdated rather than raced against the clock: compaction compares the
  # terminal attempt's own stamp with the cutoff, and a fixture that finishes
  # inside the same second as the sweep is not old enough by either reading.
  OMS_GC_FIXTURE_ATTEMPT="$finished" python3 - "$project/.oms/lifecycle/events.jsonl" <<'FIXTURE_PY'
import json, os, sys

target = os.environ["OMS_GC_FIXTURE_ATTEMPT"]
path = sys.argv[1]
lines = []
with open(path, encoding="utf-8") as handle:
    for line in handle:
        if not line.strip():
            continue
        row = json.loads(line)
        if row.get("attempt_id") == target:
            row["ts"] = "2026-01-01T00:00:00Z"
        lines.append(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n")
with open(path, "w", encoding="utf-8") as handle:
    handle.writelines(lines)
FIXTURE_PY

  # reconcile shipped tested and unreachable: nothing in the product called it,
  # so a worker that died mid-flight left its attempt non-terminal forever.
  # Compaction of the terminal one is the sweep's existing behavior, asserted
  # here because the two halves have to agree on which streams survive.
  out="$(cd "$project" && OMS_ATTEMPT_STALE_SECONDS=0 "$ROOT/scripts/gc.sh" --days 1 --apply)"
  printf '%s' "$out" | grep -Fq "stale-attempt: $stuck" ||
    fail "gc should reconcile an attempt that stopped reporting: $out"
  "$events" --repo "$project" show --attempt "$stuck" --json |
    grep -Fq '"state": "blocked"' ||
    fail "a reconciled attempt should be blocked so the inbox can name it"
  "$events" --repo "$project" show --attempt "$stuck" --json |
    grep -Fq '"reason_code": "heartbeat_expired"' ||
    fail "the reconciled attempt should say why it was closed"
  ! grep -Fq "$finished" "$project/.oms/lifecycle/events.jsonl" ||
    fail "gc should compact the stream of a long-terminal attempt"
  grep -Fq "$stuck" "$project/.oms/lifecycle/events.jsonl" ||
    fail "a non-terminal attempt's stream must survive compaction"
}

test_gc_sweeps_stale_change_guard() {
  local project="$TMP/gc-guard"

  make_committed_repo "$project"
  ( cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . begin >/dev/null )
  [ -f "$project/.oms/guards/change-guard.tsv" ] || fail "guard snapshot missing"
  # Fresh guard survives.
  ( cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply >/dev/null 2>&1 )
  [ -f "$project/.oms/guards/change-guard.tsv" ] || fail "gc must keep a fresh guard"
  # Backdate the started stamp: an abandoned guard is swept.
  python3 - "$project/.oms/guards/change-guard.tsv" <<'PY'
import sys
p = sys.argv[1]
lines = []
for line in open(p):
    if line.startswith("started\t"):
        line = "started\t1000000000\n"
    lines.append(line)
open(p, "w").writelines(lines)
PY
  local out
  out="$(cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply 2>&1)"
  printf '%s' "$out" | grep -Fq "stale-change-guard" || fail "gc should report the stale guard"
  assert_not_exists "$project/.oms/guards/change-guard.tsv"
}

test_change_guard_status_flags_stale() {
  local project="$TMP/guard-stale-status"

  make_committed_repo "$project"
  ( cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . begin >/dev/null )
  local out
  out="$(cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . status)"
  printf '%s' "$out" | grep -Fq "STALE" && fail "fresh guard must not read as stale"
  out="$(cd "$project" && OMS_GUARD_TTL=0 sh -c 'sleep 1; exec "$0" --repo . status' "$ROOT/scripts/change-guard.sh")"
  printf '%s' "$out" | grep -Fq "STALE" || fail "aged guard should read as stale with OMS_GUARD_TTL=0"
  # A dead opt-in owner pid is stale regardless of age.
  ( cd "$project" && OMS_GUARD_PID=999999 "$ROOT/scripts/change-guard.sh" --repo . begin >/dev/null )
  out="$(cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . status)"
  printf '%s' "$out" | grep -Fq "STALE" || fail "dead owner pid should read as stale"
  ( cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . end >/dev/null )
}

test_patch_land_reject_records_and_resolves_fail_ledger() {
  local project="$TMP/land-ledger"
  local err1="$TMP/land-ledger.err1"
  local out2="$TMP/land-ledger.out2"
  local err2="$TMP/land-ledger.err2"

  make_committed_repo "$project"
  printf 'change\n' >> "$project/file.txt"
  ( cd "$project" && git diff > "$TMP/land-ledger.patch" && git checkout -- file.txt )
  local rc=0
  ( cd "$project" && "$ROOT/scripts/patch-land.sh" --patch "$TMP/land-ledger.patch" --verify false ) \
    >/dev/null 2>"$err1" || rc=$?
  [ "$rc" = "1" ] || fail "rejected land should exit 1, got $rc"
  ( cd "$project" && "$ROOT/scripts/fail-ledger.sh" list ) | grep -Fq "patch-land REJECT" ||
    fail "rejection should be recorded in the fail-ledger"
  # Second attempt warns about the known rejection, then lands and resolves it.
  ( cd "$project" && "$ROOT/scripts/patch-land.sh" --patch "$TMP/land-ledger.patch" --verify true ) \
    >"$out2" 2>"$err2" || fail "admissible retry should land"
  assert_file_contains "$err2" "rejected before"
  assert_file_contains "$out2" "LANDED"
  ( cd "$project" && "$ROOT/scripts/fail-ledger.sh" list --unresolved ) | grep -Fq "patch-land REJECT" &&
    fail "successful land should resolve the recorded rejection"
  assert_file_contains "$project/file.txt" "change"
}

test_patch_land_plan_task_supplies_patch() {
  local project="$TMP/land-plan-patch"
  local out="$TMP/land-plan.out"
  local err="$TMP/land-plan.err"

  make_committed_repo "$project"
  printf 'from-plan\n' >> "$project/file.txt"
  ( cd "$project" && git diff > "$TMP/land-plan.patch" && git checkout -- file.txt )
  "$ROOT/scripts/agent-plan.sh" --repo "$project" init --goal g >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" add --id t1 --title T --verify true >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" claim --id t1 --provider codex >/dev/null
  printf 'review\n' > "$TMP/land-plan.md"
  "$ROOT/scripts/agent-plan.sh" --repo "$project" review --id t1 --artifact "$TMP/land-plan.md" --patch "$TMP/land-plan.patch" >/dev/null

  ( cd "$project" && "$ROOT/scripts/patch-land.sh" --plan-task t1 --verify true ) \
    >"$out" 2>"$err" || fail "--plan-task with stored patch should land"
  assert_file_contains "$err" "using patch from plan task t1"
  assert_file_contains "$project/file.txt" "from-plan"
  "$ROOT/scripts/agent-plan.sh" --repo "$project" show --id t1 | grep -Fq '"state": "done"' ||
    fail "landed plan task should be done"
  # Without a stored patch it must fail loudly, not guess.
  "$ROOT/scripts/agent-plan.sh" --repo "$project" add --id t2 --title T2 --verify true >/dev/null
  local rc=0
  ( cd "$project" && "$ROOT/scripts/patch-land.sh" --plan-task t2 ) >/dev/null 2>"$project/err2" || rc=$?
  [ "$rc" = "2" ] || fail "--plan-task without stored patch should exit 2, got $rc"
  assert_file_contains "$project/err2" "no stored patch path"
}

test_patch_land_rejects_stale_review_patch_lease() {
  local project="$TMP/land-stale-review-lease"
  local plan="$ROOT/scripts/agent-plan.sh"
  local rc=0

  make_committed_repo "$project"
  printf 'stale-work\n' >> "$project/file.txt"
  (cd "$project" && git diff > "$TMP/land-stale-review.patch" && git checkout -- file.txt)
  "$plan" --repo "$project" init --goal g >/dev/null
  "$plan" --repo "$project" add --id t1 --title T --verify true >/dev/null
  "$plan" --repo "$project" claim --id t1 --provider codex >/dev/null
  "$plan" --repo "$project" review --id t1 --patch "$TMP/land-stale-review.patch" >/dev/null
  "$plan" --repo "$project" reclaim --include-review --ttl 0 >/dev/null
  "$plan" --repo "$project" claim --id t1 --provider claude >/dev/null

  (cd "$project" && "$ROOT/scripts/patch-land.sh" --plan-task t1 --verify true) \
    >/dev/null 2>"$project/err" || rc=$?
  [ "$rc" = 2 ] || fail "stale stored review patch should be rejected before admission"
  assert_file_contains "$project/err" "not review"
  rc=0
  (cd "$project" && "$ROOT/scripts/patch-land.sh" --plan-task t1 \
    --patch "$TMP/land-stale-review.patch" --verify true) \
    >/dev/null 2>"$project/explicit.err" || rc=$?
  [ "$rc" = 2 ] || fail "explicit --patch must not bypass the stale review lease fence"
  assert_file_contains "$project/explicit.err" "not review"
  if grep -Fq stale-work "$project/file.txt"; then
    fail "a re-claimed task must not land the previous review's stored patch"
  fi
  "$plan" --repo "$project" show --id t1 | grep -Fq '"state": "claimed"' ||
    fail "stale patch rejection must preserve the new claim"
}

test_agent_plan_reclaim_include_review() {
  local d="$TMP/plan-reclaim-review"
  local SH="$ROOT/scripts/agent-plan.sh"

  mkdir -p "$d"
  "$SH" --repo "$d" init --goal "review reclaim" >/dev/null
  "$SH" --repo "$d" add --id t1 --title one >/dev/null
  "$SH" --repo "$d" claim --id t1 --provider codex >/dev/null
  "$SH" --repo "$d" review --id t1 --patch /tmp/p.patch >/dev/null
  # Fresh review is kept even with the flag (24h default TTL).
  "$SH" --repo "$d" reclaim --include-review >/dev/null
  "$SH" --repo "$d" show --id t1 | grep -Fq '"state": "review"' ||
    fail "a fresh review must survive reclaim --include-review"
  python3 - "$d/.oms/plan/tasks.json" <<'PY'
import json, sys
p = sys.argv[1]
d = json.load(open(p))
d["tasks"]["t1"]["updated"] = "2020-01-01T00:00:00Z"
json.dump(d, open(p, "w"))
PY
  # Aged review is only reclaimed with the opt-in flag.
  "$SH" --repo "$d" reclaim >/dev/null
  "$SH" --repo "$d" show --id t1 | grep -Fq '"state": "review"' ||
    fail "default reclaim must never touch review"
  local out
  out="$("$SH" --repo "$d" reclaim --include-review)"
  printf '%s' "$out" | grep -Fq "reclaimed t1 from review" || fail "aged review should be reclaimed with the flag"
  "$SH" --repo "$d" show --id t1 | grep -Fq '"patch": "/tmp/p.patch"' ||
    fail "reclaiming a review must keep its artifact/patch"
}

test_repo_state_flags_stale_review_and_guard() {
  local project="$TMP/state-stale"

  make_committed_repo "$project"
  "$ROOT/scripts/agent-plan.sh" --repo "$project" init --goal g >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" add --id t1 --title T >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" claim --id t1 --provider codex >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" review --id t1 >/dev/null
  python3 - "$project/.oms/plan/tasks.json" <<'PY'
import json, sys
p = sys.argv[1]
d = json.load(open(p))
d["tasks"]["t1"]["updated"] = "2020-01-01T00:00:00Z"
json.dump(d, open(p, "w"))
PY
  ( cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . begin >/dev/null )
  local out
  out="$(cd "$project" && OMS_GUARD_TTL=0 sh -c 'sleep 1; exec "$0" --repo .' "$ROOT/scripts/state.sh")"
  printf '%s' "$out" | grep -Fq "STALE review" || fail "repo-state should flag the stale review"
  printf '%s' "$out" | grep -Fq "Change-guard: ACTIVE (STALE" || fail "repo-state should flag the stale guard"
  ( cd "$project" && "$ROOT/scripts/state.sh" --repo . --json ) |
    python3 -c 'import json,sys; d=json.load(sys.stdin); assert d["plan"]["stale_review"][0]["id"]=="t1"' ||
    fail "stale review should be in the JSON view"
}

test_run_with_timeout_kill_after_defeats_term_trap() {
  local out="$TMP/rwt-kill-out"
  local rc=0

  # A worker that ignores SIGTERM must still die: --kill-after escalates to
  # SIGKILL, so the wall clock stays a real bound (GNU timeout exits 137).
  bash -c ". '$ROOT/scripts/lib/peer-common.sh'; \
    OMS_PEER_TIMEOUT=1 OMS_PEER_KILL_AFTER=1 \
    run_with_timeout bash -c 'trap \"\" TERM; sleep 30'" >"$out" 2>&1 || rc=$?
  [ "$rc" = "137" ] || [ "$rc" = "124" ] || fail "TERM-immune worker should be killed (got rc=$rc)"
  [ "$rc" = "137" ] || {
    # 124 without kill-after support would mean the sleep is still alive.
    command -v timeout >/dev/null 2>&1 && timeout --kill-after 1 5 true >/dev/null 2>&1 &&
      fail "GNU timeout present but worker was not SIGKILLed (rc=$rc)"
  }
}

test_run_with_timeout_require_refuses_unbounded() {
  local err="$TMP/rwt-require-err"
  local rc=0

  bash -c ". '$ROOT/scripts/lib/peer-common.sh'; \
    OMS_REQUIRE_TIMEOUT=1 PATH='' run_with_timeout /bin/echo should-not-run" \
    >"$TMP/rwt-require-out" 2>"$err" || rc=$?
  [ "$rc" = "127" ] || fail "OMS_REQUIRE_TIMEOUT=1 without a timeout binary should refuse with 127, got $rc"
  assert_file_contains "$err" "refusing unbounded"
  grep -Fq "should-not-run" "$TMP/rwt-require-out" && fail "refused call must not run the command"
  return 0
}

test_artifact_index_prune_atomic_refuses_symlink() {
  local project="$TMP/prune-symlink"
  local i

  make_committed_repo "$project"
  mkdir -p "$project/.oms/artifacts"
  for i in 1 2 3 4 5; do
    printf '{"ts":"2026-01-0%sT00:00:00Z","kind":"k","exit":0}\n' "$i" >> "$project/.oms/artifacts/real.jsonl"
  done
  ln -s real.jsonl "$project/.oms/artifacts/index.jsonl"
  cp "$project/.oms/artifacts/real.jsonl" "$TMP/prune-symlink-before.jsonl"
  if ( cd "$project" && "$ROOT/scripts/artifact-index.sh" prune 2 \
      >/dev/null 2>&1 ); then
    fail "prune must refuse a symlinked artifact-index leaf"
  fi
  assert_symlink_to "$project/.oms/artifacts/index.jsonl" "real.jsonl"
  cmp -s "$TMP/prune-symlink-before.jsonl" \
    "$project/.oms/artifacts/real.jsonl" ||
    fail "refused prune changed the symlink target"
  [ "$(wc -l < "$project/.oms/artifacts/real.jsonl" | tr -d ' ')" = "5" ] ||
    fail "refused prune changed the target row count"
}

test_oms_run_new_leaves_no_pointer_residue() {
