test_smoke_suite_does_not_mutate_source_oms() {
  local after
  after="$(source_oms_fingerprint)"
  [ "$SOURCE_OMS_FINGERPRINT" = "$after" ] && return 0
  # Naming the paths is the point. This guard used to compare two opaque
  # digests, so every time it fired it destroyed the evidence it had just
  # detected — three separate occurrences in one day, none of them diagnosable
  # after the fact, and a watcher could only catch a recurrence live.
  printf '%s\n' "$SOURCE_OMS_FINGERPRINT" > "$TMP/oms-before.txt"
  printf '%s\n' "$after" > "$TMP/oms-after.txt"
  # The fingerprints differ here, so this diff exits 1 by definition (and
  # SIGPIPEs past 20 lines); without the guard, errexit killed the suite
  # before the labelled fail below could state what happened — the guard
  # destroyed the evidence it had just printed.
  diff "$TMP/oms-before.txt" "$TMP/oms-after.txt" | grep -E '^[<>]' | head -20 >&2 || true
  fail "smoke suite mutated the source checkout .oms state (paths above)"
}

test_oms_run_validate_flags_schema_drift() {
  local project="$TMP/validate-drift"

  make_committed_repo "$project"
  mkdir -p "$project/.oms/runs"
  printf '{"schema":1,"run_id":"r","tool":"t","event":"new"}\n' > "$project/.oms/runs/spine.jsonl"
  ( cd "$project" && "$ROOT/scripts/run.sh" validate --dir "$project/.oms" >/dev/null 2>&1 ) ||
    fail "a clean schema-1 spine should validate"
  # A row below the family's expected schema is drift (nonzero + DRIFT tag).
  printf '{"schema":0,"run_id":"r2","tool":"t","event":"new"}\n' >> "$project/.oms/runs/spine.jsonl"
  local out
  out="$(cd "$project" && "$ROOT/scripts/run.sh" validate --dir "$project/.oms" 2>&1)" && \
    fail "schema drift must make validate exit nonzero"
  printf '%s' "$out" | grep -Fq "DRIFT" || fail "validate should tag the drifted family"
}

test_oms_list_joins_full_first_sentence() {
  local bin="$TMP/oms-desc-bin"
  local out

  mkdir -p "$bin"
  ln -sfn "$ROOT/scripts/oms" "$bin/oms"
  out="$("$bin/oms" list)" || fail "oms list should succeed"
  # Header comments span lines; the catalog must show the whole first
  # sentence, not the first physical comment line.
  printf '%s\n' "$out" | grep -Eq '^advise .*agent-call\.sh\.$' ||
    fail "advise description should join its full first sentence"
  # Usage-fallback descriptions get the same sentence join + cut.
  printf '%s\n' "$out" | grep -Eq '^agent-call .*read-only independent pass\.$' ||
    fail "agent-call description should end at its first sentence"
  if printf '%s\n' "$out" | grep -Eq '^agent-call .*write tasks'; then
    fail "agent-call description should not leak the second sentence"
  fi
}

test_oms_dispatcher_hints_help_on_misuse() {
