  fi

  "$ROOT/scripts/project-private.sh" --repo "$project" remove >/dev/null
  out="$("$ROOT/scripts/state.sh" --repo "$project")"
  printf '%s' "$out" | grep -Fq 'visible to git (run: oms project-private apply)' ||
