make_guard_repo() {  # make_guard_repo DIR — repo with an ignored directory
  local dir="$1"

  make_committed_repo "$dir"
  # Stubs and HOME stay outside the repo: a harness tool the worker invokes can
  # write under HOME, and inside the repo that is indistinguishable from the
  # worker planting files.
  mkdir -p "$dir-bin" "$dir-home" "$dir/venv/bin"
  printf 'venv/\n*.log\n' > "$dir/.gitignore"
  ( cd "$dir" && git add .gitignore &&
    git -c user.email=t@example.com -c user.name=t commit -qm ignore >/dev/null )
  printf 'original\n' > "$dir/venv/bin/python"
}

run_guarded_worker() {  # run_guarded_worker DIR WORKER_BODY -> prints "rc<TAB>output"
  local dir="$1"
  local body="$2"
  local rc=0
  local out
  local guard_home="$dir-home"

  printf '#!/usr/bin/env bash\ncase "${1:-}:${2:-}" in --version:|--help:|exec:--help) printf "codex 1.0\\n"; exit 0 ;; esac\n%s\necho done\n' \
    "$body" > "$dir-bin/codex"
  chmod +x "$dir-bin/codex"
  out="$(HOME="$guard_home" NVM_DIR="$guard_home/.nvm" PATH="$dir-bin:/usr/bin:/bin" \
    OMS_WORKER_GUARD_STRICT="${OMS_WORKER_GUARD_STRICT:-0}" \
    OMS_WORKER_AUTHORITY_EXCLUSIVE="${OMS_WORKER_AUTHORITY_EXCLUSIVE:-0}" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$dir" --to codex --prompt x \
    --no-verify 2>&1)" || rc=$?
  printf '%s\t%s' "$rc" "$out"
}

test_worker_guard_sees_planted_and_ignored_files() {
  local project="$TMP/guard-files"
  local result

  make_guard_repo "$project"
  # A planted untracked file is executable later from the primary tree.
  # Untracked churn cannot be attributed — the user editing their own repo looks
  # identical — so it is reported, not failed, unless the caller asks for strict.
  result="$(run_guarded_worker "$project" "printf 'evil\n' > $project/sitecustomize.py")"
  [ "${result%%	*}" = 0 ] || fail "unattributable churn must not fail an ordinary run: $result"
  printf '%s' "$result" | grep -Fq 'changed outside the worktree during this run: files' ||
    fail "the untracked surface should still be reported: $result"
  result="$(OMS_WORKER_GUARD_STRICT=1 run_guarded_worker "$project" "printf 'evil2\n' > $project/sitecustomize2.py")"
  [ "${result%%	*}" != 0 ] || fail "strict mode should fail on a planted file: $result"

  # git status collapses a fully ignored directory to one entry, so replacing a
  # file inside it is invisible there; the stat scan is what catches it.
  local swap="$TMP/guard-ignored"
  make_guard_repo "$swap"
  result="$(OMS_WORKER_GUARD_STRICT=1 run_guarded_worker "$swap" "printf 'tampered\n' > $swap/venv/bin/python")"
  [ "${result%%	*}" != 0 ] ||
    fail "replacing a file inside an ignored directory should fail a strict run"
  printf '%s' "$result" | grep -Fq 'outside its worktree: files' ||
    fail "an ignored-tree replacement should be named: $result"
}

test_worker_guard_sees_object_store_and_metadata_writes() {
  local project="$TMP/guard-gitmeta"
  local result

  make_guard_repo "$project"
  # An alternate silently widens where objects may come from.
  result="$(run_guarded_worker "$project" \
    "mkdir -p $project/.git/objects/info && printf '/tmp/elsewhere\n' > $project/.git/objects/info/alternates")"
  [ "${result%%	*}" != 0 ] || fail "adding an object alternate should fail the run"
  printf '%s' "$result" | grep -Fq 'outside its worktree: gitmeta' ||
    fail "the metadata surface should be named: $result"

  local excl="$TMP/guard-exclude"
  make_guard_repo "$excl"
  result="$(run_guarded_worker "$excl" "printf 'drop\n' >> $excl/.git/info/exclude")"
  [ "${result%%	*}" != 0 ] || fail "editing .git/info/exclude should fail the run"
  printf '%s' "$result" | grep -Fq 'gitmeta' ||
    fail "an exclude-file edit should be named: $result"
}

test_worker_guard_rejects_duplicate_live_managed_worktree_metadata() {
  local project="$TMP/guard-gitmeta-duplicate"
  local managed_root="$TMP/guard-gitmeta-managed-root"
  local sibling_parent="$managed_root/oh-my-setting-delegate.sibling"
  local sibling="$sibling_parent/wt"
  local common_dir
  local real_metadata
  local bin_dir="$project-bin"
  local home_dir="$project-home"
  local out
  local rc=0

  make_guard_repo "$project"
  mkdir -p "$sibling_parent"
  git -C "$project" worktree add --quiet --detach "$sibling" HEAD >/dev/null 2>&1 ||
    fail "could not create the live managed sibling fixture"
  {
    printf 'kind=oh-my-setting-temp\n'
    printf 'pid=%s\n' "$$"
    printf 'repo=%s\n' "$project"
    printf 'worktree=%s\n' "$sibling"
    printf 'temporary=1\n'
  } > "$sibling_parent/.oh-my-setting-tmp"
  common_dir="$(git -C "$project" rev-parse --git-common-dir)"
  case "$common_dir" in /*) ;; *) common_dir="$project/$common_dir" ;; esac
  real_metadata="$(git -C "$sibling" rev-parse --git-dir)"
  case "$real_metadata" in /*) ;; *) real_metadata="$sibling/$real_metadata" ;; esac

  cat > "$bin_dir/codex" <<EOF
#!/usr/bin/env bash
cat >/dev/null
mkdir -p "$common_dir/worktrees/rogue-duplicate"
printf '%s\\n' "$sibling/.git" > "$common_dir/worktrees/rogue-duplicate/gitdir"
cp "$real_metadata/HEAD" "$common_dir/worktrees/rogue-duplicate/HEAD"
echo "planted duplicate managed metadata"
EOF
  chmod +x "$bin_dir/codex"

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_DELEGATE_WORKTREE_ROOT="$managed_root" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --no-verify 2>&1)" || rc=$?
  [ "$rc" != 0 ] ||
    fail "duplicate metadata must not inherit a live sibling's managed exemption: $out"
  printf '%s' "$out" | grep -Fq 'outside its worktree: gitmeta' ||
    fail "duplicate managed-looking metadata should be a gitmeta violation: $out"
}

