EOF
  chmod +x "$bin_dir/codex"

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_DELEGATE_WORKTREE_ROOT="$managed_root" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --no-verify 2>&1)" || rc=$?
  [ "$rc" != 0 ] ||
    fail "symlink worktree metadata must be a hard guard violation: $out"
  printf '%s' "$out" | grep -Fq 'outside its worktree: gitmeta' ||
    fail "symlink worktree metadata should be named as gitmeta: $out"
}

make_live_managed_sibling() {  # make_live_managed_sibling PROJECT SIBLING_PARENT — registered wt + live marker
  local project="$1"
  local sibling_parent="$2"
  local sibling="$sibling_parent/wt"

  mkdir -p "$sibling_parent"
  git -C "$project" worktree add --quiet --detach "$sibling" HEAD >/dev/null 2>&1 ||
    fail "could not create the live managed sibling fixture"
  {
    printf 'kind=oh-my-setting-temp\n'
    printf 'pid=%s\n' "$$"
    printf 'repo=%s\n' "$project"
    printf 'worktree=%s\n' "$sibling"
    printf 'temporary=1\n'
  } > "$sibling_parent/.oh-my-setting-tmp"
}

run_delegate_beside_sibling() {  # run_delegate_beside_sibling PROJECT MANAGED_ROOT WORKER_BODY -> "rc<TAB>output"
  local project="$1"
  local managed_root="$2"
  local body="$3"
  local bin_dir="$project-bin"
  local home_dir="$project-home"
  local rc=0
  local out

  printf '#!/usr/bin/env bash\ncat >/dev/null\n%s\necho done\n' "$body" > "$bin_dir/codex"
  chmod +x "$bin_dir/codex"
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_DELEGATE_WORKTREE_ROOT="$managed_root" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --no-verify 2>&1)" || rc=$?
  printf '%s\t%s' "$rc" "$out"
}

test_worker_guard_exempts_a_live_sibling_mid_removal() {
  local project="$TMP/guard-sibling-removal"
  local managed_root="$TMP/guard-sibling-removal-root"
  local sibling_parent="$managed_root/oh-my-setting-delegate.sibling"
  local result

  make_guard_repo "$project"
  make_live_managed_sibling "$project" "$sibling_parent"
  # `git worktree remove` deletes the checkout before the registry entry, so a
  # final capture inside that window sees a registered worktree with no
  # checkout while the sibling's marker is still live.
  result="$(run_delegate_beside_sibling "$project" "$managed_root" "rm -rf $sibling_parent/wt")"
  [ "${result%%	*}" = 0 ] ||
    fail "a live sibling mid-removal must not fail the run: $result"
  if printf '%s' "$result" | grep -Fq 'outside the worktree'; then
    fail "a live sibling mid-removal should not be reported as a change: $result"
  fi
}

test_worker_guard_exempts_a_live_sibling_mid_creation() {
  local project="$TMP/guard-sibling-creation"
  local managed_root="$TMP/guard-sibling-creation-root"
  local sibling_parent="$managed_root/oh-my-setting-delegate.sibling"
  local result

  make_guard_repo "$project"
  make_live_managed_sibling "$project" "$sibling_parent"
  # The marker is written before `git worktree add`, which registers the entry
  # before the checkout exists: the pre-provider snapshot sees a registered
  # worktree with no checkout, the final capture sees the same entry live.
  mv "$sibling_parent/wt" "$sibling_parent/pending"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    "mv $sibling_parent/pending $sibling_parent/wt")"
  [ "${result%%	*}" = 0 ] ||
    fail "a live sibling mid-creation must not fail the run: $result"
  if printf '%s' "$result" | grep -Fq 'outside the worktree'; then
    fail "a live sibling mid-creation should not be reported as a change: $result"
  fi
}

test_worker_guard_flags_a_sibling_whose_marker_died() {
  local project="$TMP/guard-sibling-dead"
  local managed_root="$TMP/guard-sibling-dead-root"
  local sibling_parent="$managed_root/oh-my-setting-delegate.sibling"
  local result

  make_guard_repo "$project"
  make_live_managed_sibling "$project" "$sibling_parent"
  # The exemption is a liveness claim re-checked at every capture: an entry
  # that was managed at the pre-provider snapshot inherits nothing once its
  # marker is gone, so a worker cannot hide behind a sibling by killing it.
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    "rm -f $sibling_parent/.oh-my-setting-tmp")"
  [ "${result%%	*}" != 0 ] ||
    fail "a sibling whose marker died must stay a hard gitmeta violation: $result"
  printf '%s' "$result" | grep -Fq 'outside its worktree: gitmeta' ||
    fail "a dead-marker sibling should be named as gitmeta: $result"
}

test_worker_guard_reports_a_bounded_scan() {
  local project="$TMP/guard-budget"
  local out
  local guard_home="$project-home"

  make_guard_repo "$project"
  printf '#!/usr/bin/env bash\necho done\n' > "$project-bin/codex"
  chmod +x "$project-bin/codex"
  printf 'a\n' > "$project/one.txt"
  printf 'b\n' > "$project/two.txt"

  # A cap that hides how much it skipped reads as full coverage. Here the cap
  # is too small to even reach the end of the untracked files, which is the
  # serious case: coverage is genuinely partial, not merely short of the
  # ignored churn.
  out="$(HOME="$guard_home" NVM_DIR="$guard_home/.nvm" PATH="$project-bin:/usr/bin:/bin" \
    OMS_WORKER_GUARD_MAX_FILES=1 "$ROOT/scripts/peer-delegate.sh" --repo "$project" \
    --to codex --prompt x --no-verify 2>&1)" || fail "a bounded scan should not fail the run: $out"
  printf '%s' "$out" | grep -Fq 'coverage is partial' ||
    fail "a truncated scan must say so: $out"
}

test_worker_guard_rejects_any_worker_authority_state_change() {
  local project="$TMP/guard-state"
  local result

  make_guard_repo "$project"
  mkdir -p "$project/.oms/threads"
  printf '*\n' > "$project/.oms/.gitignore"
  printf '{"schema":1,"fingerprint":"abc","exit":1,"cmd":"pytest"}\n' \
    > "$project/.oms/failures.jsonl"
  printf '{"schema":1,"thread":"t1","seq":1,"role":"answer","text":"first"}\n' \
    > "$project/.oms/threads/t1.jsonl"

  # A delegated worker returns an artifact and patch; it has no authority to
  # write the primary control plane. Even a syntactically valid append can
  # forge a lifecycle/landing record that later readers treat as authority.
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$project" \
    "printf '{\"schema\":1,\"fingerprint\":\"def\",\"exit\":1}\n' >> $project/.oms/failures.jsonl")"
  [ "${result%%	*}" != 0 ] || fail "appending primary authority state should fail the run: $result"
  printf '%s' "$result" | grep -Fq 'shared-state' ||
    fail "an appended authority row should name the shared-state surface: $result"
  if grep -Fq '"fingerprint":"def"' "$project/.oms/failures.jsonl"; then
    fail "the appended authority row should be rolled back"
  fi

  # Rewritten JSON state is equally authoritative. Presence-only checks let a
  # worker widen its path scope or replace the lease that patch-land trusts.
  local plan_rewrite="$TMP/guard-state-plan-rewrite"
  make_guard_repo "$plan_rewrite"
  mkdir -p "$plan_rewrite/.oms/plan"
  printf '{"tasks":[{"id":"t1","allowed_paths":["src/"]}]}\n' \
    > "$plan_rewrite/.oms/plan/tasks.json"
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$plan_rewrite" \
    "printf '{\"tasks\":[{\"id\":\"t1\",\"allowed_paths\":[\"/\"]}]}\\n' > $plan_rewrite/.oms/plan/tasks.json")"
  [ "${result%%	*}" != 0 ] || fail "rewriting plan authority should fail the run: $result"
  printf '%s' "$result" | grep -Fq 'plan/tasks.json' ||
    fail "the rewritten authority file should be named: $result"
  if printf '%s' "$result" | grep -Fq 'shared-state: failures.jsonl'; then
    fail "parent failure bookkeeping must not be blamed on the plan-mutating worker: $result"
  fi
  grep -Fq '"allowed_paths":["src/"]' "$plan_rewrite/.oms/plan/tasks.json" ||
    fail "rewritten plan authority should be restored"

  # Rewriting rows already there is how a worker would erase the failure that
  # blocks its retry, or forge a turn another agent reads as evidence.
  local rewrite="$TMP/guard-state-rewrite"
  make_guard_repo "$rewrite"
  mkdir -p "$rewrite/.oms"
  printf '*\n' > "$rewrite/.oms/.gitignore"
  printf '{"schema":1,"fingerprint":"abc","exit":1,"cmd":"pytest"}\n' \
    > "$rewrite/.oms/failures.jsonl"
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$rewrite" \
    "printf '{\"schema\":1,\"fingerprint\":\"zzz\",\"exit\":0}\n' > $rewrite/.oms/failures.jsonl")"
  [ "${result%%	*}" != 0 ] || fail "rewriting shared state should fail the run: $result"
  printf '%s' "$result" | grep -Fq 'shared-state' ||
    fail "the shared-state surface should be named: $result"
  printf '%s' "$result" | grep -Fq 'failures.jsonl changed' ||
    fail "the violation should name the file and what happened: $result"
  grep -Fq '"fingerprint":"abc"' "$rewrite/.oms/failures.jsonl" ||
    fail "rewritten shared state should be restored"

  local removed="$TMP/guard-state-deleted"
  make_guard_repo "$removed"
  mkdir -p "$removed/.oms"
  printf '*\n' > "$removed/.oms/.gitignore"
  printf '{"schema":1,"fingerprint":"abc","exit":1}\n' > "$removed/.oms/failures.jsonl"
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$removed" \
    "rm -f $removed/.oms/failures.jsonl")"
  [ "${result%%	*}" != 0 ] || fail "deleting shared state should fail the run: $result"
  printf '%s' "$result" | grep -Fq 'was deleted' ||
    fail "a deleted state file should be named: $result"
  grep -Fq '"fingerprint":"abc"' "$removed/.oms/failures.jsonl" ||
    fail "deleted shared state should be restored"
}

test_worker_authority_guard_restores_primary_state() {
  local project="$TMP/guard-state-restore"
  local state="$project/.oms/authority"
  local result

  make_guard_repo "$project"
  mkdir -p "$state" "$project/.oms/hooks" "$project/.oms/work-journal"
  printf '*\n' > "$project/.oms/.gitignore"
  printf 'original content\n' > "$state/content.txt"
  printf 'restore this file\n' > "$state/deleted.txt"
  printf 'mode stays stable\n' > "$state/mode.txt"
  printf 'target a\n' > "$state/target-a"
  printf 'target b\n' > "$state/target-b"
  chmod 0750 "$state"
  chmod 0750 "$project/.oms"
  chmod 0600 "$state/mode.txt"
  ln -s target-a "$state/current"

  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$project" "
printf 'worker rewrite\\n' > $state/content.txt
printf 'worker creation\\n' > $state/created.txt
rm -f $state/deleted.txt
chmod 0777 $state/mode.txt
chmod 0700 $state
chmod 0777 $project/.oms
rm -f $state/current
ln -s target-b $state/current
printf 'ambient hook\\n' > $project/.oms/hooks/worker-event
printf 'ambient journal\\n' > $project/.oms/work-journal/worker-event
")"
  [ "${result%%	*}" != 0 ] ||
    fail "authority mutation should block the delegated worker: $result"
  printf '%s' "$result" | grep -Fq 'owner authority shared-state' ||
    fail "authority mutation should report the provider-window boundary: $result"
  for detail in \
    'authority changed' \
    'authority/content.txt changed' \
    'authority/created.txt was created' \
    'authority/current changed' \
    'authority/deleted.txt was deleted' \
    'authority/mode.txt changed' \
    '.oms root changed'; do
    printf '%s' "$result" | grep -Fq "$detail" ||
      fail "authority report lost the actual worker mutation ($detail): $result"
  done
  if printf '%s' "$result" | grep -Fq 'shared-state: failures.jsonl'; then
    fail "parent failure bookkeeping must not enter the provider mutation report: $result"
  fi
  printf '%s' "$result" | grep -Fq 'restored from pre-provider snapshot' ||
    fail "authority report should confirm successful rollback: $result"

  [ "$(cat "$state/content.txt")" = "original content" ] ||
    fail "rewritten authority content was not restored"
  if [ -e "$state/created.txt" ] || [ -L "$state/created.txt" ]; then
    fail "worker-created authority state was not removed"
  fi
  [ "$(cat "$state/deleted.txt")" = "restore this file" ] ||
    fail "worker-deleted authority state was not restored"
  [ "$(readlink "$state/current")" = target-a ] ||
    fail "replaced authority symlink was not restored"
  python3 - "$state" <<'PY' || fail "authority modes were not restored"
import os
import stat
import sys

root = sys.argv[1]
assert stat.S_IMODE(os.lstat(root).st_mode) == 0o750
assert stat.S_IMODE(os.lstat(os.path.join(root, "mode.txt")).st_mode) == 0o600
assert stat.S_IMODE(os.lstat(os.path.dirname(root)).st_mode) == 0o750
PY

  # These two trees are ambient telemetry, not landing/lease/scope authority.
  [ "$(cat "$project/.oms/hooks/worker-event")" = "ambient hook" ] ||
    fail "hooks exclusion should remain outside authority rollback"
  [ "$(cat "$project/.oms/work-journal/worker-event")" = "ambient journal" ] ||
    fail "work-journal exclusion should remain outside authority rollback"

  # Replacing `.oms` itself must not make the manifest walk the symlink target.
  # Because the telemetry roots disappear with the container, the disaster
  # path restores their pre-provider bytes along with authority state.
  local replaced="$TMP/guard-state-root-replaced"
  local outside="$TMP/guard-state-root-outside"
  make_guard_repo "$replaced"
  mkdir -p "$replaced/.oms/authority" "$replaced/.oms/hooks" \
    "$replaced/.oms/work-journal" "$outside"
  printf '*\n' > "$replaced/.oms/.gitignore"
  printf 'root authority\n' > "$replaced/.oms/authority/value"
  printf 'original hook\n' > "$replaced/.oms/hooks/events.jsonl"
  printf 'original journal\n' > "$replaced/.oms/work-journal/index.json"
  printf 'external target\n' > "$outside/foreign.txt"
  chmod 0750 "$replaced/.oms"

  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$replaced" "
rm -rf $replaced/.oms
ln -s $outside $replaced/.oms
printf 'outside remains outside\\n' > $outside/worker-marker
")"
  [ "${result%%	*}" != 0 ] ||
    fail "replacing the authority root should block the delegated worker: $result"
  printf '%s' "$result" | grep -Fq '.oms root changed' ||
    fail "root replacement should be named without traversing it: $result"
  if printf '%s' "$result" | grep -Fq 'foreign.txt'; then
    fail "authority scan followed the worker-planted root symlink: $result"
  fi
  if [ -L "$replaced/.oms" ] || [ ! -d "$replaced/.oms" ]; then
    fail "the authority root directory was not restored"
  fi
  [ "$(cat "$replaced/.oms/authority/value")" = "root authority" ] ||
    fail "authority bytes lost when the root was replaced"
  grep -Fq 'original hook' "$replaced/.oms/hooks/events.jsonl" ||
    fail "hook telemetry lost when the root was replaced"
  grep -Fq 'original journal' "$replaced/.oms/work-journal/index.json" ||
    fail "work-journal telemetry lost when the root was replaced"
  [ "$(cat "$outside/worker-marker")" = "outside remains outside" ] ||
    fail "rollback should not mutate the planted symlink target"
}

test_parallel_delegates_do_not_erase_each_others_authority_state() {
  local project="$TMP/guard-state-parallel"
  local barrier="$TMP/guard-state-parallel-barrier"
  local bin_dir="$project-bin"
  local home_dir="$project-home"
  local pid_a pid_b rc_a=0 rc_b=0 ticks=0
  local artifact_a artifact_b patch_a patch_b index

  make_guard_repo "$project"
  mkdir -p "$barrier"
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
set -eu
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) printf 'codex 1.0\n'; exit 0 ;; esac
prompt="$(cat)"
case "$prompt" in
  *parallel-a*) name=a ;;
  *parallel-b*) name=b ;;
  *) echo "unexpected parallel test prompt"; exit 90 ;;
esac
printf 'worker %s edit\n' "$name" >> file.txt
: > "$OMS_TEST_BARRIER/$name.ready"
while [ ! -f "$OMS_TEST_BARRIER/$name.release" ]; do sleep 0.05; done
echo "parallel worker $name done"
EOF
  chmod +x "$bin_dir/codex"

  # Start B first so its snapshots are complete before A exists. FIFO release
  # below then proves B tolerates A's live managed worktree appearing during its
  # guard window, rather than merely getting a before/after state that matches.
  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_TEST_BARRIER="$barrier" OMS_PEER_TIMEOUT=15 OMS_OPERATION_ID=parallel-b \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex \
      --prompt parallel-b --no-verify > "$barrier/b.out" 2> "$barrier/b.err" &
  pid_b=$!
  while [ ! -f "$barrier/b.ready" ] && [ "$ticks" -lt 300 ] &&
    kill -0 "$pid_b" 2>/dev/null; do
    ticks=$((ticks + 1))
    sleep 0.05
  done
  if [ ! -f "$barrier/b.ready" ]; then
    : > "$barrier/b.release"
    wait "$pid_b" 2>/dev/null || true
    fail "first parallel delegate did not reach the provider barrier: $(cat "$barrier/b.err")"
  fi

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_TEST_BARRIER="$barrier" OMS_PEER_TIMEOUT=15 OMS_OPERATION_ID=parallel-a \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex \
      --prompt parallel-a --no-verify > "$barrier/a.out" 2> "$barrier/a.err" &
  pid_a=$!
  ticks=0
  while [ ! -f "$barrier/a.ready" ] && [ "$ticks" -lt 300 ] &&
    kill -0 "$pid_a" 2>/dev/null; do
    ticks=$((ticks + 1))
    sleep 0.05
  done
  if [ ! -f "$barrier/a.ready" ]; then
    : > "$barrier/a.release"
    : > "$barrier/b.release"
    wait "$pid_a" 2>/dev/null || true
    wait "$pid_b" 2>/dev/null || true
    fail "second parallel delegate did not overlap at the provider barrier: $(cat "$barrier/a.err" "$barrier/b.err")"
  fi

  # FIFO completion is the harder case: B's outer guard began before A's
  # managed worktree existed, and ends while A is still live. That registration
  # and A's liveness state are owner-managed concurrency, not worker tampering.
  : > "$barrier/b.release"
  wait "$pid_b" || rc_b=$?
  artifact_b="$(sed -n 's/^artifact: //p' "$barrier/b.out" | sed -n '1p')"
  patch_b="$(sed -n 's/^patch: //p' "$barrier/b.out" | sed -n '1p')"
  : > "$barrier/a.release"
  wait "$pid_a" || rc_a=$?
  artifact_a="$(sed -n 's/^artifact: //p' "$barrier/a.out" | sed -n '1p')"
  patch_a="$(sed -n 's/^patch: //p' "$barrier/a.out" | sed -n '1p')"
  [ "$rc_a" = 0 ] && [ "$rc_b" = 0 ] ||
    fail "well-behaved parallel delegates should both pass (a=$rc_a b=$rc_b): $(cat "$barrier/a.err" "$barrier/b.err")"
  [ -s "$artifact_a" ] && [ -s "$artifact_b" ] && [ -s "$patch_a" ] && [ -s "$patch_b" ] ||
    fail "parallel delegates lost an artifact or patch (a=$artifact_a/$patch_a b=$artifact_b/$patch_b)"
  assert_file_contains "$artifact_a" 'parallel worker a done'
  assert_file_contains "$artifact_b" 'parallel worker b done'
  index="$project/.oms/artifacts/index.jsonl"
  assert_file_contains "$index" "$(basename "$artifact_a")"
  assert_file_contains "$index" "$(basename "$artifact_b")"
  if grep -Fq 'changed owner authority shared-state' "$barrier/a.err" "$barrier/b.err"; then
    fail "sibling owner writes must not be attributed to either worker"
  fi
}

test_worker_guard_sees_submodule_and_worktree_metadata() {
  local project="$TMP/guard-submodule"
  local source="$TMP/guard-submodule-src"
  local result

  make_committed_repo "$source"
  make_guard_repo "$project"
  # A submodule keeps its own config, refs, and hooks under .git/modules, which
  # the parent's status never shows.
  ( cd "$project" && git -c protocol.file.allow=always -c user.email=t@example.com \
    -c user.name=t submodule add -q "$source" vendor >/dev/null 2>&1 &&
    git -c user.email=t@example.com -c user.name=t commit -qm submodule >/dev/null )
  [ -d "$project/.git/modules/vendor" ] || fail "submodule fixture did not materialize"

  result="$(run_guarded_worker "$project" \
    "git -C $project/vendor config --local oms.tampered yes")"
  [ "${result%%	*}" != 0 ] || fail "submodule config tampering should fail the run: $result"
  printf '%s' "$result" | grep -Fq 'gitmeta' ||
    fail "submodule metadata should be named: $result"

  # A linked worktree is another checkout of the same repo, registered in the
  # common git dir.
  local wt="$TMP/guard-worktree"
  make_guard_repo "$wt"
  result="$(run_guarded_worker "$wt" \
    "git -C $wt worktree add --detach $wt/../guard-worktree-extra HEAD")"
  [ "${result%%	*}" != 0 ] || fail "registering a worktree should fail the run: $result"
  printf '%s' "$result" | grep -Fq 'gitmeta' ||
    fail "a new worktree registration should be named: $result"
}

test_shared_memory_context_ranked_recall() {
  local repo="$TMP/memory-recall-ctx"
  local out

  make_committed_repo "$repo"
  ( cd "$repo" &&
    bash "$ROOT/scripts/agent-memory.sh" append --agent claude \
      --text "Always run the focused parser test before landing parser changes." >/dev/null &&
    bash "$ROOT/scripts/agent-memory.sh" append --agent claude \
      --text "The deploy pipeline needs the staging flag." >/dev/null )

  # Naming the operation adds a query-ranked recall section to the injected
  # memory context; without a query the recency tails stand alone.
  out="$(cd "$repo" && bash -c '. "$1"; ma_write_shared_memory_context "$2" "refactor the parser module tests"' \
    _ "$ROOT/scripts/lib/agent-memory-common.sh" "$repo")"
  printf '%s' "$out" | grep -Fq '### relevant recall' ||
    fail "query should add a ranked recall section: $out"
  printf '%s' "$out" | grep -Fq 'focused parser test' ||
    fail "recall should surface the matching lesson"
  out="$(cd "$repo" && bash -c '. "$1"; ma_write_shared_memory_context "$2"' \
    _ "$ROOT/scripts/lib/agent-memory-common.sh" "$repo")"
  if printf '%s' "$out" | grep -Fq 'relevant recall'; then
    fail "no query must mean no recall section"
  fi
}

test_memory_recall_tracks_access_for_decay() {
  local repo="$TMP/memory-access-decay"
  local db

  make_committed_repo "$repo"
  ( cd "$repo" &&
    bash "$ROOT/scripts/agent-memory.sh" append --agent claude \
      --text "Parser fixes need the focused test first." >/dev/null &&
    bash "$ROOT/scripts/agent-memory.sh" append --agent claude \
      --text "Deploy needs the staging flag." >/dev/null )
  ( cd "$repo" && bash "$ROOT/scripts/agent-memory.sh" recall \
      --text "parser focused test" --limit 2 >/dev/null )
  db="$(find "$repo/.oms/memory" -name '*.sqlite3' | head -n 1)"
  [ -n "$db" ] || fail "memory database missing after recall"
  # Recall is what marks a memory as alive: the returned entry gains an
  # access row, and a second recall increments it. Stats live outside
  # memory_entries so a markdown re-derive cannot erase them.
  python3 - "$db" <<'PY' || fail "first recall should record one access"
import sqlite3, sys
rows = list(sqlite3.connect(sys.argv[1]).execute(
    "select hit_count from memory_access"))
assert rows == [(1,)], rows
PY
  ( cd "$repo" && bash "$ROOT/scripts/agent-memory.sh" recall \
      --text "parser focused test" --limit 2 >/dev/null )
  python3 - "$db" <<'PY' || fail "second recall should increment the hit count"
import sqlite3, sys
rows = list(sqlite3.connect(sys.argv[1]).execute(
    "select hit_count from memory_access"))
assert rows == [(2,)], rows
PY
}

test_shared_memory_writes_are_append_only() {
  local project="$TMP/memory-contract"
  local home_dir="$project/agenthome"
  local memory="$project/.oms/memory/shared.md"
  local before

  make_committed_repo "$project"
  mkdir -p "$home_dir"
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --agent codex --text "first note" >/dev/null
  before="$(cat "$memory")"

  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --agent claude --text "second note" >/dev/null
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" pin \
    --agent codex --text "pinned note" >/dev/null
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" compact >/dev/null

  # The guard verifies that existing bytes never change, so the writers have to
  # keep that true: a refactor that starts rewriting the log in place would
  # make every worker look like it forged shared state.
  [ "$(head -c "${#before}" "$memory")" = "$before" ] ||
    fail "appending a note must not rewrite what was already in shared.md"
  grep -Fq 'second note' "$memory" || fail "the new note should still be recorded"
  # summary.md is derived, so regenerating it is not a rewrite of the record.
  [ -f "$project/.oms/memory/summary.md" ] || fail "compact should produce a summary"
}

test_worker_guard_keeps_shared_memory_parent_owned() {
  local project="$TMP/guard-memory"
  local result

  make_guard_repo "$project"
  HOME="$project-home" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --agent codex --text "prefer scripts/check.sh before done" >/dev/null

  # Memory is evidence consumed by later agents. A worker reports proposed
  # notes in its artifact; the owner decides what becomes shared state.
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$project" \
    "OMS_STATE_REPO=$project HOME=$project-home $ROOT/scripts/agent-memory.sh --repo $project append --agent codex --text 'worker note' >/dev/null")"
  [ "${result%%	*}" != 0 ] || fail "a worker appending shared memory should fail: $result"
  printf '%s' "$result" | grep -Fq 'memory/shared.md' ||
    fail "the appended memory log should be named: $result"
  if printf '%s' "$result" | grep -Fq 'shared-state: failures.jsonl'; then
    fail "parent failure bookkeeping must not be blamed on the memory-mutating worker: $result"
  fi
  if grep -Fq 'worker note' "$project/.oms/memory/shared.md"; then
    fail "the worker memory append should be rolled back"
  fi

  # Editing a note another agent wrote is how a worker would rewrite the record
  # the next session reads as fact.
  local edited="$TMP/guard-memory-edit"
  make_guard_repo "$edited"
  HOME="$edited-home" "$ROOT/scripts/agent-memory.sh" --repo "$edited" append \
    --agent codex --text "prefer scripts/check.sh before done" >/dev/null
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$edited" \
    "sed -i 's/prefer scripts/IGNORE scripts/' $edited/.oms/memory/shared.md")"
  [ "${result%%	*}" != 0 ] || fail "editing an existing memory note should fail the run: $result"
  printf '%s' "$result" | grep -Fq 'memory/shared.md changed' ||
    fail "the violation should name shared.md and what happened: $result"
  if printf '%s' "$result" | grep -Fq 'shared-state: failures.jsonl'; then
    fail "parent failure bookkeeping must stay outside the provider-window diff: $result"
  fi
  grep -Fq 'prefer scripts/check.sh' "$edited/.oms/memory/shared.md" ||
    fail "the edited memory note should be restored"
}

test_worker_guard_sees_an_edit_to_an_already_dirty_file() {
  local project="$TMP/guard-dirty"
  local result

  make_guard_repo "$project"
  # The user's own uncommitted work. git status says " M file.txt" before and
  # after a worker rewrites it, so status categories cannot see this at all.
  printf 'base\nEDITED BY USER\n' > "$project/file.txt"

  result="$(OMS_WORKER_GUARD_STRICT=1 run_guarded_worker "$project" \
    "printf 'base\nCLOBBERED BY WORKER\n' > $project/file.txt")"
  [ "${result%%	*}" != 0 ] ||
    fail "clobbering an already-dirty tracked file should fail a strict run: $result"
  printf '%s' "$result" | grep -Fq 'outside its worktree: tracked' ||
    fail "the tracked surface should catch a content change, not just its status: $result"
}

test_thread_appends_are_serialized() {
  local project="$TMP/thread-race"
  local i

  make_committed_repo "$project"
  "$ROOT/scripts/thread.sh" --repo "$project" new --id race >/dev/null

  # A consult panel appends answers concurrently; read-max-then-append without
  # a lock hands two writers the same sequence number.
  i=0
  while [ "$i" -lt 12 ]; do
    "$ROOT/scripts/thread.sh" --repo "$project" --id race append \
      --role note --text "turn $i" >/dev/null 2>&1 &
    i=$((i + 1))
  done
  wait

  python3 - "$project/.oms/threads/race.jsonl" <<'PY' || fail "concurrent appends must keep sequence numbers unique and contiguous"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1]) if line.strip()]
seqs = [r["seq"] for r in rows]
assert len(rows) == 12, len(rows)
assert sorted(seqs) == list(range(1, 13)), seqs
PY
}

test_thread_pointer_does_not_cross_tasks() {
  local project="$TMP/thread-owner"
  local first

  make_committed_repo "$project"
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" init --goal "first task" >/dev/null )
  first="$("$ROOT/scripts/thread.sh" --repo "$project" new --topic "first" )"
  [ "$("$ROOT/scripts/thread.sh" --repo "$project" current)" = "$first" ] ||
    fail "the thread should be current for the task that opened it"

  # A different task must not inherit the previous task's conversation.
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" close --reason "moving on" >/dev/null )
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" init --goal "second task" >/dev/null )
  if "$ROOT/scripts/thread.sh" --repo "$project" current >/dev/null 2>&1; then
    fail "a new task must not inherit the previous task's thread"
  fi
}

test_landing_refuses_to_apply_without_a_recorded_intent() {
  local project="$TMP/landing-failclosed"
  local patch="$TMP/landing-failclosed.patch"
  local rc=0
  local out

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )
  mkdir -p "$project/.oms"
  printf '*\n' > "$project/.oms/.gitignore"
  : > "$project/.oms/landings.jsonl"
  chmod 444 "$project/.oms/landings.jsonl"

  out="$("$ROOT/scripts/patch-land.sh" --patch "$patch" --repo "$project" 2>&1)" || rc=$?
  chmod 644 "$project/.oms/landings.jsonl"
  [ "$rc" != 0 ] || fail "an unrecordable intent must not apply: $out"
  printf '%s' "$out" | grep -Fq 'refusing to apply' ||
    fail "the refusal should say why: $out"
  [ -z "$(git -C "$project" status --porcelain -- file.txt)" ] ||
    fail "nothing should have been applied"
}

test_provider_permissions_grants_only_what_is_missing() {
  local dir="$TMP/provider-perms"
  local settings="$dir/settings.json"
  local bin="$dir/bin"
  local rc=0
  local out

  mkdir -p "$dir" "$bin"
  printf '#!/bin/sh\nexit 0\n' > "$bin/agy"
  chmod +x "$bin/agy"

  out="$(PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" \
    --apply --profile delegate --allow-command uv \
    --worktree-parent /tmp --settings "$settings" 2>&1)" ||
    fail "apply should succeed on a fresh settings file: $out"
  python3 - "$settings" <<'PY' || fail "apply must write exactly the profile's rules"
import json, sys
allow = json.load(open(sys.argv[1]))["permissions"]["allow"]
assert allow == ["read_file(*)", "command(*)",
                 "write_file(/tmp)", "unsandboxed(uv)"], allow
PY

  # Re-running must be a no-op, not a second copy of every rule.
  PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" --check --profile delegate \
    --allow-command uv --worktree-parent /tmp --settings "$settings" >/dev/null ||
    fail "a satisfied config should check clean"

  # A directory grant covers paths under it, so a narrower requirement is met.
  PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" --check --profile delegate \
    --worktree-parent /tmp/nested/deeper --settings "$settings" >/dev/null ||
    fail "write_file(/tmp) should already cover a directory beneath it"

  # An unrelated command is still missing, and the hint must carry the flag
  # that produced the finding.
  out="$(PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" --check --profile delegate \
    --allow-command npm --worktree-parent /tmp --settings "$settings" 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "a missing unsandboxed grant should not check clean: $out"
  printf '%s' "$out" | grep -Fq -- '--allow-command npm' ||
    fail "following the hint must grant what was reported: $out"

  # The sandbox boundary is not something to hand over with one flag.
  rc=0
  out="$(PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" --check --profile delegate \
    --allow-command '*' --settings "$settings" 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "a wildcard sandbox escape should be refused: $out"
}

test_peer_delegate_uses_managed_private_worktree_root() {
  local project="$TMP/delegate-private-root"
  local home_dir="$TMP/delegate-private-home"
  local cache_dir="$TMP/delegate-private-cache"
  local managed_root="$cache_dir/oh-my-setting/worktrees"
  local out worktree worktree_parent

  make_committed_repo "$project"
  mkdir -p "$home_dir" "$cache_dir"
  out="$(HOME="$home_dir" XDG_CACHE_HOME="$cache_dir" \
    OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
      --repo "$project" --to codex --prompt 'private root regression' \
      --no-verify --keep-worktree 2>&1)" ||
    fail "delegate dry-run should create an inspectable worktree: $out"
  worktree="$(printf '%s\n' "$out" | sed -n 's/^worktree kept: //p' | tail -n 1)"
  [ -n "$worktree" ] || fail "delegate did not report its kept worktree: $out"
  case "$worktree" in
    "$managed_root"/*/wt) ;;
    *) fail "delegate worktree escaped the managed root: $worktree" ;;
  esac
  [ -d "$managed_root" ] && [ ! -L "$managed_root" ] ||
    fail "managed delegate root must be a real directory"
  python3 - "$managed_root" <<'PY' || fail "managed delegate root must be mode 0700"
import os, stat, sys
assert stat.S_IMODE(os.stat(sys.argv[1]).st_mode) == 0o700
PY

  worktree_parent="$(dirname "$worktree")"
  git -C "$project" worktree remove --force "$worktree" >/dev/null 2>&1 ||
    fail "could not clean the kept delegate worktree"
  rm -rf "$worktree_parent"
}

test_provider_permissions_apply_preserves_a_concurrent_settings_edit() {
  local dir="$TMP/provider-perms-apply-cas"
  local settings="$dir/settings.json"
  local managed="$settings.oh-my-setting-permissions.json"
  local bin="$dir/bin"
  local pythonpath="$dir/pythonpath"
  local ready="$dir/backup-copy-ready"
  local continue="$dir/backup-copy-continue"
  local out="$dir/apply.out"
  local pid rc=0 attempts=0

  mkdir -p "$bin" "$pythonpath"
  printf '#!/bin/sh\nexit 0\n' > "$bin/agy"
  chmod +x "$bin/agy"
  cat > "$settings" <<'EOF'
{
  "theme": "user-before",
  "permissions": {
    "allow": ["read_file(*)", "user(existing)"]
  }
}
EOF

  # Pause the standard-library backup copy after apply has read its snapshot.
  # This is process-local dependency injection: production code gets no test
  # hook, while the fixture can deterministically land a concurrent edit in
  # the old read -> write gap.
  cat > "$pythonpath/shutil.py" <<'PY'
import os
import time


def rmtree(path, ignore_errors=False, onerror=None):
    # tempfile only captures this symbol while provider-permissions uses
    # mkstemp; no temporary-directory cleanup runs in this fixture.
    raise AssertionError("unexpected shutil.rmtree call: %s" % path)


def copyfileobj(source, target, length=1024 * 1024):
    ready = os.environ["OMS_TEST_PP_COPY_READY"]
    proceed = os.environ["OMS_TEST_PP_COPY_CONTINUE"]
    with open(ready, "w", encoding="utf-8") as handle:
        handle.write("ready\n")
    deadline = time.time() + 10
    while not os.path.exists(proceed):
        if time.time() >= deadline:
            raise RuntimeError("timed out waiting for concurrent edit")
        time.sleep(0.01)
    while True:
        chunk = source.read(length)
        if not chunk:
            return
        target.write(chunk)
PY

  env PYTHONPATH="$pythonpath" OMS_TEST_PP_COPY_READY="$ready" \
    OMS_TEST_PP_COPY_CONTINUE="$continue" PATH="$bin:$PATH" \
    "$ROOT/scripts/provider-permissions.sh" --apply --profile consult \
    --settings "$settings" >"$out" 2>&1 &
  pid=$!
  while [ ! -e "$ready" ] && kill -0 "$pid" 2>/dev/null; do
    attempts=$((attempts + 1))
    [ "$attempts" -lt 500 ] || break
    sleep 0.01
  done
  if [ ! -e "$ready" ]; then
    : > "$continue"
    wait "$pid" || true
    fail "permission apply did not reach the concurrent-edit boundary: $(cat "$out")"
  fi

  PYTHONPATH='' python3 - "$settings" <<'PY'
import json
import os
import sys
import tempfile

path = sys.argv[1]
with open(path, encoding="utf-8") as handle:
    cfg = json.load(handle)
cfg["theme"] = "user-during-apply"
cfg["permissions"]["allow"].append("user(during-apply)")
fd, temporary = tempfile.mkstemp(prefix=".concurrent-settings.",
                                 dir=os.path.dirname(path))
try:
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        json.dump(cfg, handle, indent=2)
        handle.write("\n")
    os.replace(temporary, path)
finally:
    try:
        os.unlink(temporary)
    except FileNotFoundError:
        pass
PY
  : > "$continue"
  wait "$pid" || rc=$?

  [ "$rc" -ne 0 ] || fail "permission apply overwrote a concurrent settings edit"
  grep -Fq 'settings changed during permission apply' "$out" ||
    fail "concurrent permission refusal was not explained: $(cat "$out")"
  python3 - "$settings" <<'PY' || fail "concurrent permission edit was not preserved"
import json
import sys

cfg = json.load(open(sys.argv[1], encoding="utf-8"))
assert cfg["theme"] == "user-during-apply", cfg
assert cfg["permissions"]["allow"] == [
    "read_file(*)", "user(existing)", "user(during-apply)"
], cfg
PY
  [ ! -e "$managed" ] ||
    fail "failed permission apply claimed ownership it did not grant"
}

test_provider_permissions_tracks_and_revokes_only_managed_rules() {
  local dir="$TMP/provider-perms-managed"
  local settings="$dir/settings.json"
  local managed="$settings.oh-my-setting-permissions.json"
  local bin="$dir/bin"
  local before after out rc=0 victim victim_before

  mkdir -p "$bin"
  printf '#!/bin/sh\nexit 0\n' > "$bin/agy"
  chmod +x "$bin/agy"
  cat > "$settings" <<'EOF'
{
  "theme": "user-before",
  "permissions": {
    "allow": ["read_file(*)", "user(existing)"]
  }
}
EOF

  for help_command in \
      "$ROOT/install.sh --help" \
      "$ROOT/scripts/provider-permissions.sh --help"; do
    out="$(bash -c "$help_command")" || fail "permission help failed: $help_command"
    for rule in 'read_file(*)' 'command(*)'; do
      printf '%s' "$out" | grep -Fq "$rule" ||
        fail "permission consent omitted $rule: $help_command"
    done
    if printf '%s' "$out" | grep -Fq 'mcp(*)'; then
      fail "permission consent must not advertise an all-MCP grant: $help_command"
    fi
  done

  PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" \
    --apply --profile consult --settings "$settings" >/dev/null ||
    fail "managed consult permission apply failed"
  python3 - "$settings" "$managed" <<'PY' || fail "permission ownership was recorded incorrectly"
import json, sys
settings, managed = sys.argv[1:]
cfg = json.load(open(settings, encoding="utf-8"))
assert cfg["theme"] == "user-before", cfg
assert cfg["permissions"]["allow"] == [
    "read_file(*)", "user(existing)", "command(*)"
], cfg
state = json.load(open(managed, encoding="utf-8"))
assert state == {"schema": 1, "rules": ["command(*)"]}, state
backup = json.load(open(settings + ".bak", encoding="utf-8"))
assert backup["permissions"]["allow"] == ["read_file(*)", "user(existing)"], backup
PY

  # Changes after installation are user-owned. A duplicate of one managed rule
  # represents a later user grant; removal may consume only the occurrence the
  # sidecar owns, not every equal string in the list.
  python3 - "$settings" <<'PY'
import json, sys
path = sys.argv[1]
cfg = json.load(open(path, encoding="utf-8"))
cfg["theme"] = "user-after"
cfg["permissions"]["allow"].extend(["user(after)", "command(*)"])
with open(path, "w", encoding="utf-8") as handle:
    json.dump(cfg, handle, indent=2)
    handle.write("\n")
PY

  PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" \
    --apply --profile consult --settings "$settings" >/dev/null ||
    fail "repeated permission apply should be idempotent"
  python3 - "$settings.bak" <<'PY' || fail "repeat apply overwrote the original backup"
import json, sys
cfg = json.load(open(sys.argv[1], encoding="utf-8"))
assert cfg["theme"] == "user-before", cfg
assert "user(after)" not in cfg["permissions"]["allow"], cfg
PY

  # Removal is local JSON surgery and must work even when agy is no longer on
  # PATH. It removes only sidecar-owned occurrences and then deletes the sidecar.
  PATH="/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" \
    --remove --settings "$settings" >/dev/null ||
    fail "managed permission removal failed without agy"
  [ ! -e "$managed" ] || fail "managed permission sidecar survived removal"
  python3 - "$settings" <<'PY' || fail "permission removal overwrote user rules"
import json, sys
cfg = json.load(open(sys.argv[1], encoding="utf-8"))
assert cfg["theme"] == "user-after", cfg
assert cfg["permissions"]["allow"] == [
    "read_file(*)", "user(existing)", "user(after)", "command(*)"
], cfg
PY

  before="$(cksum < "$settings")"
  PATH="/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" \
    --remove --settings "$settings" >/dev/null ||
    fail "repeated permission removal should be idempotent"
  after="$(cksum < "$settings")"
  [ "$before" = "$after" ] || fail "idempotent removal rewrote user settings"

  printf '{not-json\n' > "$managed"
  before="$(cksum < "$settings")"
  rc=0
  out="$(PATH="/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" \
    --remove --settings "$settings" 2>&1)" || rc=$?
  [ "$rc" -ne 0 ] || fail "invalid permission ownership state was ignored"
  after="$(cksum < "$settings")"
  [ "$before" = "$after" ] || fail "failed permission removal mutated settings"
  printf '%s' "$out" | grep -Fq 'managed permission state' ||
    fail "invalid permission ownership failure was not explained: $out"
  rm -f "$managed"

  # Ownership metadata is privileged input: following a planted sidecar
  # symlink could otherwise turn uninstall into an arbitrary-file rewriter.
  victim="$dir/user-owned.json"
  printf '%s\n' '{"schema":1,"rules":["command(*)"]}' > "$victim"
  if ln -s "$victim" "$managed" 2>/dev/null; then
    before="$(cksum < "$settings")"
    victim_before="$(cksum < "$victim")"
    rc=0
    out="$(PATH="/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" \
      --remove --settings "$settings" 2>&1)" || rc=$?
    [ "$rc" -ne 0 ] || fail "a symbolic-link ownership sidecar was trusted"
    [ "$before" = "$(cksum < "$settings")" ] ||
      fail "symbolic-link ownership failure mutated settings"
    [ "$victim_before" = "$(cksum < "$victim")" ] ||
      fail "symbolic-link ownership failure mutated its target"
    printf '%s' "$out" | grep -Fq 'symbolic link' ||
      fail "symbolic-link ownership refusal was not explained: $out"
    rm -f "$managed" "$victim"
  fi

  python3 - "$managed" <<'PY'
import json
import sys

with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump({
        "schema": 1,
        "rules": ["command(*)"],
        "removal": {
            "before_sha256": "0" * 64,
            "after_sha256": "1" * 64,
        },
    }, handle)
PY
  before="$(cksum < "$settings")"
  rc=0
  out="$(PATH="/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" \
    --remove --settings "$settings" 2>&1)" || rc=$?
  [ "$rc" -ne 0 ] || fail "a stale permission-removal journal was replayed"
  [ "$before" = "$(cksum < "$settings")" ] ||
    fail "stale permission-removal journal overwrote concurrent user edits"
  [ -f "$managed" ] || fail "failed permission-removal retry lost ownership state"
  printf '%s' "$out" | grep -Fq 'settings changed' ||
    fail "stale permission-removal journal failure was not explained: $out"
  rm -f "$managed"
}

test_provider_permissions_toolchains_follow_the_machine() {
  local dir="$TMP/provider-perms-toolchains"
  local settings="$dir/settings.json"
  local bin="$dir/bin"
  local out

  # Only tools this machine actually has: an escape granted to something that
  # is not installed buys nothing and outlives the reason it was added.
  mkdir -p "$dir" "$bin"
  printf '#!/bin/sh\nexit 0\n' > "$bin/agy"
  printf '#!/bin/sh\nexit 0\n' > "$bin/npm"
  chmod +x "$bin/agy" "$bin/npm"

  out="$(PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" --print \
    --profile delegate --allow-toolchains --worktree-parent /tmp --settings "$settings" 2>&1)" ||
    fail "print should succeed: $out"
  printf '%s\n' "$out" | grep -Fxq 'unsandboxed(npm)' ||
    fail "an installed package manager should be granted: $out"
  if printf '%s\n' "$out" | grep -Fxq 'unsandboxed(cargo)'; then
    fail "cargo is not on this PATH and must not be granted: $out"
  fi
  # Tools that write in-tree, contradict the uv policy, or hold root-equivalent
  # access are out of the list regardless of being installed.
  for excluded in pip conda docker make node git; do
    if printf '%s\n' "$out" | grep -Fxq "unsandboxed($excluded)"; then
      fail "$excluded must not be granted by --allow-toolchains: $out"
    fi
  done
}

test_provider_permissions_leaves_flag_driven_providers_alone() {
  local dir="$TMP/provider-perms-none"
  local bin="$dir/bin"
  local out

  # No agy on PATH: codex and claude carry authority per invocation, so there
  # is nothing standing to grant and the check must not invent work.
  mkdir -p "$dir" "$bin"
  out="$(PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" --check 2>&1)" ||
    fail "no antigravity means nothing to do: $out"
  printf '%s' "$out" | grep -Fq 'not installed' || fail "should say why there is nothing to do: $out"
}

test_worker_guard_spends_its_budget_on_untracked_before_ignored() {
  local project="$TMP/guard-budget-order"
  local snap="$TMP/guard-budget-order-snap"
  local i
  local changed
  local files_line

  make_committed_repo "$project"
  printf 'junk/\n' > "$project/.gitignore"
  git -C "$project" add .gitignore
  git -C "$project" -c user.email=t@t -c user.name=t commit -qm "ignore junk"
  # A real ML repo: an ignored tree with far more files than the budget, and a
  # couple of genuinely new source files whose paths sort after it.
  mkdir -p "$project/junk"
  i=0
  while [ "$i" -lt 30 ]; do
    printf 'x\n' > "$project/junk/blob$i.bin"
    i=$((i + 1))
  done
  printf 'new\n' > "$project/zz_new_source.py"

  rm -rf "$snap"
  ( . "$ROOT/scripts/lib/oms-common.sh"
    OMS_WORKER_GUARD_MAX_FILES=5 oms_worker_surface_snapshot "$project" "$snap" ) ||
    fail "snapshot failed"
  files_line="$(grep '^TRUNCATED' "$snap/files" || true)"
  case "$files_line" in
    *"(ignored)"*) ;;
    *) fail "truncation should land in the ignored class, got: ${files_line:-<none>}" ;;
  esac

  # The point of the ordering: a stray write to an untracked source file is
  # still caught, even though the scan stopped early.
  printf 'new\nWORKER WROTE HERE\n' > "$project/zz_new_source.py"
  changed="$( . "$ROOT/scripts/lib/oms-common.sh"
    OMS_WORKER_GUARD_MAX_FILES=5 oms_worker_surface_diff "$project" "$snap" )"
  case "$changed" in
    *files*) ;;
    *) fail "a change to an untracked source file must survive truncation, got: ${changed:-<none>}" ;;
  esac
}

test_delegate_says_the_worker_cannot_see_uncommitted_work() {
  local project="$TMP/delegate-dirty-base"
  local bin="$project/bin"
  local home_dir="$project/home"
  local out
  local artifact

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir"
  printf '#!/usr/bin/env bash\ncat > /dev/null\necho "did the work"\n' > "$bin/codex"
  chmod +x "$bin/codex"
  # The caller is mid-edit. The worktree is built from HEAD, so a brief written
  # about what is on screen describes code the worker will never find.
  printf 'base\nUNCOMMITTED WORK\n' > "$project/file.txt"

  out="$(HOME="$home_dir" PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --prompt "change the thing" --no-verify 2>&1)" ||
    fail "a dirty caller tree is a note, not a failure: $out"
  printf '%s' "$out" | grep -Fq 'differ from HEAD' ||
    fail "delegating from a dirty tree should say the worker sees HEAD: $out"

  artifact="$(printf '%s' "$out" | sed -n 's/^artifact: //p' | head -n 1)"
  [ -f "$artifact" ] || fail "no artifact recorded: $out"
  grep -Fq 'NOT visible to the worker' "$artifact" ||
    fail "the patch reviewer needs to know which base it was written against"
}

test_memory_recall_spans_notes_and_recorded_failures() {
  local project="$TMP/memory-failures"
  local gate='bash -c "grep -q fixed state.txt || { echo ERROR: state.txt not fixed; exit 1; }; echo ok"'
  local out

  make_committed_repo "$project"
  printf 'broken\n' > "$project/state.txt"
  "$ROOT/scripts/agent-task.sh" --repo "$project" init --goal "fix state" --verify "$gate" >/dev/null
  "$ROOT/scripts/agent-task.sh" --repo "$project" verify >/dev/null 2>&1 || true
  OMS_AGENT=codex "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --text "the gate reads state.txt directly" >/dev/null

  # Exact-fingerprint `check --cmd` answers "this same command failed". One
  # recall has to answer the softer question across everything recorded: notes,
  # pins, and what already went wrong.
  out="$("$ROOT/scripts/agent-memory.sh" --repo "$project" recall "state.txt")"
  printf '%s' "$out" | grep -Fq 'ERROR: state.txt not fixed' ||
    fail "recall should reach the failure ledger: $out"
  printf '%s' "$out" | grep -Fq 'the gate reads state.txt directly' ||
    fail "recall should still reach the notes: $out"
}

test_memory_recall_marks_a_resolved_failure() {
  local project="$TMP/memory-failures-resolved"
  local gate='bash -c "grep -q fixed state.txt || { echo ERROR: state.txt not fixed; exit 1; }; echo ok"'
  local out

  make_committed_repo "$project"
  printf 'broken\n' > "$project/state.txt"
  "$ROOT/scripts/agent-task.sh" --repo "$project" init --goal "fix state" --verify "$gate" >/dev/null
  "$ROOT/scripts/agent-task.sh" --repo "$project" verify >/dev/null 2>&1 || true
  # The gate now passes, so the ledger row is resolved. A resolution is its own
  # append-only row carrying nothing but the fingerprint it clears: recalling
  # the failure without it presents a solved problem as an open one, which is
  # worse than not recalling it at all.
  printf 'fixed\n' > "$project/state.txt"
  "$ROOT/scripts/agent-task.sh" --repo "$project" verify >/dev/null 2>&1 ||
    fail "the gate should pass once state.txt is fixed"

  out="$("$ROOT/scripts/agent-memory.sh" --repo "$project" recall "state.txt")"
  printf '%s' "$out" | grep -Fq 'resolved' ||
    fail "recall must mark a resolved failure as resolved: $out"
  "$ROOT/scripts/agent-memory.sh" --repo "$project" recall "state.txt" --json |
    grep -Fq '"kind": "failure-resolved"' ||
    fail "a resolved failure should carry failure-resolved provenance"

  # A later failure on the same fingerprint re-opens it: the last event wins.
  printf 'broken\n' > "$project/state.txt"
  "$ROOT/scripts/agent-task.sh" --repo "$project" verify >/dev/null 2>&1 || true
  out="$("$ROOT/scripts/agent-memory.sh" --repo "$project" recall "state.txt" --json)"
  printf '%s' "$out" | grep -Fq '"kind": "failure"' ||
    fail "a failure recorded after a resolution must recall as open: $out"
}

test_memory_index_upgrades_a_schema_two_database() {
  local project="$TMP/memory-v2"
  local db="$project/.oms/memory/memory.sqlite3"
  local out

  # A database built before failures were indexed carries a CHECK constraint
  # that cannot be altered in place. Everything in it is derived, so the upgrade
  # re-derives rather than migrating rows.
  mkdir -p "$project/.oms/memory"
  printf '# Shared Agent Memory\n\n## 2026-07-01T00:00:00Z codex\n\nolder note kept\n' \
    > "$project/.oms/memory/shared.md"
  printf '# Pins\n\n- 2026-07-01T00:00:00Z [claude] pinned rule\n' \
    > "$project/.oms/memory/pins.md"
  python3 - "$db" "$project/.oms/memory/shared.md" "$project/.oms/memory/pins.md" <<'PY'
import sqlite3, sys
db = sqlite3.connect(sys.argv[1])
db.executescript(
    """
    create table memory_sources (
      source text primary key check (source in ('shared', 'pins')),
      path text not null, size integer not null,
      mtime_ns integer not null, digest text not null
    );
    create table memory_entries (
      id integer primary key, event_id text not null unique,
      source text not null check (source in ('shared', 'pins')),
      ordinal integer not null, occurred_at text not null, agent text not null,
      kind text not null, task_id text not null, session_hash text not null,
      git_sha text not null, git_dirty integer, git_state text not null,
      body text not null, rendered text not null
    );
    pragma user_version = 2;
    """
)
db.commit()
PY
  printf '{"schema":1,"ts":"2026-07-02T00:00:00Z","agent":"codex","kind":"verify","cmd":"uv run pytest","exit":1,"summary":"ERROR: fixture missing","fingerprint":"abc123"}\n' \
    > "$project/.oms/failures.jsonl"

  out="$("$ROOT/scripts/agent-memory.sh" --repo "$project" search "fixture missing")" ||
    fail "an older database must upgrade rather than error: $out"
  printf '%s' "$out" | grep -Fq 'ERROR: fixture missing' ||
    fail "the upgraded index should carry failures: $out"
  out="$("$ROOT/scripts/agent-memory.sh" --repo "$project" search "older note kept")"
  printf '%s' "$out" | grep -Fq 'older note kept' ||
    fail "re-deriving must not lose what is still in the Markdown: $out"
}

test_task_verify_surfaces_the_advisor_on_a_repeat() {
  local project="$TMP/verify-advise"
  local gate='bash -c "grep -q fixed state.txt || { echo ERROR: not fixed; exit 1; }"'
  local out

  # Recording is deliberately quiet here, which is what made this path dead on
  # arrival: the ledger's escalation line was written to a stderr the caller
  # threw away, so the one message this recording exists to produce never
  # reached the agent that had just failed the same gate twice.
  make_committed_repo "$project"
  printf 'broken\n' > "$project/state.txt"
  "$ROOT/scripts/agent-task.sh" --repo "$project" init --goal "fix state" \
    --verify "$gate" >/dev/null

  out="$("$ROOT/scripts/agent-task.sh" --repo "$project" verify 2>&1)" || true
  if printf '%s' "$out" | grep -Fq 'oms advise'; then
    fail "one failed gate is not a pattern: $out"
  fi

  out="$("$ROOT/scripts/agent-task.sh" --repo "$project" verify 2>&1)" || true
  printf '%s' "$out" | grep -Fq 'oms advise' ||
    fail "a gate that failed twice should reach the agent with an advisor: $out"
  # The bookkeeping stays quiet; only the escalation is let through.
  if printf '%s' "$out" | grep -Fq 'fail-ledger: recorded'; then
    fail "the recording line should stay silenced: $out"
  fi

  printf 'fixed\n' > "$project/state.txt"
  "$ROOT/scripts/agent-task.sh" --repo "$project" verify >/dev/null 2>&1 ||
    fail "the gate should pass once state.txt is fixed"
  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" list)" ||
    fail "list should succeed"
  printf '%s' "$out" | grep -Fq 'resolved' ||
    fail "a passing gate should resolve its row: $out"
}

test_task_close_promotes_the_decision_and_the_pitfall() {
  local project="$TMP/close-promote"
  local out

  make_committed_repo "$project"
  "$ROOT/scripts/agent-task.sh" --repo "$project" init --goal "wire it" --verify true >/dev/null
  "$ROOT/scripts/agent-task.sh" --repo "$project" update \
    --decision "the gate reads the file, so fixtures write it first" >/dev/null
  "$ROOT/scripts/agent-task.sh" --repo "$project" update \
    --last-failure "PATH stub shadowed by ~/.local/bin unless HOME is a fixture" >/dev/null
  "$ROOT/scripts/agent-task.sh" --repo "$project" verify >/dev/null
  "$ROOT/scripts/agent-task.sh" --repo "$project" close >/dev/null

  # Both lines were already written during the work. Closing used to keep the
  # goal and drop the two lines a later session could act on.
  out="$(cat "$project/.oms/memory/shared.md")"
  printf '%s' "$out" | grep -Fq 'decision: ' ||
    fail "the decision already in the packet should survive close: $out"
  printf '%s' "$out" | grep -Fq 'PATH stub shadowed' ||
    fail "the pitfall already in the packet should survive close: $out"
}

test_task_verify_files_and_clears_its_own_failures() {
  local project="$TMP/verify-ledger"
  local gate='bash -c "grep -q fixed state.txt || { echo ERROR: state.txt not fixed; exit 1; }; echo ok"'
  local out

  make_committed_repo "$project"
  printf 'broken\n' > "$project/state.txt"
  "$ROOT/scripts/agent-task.sh" --repo "$project" init --goal "fix state" --verify "$gate" >/dev/null

  # The failure ledger only ever saw harness-mediated paths, so the gate the
  # primary agent actually runs went unrecorded and the same break could be
  # diagnosed twice.
  "$ROOT/scripts/agent-task.sh" --repo "$project" verify >/dev/null 2>&1 || true
  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" list --unresolved)"
  printf '%s' "$out" | grep -Fq 'ERROR: state.txt not fixed' ||
    fail "a failed gate should file a row carrying the failing line: $out"

  # The readers are already wired: patch-land and plan-run ask this before
  # acting, so a row filed here is seen without any new integration.
  # check signals "this failed before" through its exit code, which is why
  # patch-land.sh:305 also takes it with `|| true`.
  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" check --cmd "$gate" 2>&1 || true)"
  printf '%s' "$out" | grep -Fq 'already failed' ||
    fail "the existing check path should see the row: $out"

  # Same gate, fixed code: the row clears, so the ledger answers "is this still
  # broken" rather than "did this ever break".
  printf 'fixed\n' > "$project/state.txt"
  "$ROOT/scripts/agent-task.sh" --repo "$project" verify >/dev/null 2>&1 ||
    fail "a passing gate must still verify the task"
  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" list --unresolved)"
  if printf '%s' "$out" | grep -Fq 'state.txt not fixed'; then
    fail "a passing gate should clear its own row: $out"
  fi
}

test_task_verify_survives_a_gate_with_no_failure_line() {
  local project="$TMP/verify-quiet"

  # A passing gate prints nothing matching the summary patterns. Computing that
  # summary on the success path once killed every passing verify under set -e.
  make_committed_repo "$project"
  "$ROOT/scripts/agent-task.sh" --repo "$project" init --goal "quiet gate" --verify "true" >/dev/null
  "$ROOT/scripts/agent-task.sh" --repo "$project" verify >/dev/null 2>&1 ||
    fail "a silent passing gate must verify, not abort"
}

test_delegate_consults_an_advisor_after_a_repair_also_fails() {
  local project="$TMP/delegate-advise"
  local bin="$project/bin"
  local home_dir="$project/home"
  local out
  local artifact

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir"
  # The worker never succeeds; the advisor is a second provider, which is what
  # the default picker looks for — an opinion from something other than the
  # agent that is already stuck.
  cat > "$bin/codex" <<'EOF'
#!/usr/bin/env bash
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) printf 'codex 1.0\n'; exit 0 ;; esac
cat > /dev/null
echo "tried and failed"
exit 1
EOF
  cat > "$bin/claude" <<'EOF'
#!/usr/bin/env bash
case "${1:-}" in --version|--help) printf 'claude 1.0\n'; exit 0 ;; esac
cat > /dev/null
echo "VERDICT: stop. The brief names a file that does not exist in this tree."
EOF
  chmod +x "$bin/codex" "$bin/claude"

  out="$(HOME="$home_dir" PATH="$bin:/usr/bin:/bin" OMS_ADVISOR_PROVIDER=claude \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --prompt "a task that keeps failing" --no-verify --repair 2 2>&1)" || true

  printf '%s' "$out" | grep -Fq 'advisor consulted after repeated failure' ||
    fail "a second failing attempt should pull in an outside opinion: $out"
  artifact="$(printf '%s' "$out" | sed -n 's/^artifact: //p' | head -n 1)"
  grep -Fq 'Advisor (after repeated failure)' "$artifact" ||
    fail "the advice belongs in the artifact"
  grep -Fq 'The brief names a file that does not exist' "$artifact" ||
    fail "the advisor's actual answer should be recorded"

  # Once per delegation: the point is a different opinion, not a second loop.
  [ "$(grep -c 'Advisor (after repeated failure)' "$artifact")" = 1 ] ||
    fail "the advisor should be consulted once, not every round"
}

test_delegate_does_not_consult_an_advisor_on_a_first_failure() {
  local project="$TMP/delegate-advise-first"
  local bin="$project/bin"
  local home_dir="$project/home"
  local out

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir"
  printf '#!/usr/bin/env bash\ncase "${1:-}:${2:-}" in --version:|--help:|exec:--help) printf "codex 1.0\\n"; exit 0 ;; esac\ncat > /dev/null\necho nope\nexit 1\n' > "$bin/codex"
  printf '#!/usr/bin/env bash\ncase "${1:-}" in --version|--help) printf "claude 1.0\\n"; exit 0 ;; esac\ncat > /dev/null\necho advice\n' > "$bin/claude"
  chmod +x "$bin/codex" "$bin/claude"

  # One repair is the ordinary path: a worker that stumbles once and is told so
  # usually recovers, and an advisor call there would be a tax on every run.
  out="$(HOME="$home_dir" PATH="$bin:/usr/bin:/bin" OMS_ADVISOR_PROVIDER=claude \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --prompt "fails once" --no-verify --repair 1 2>&1)" || true
  if printf '%s' "$out" | grep -Fq 'advisor consulted'; then
    fail "a single repair round should not pay for an advisor: $out"
  fi
}

test_harness_child_cannot_start_recursive_peer_work() {
  local project="$TMP/child-peer-authority"
  local bin="$project/bin"
  local home_dir="$project/home"
  local counter="$project/provider-calls"
  local router_counter="$project/router-provider-calls"
  local router_output="$project/router-child.out"
  local verify_sentinel="$project/reviewer-verify-ran"
  local verdicts="$project/verdicts"
  local output rc label

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir" "$verdicts"
  for provider in codex claude agy; do
    cat > "$bin/$provider" <<'EOF'
#!/usr/bin/env bash
printf 'called\n' >> "$OMS_TEST_PEER_COUNTER"
cat >/dev/null || true
printf 'A complete fixture answer that should never be reached by a harness child.\n'
EOF
    chmod +x "$bin/$provider"
  done

  assert_child_peer_refused() {
    label="$1"
    shift
    output="$project/$label.out"
    rc=0
    OMS_HARNESS_CHILD=1 OMS_TEST_PEER_COUNTER="$counter" \
      HOME="$home_dir" PATH="$bin:/usr/bin:/bin" "$@" \
      >"$output" 2>&1 || rc=$?
    [ "$rc" = 2 ] ||
      fail "harness child peer start $label returned $rc: $(cat "$output")"
    grep -Fq 'a harness child cannot start peer calls or delegation' "$output" ||
      fail "harness child peer refusal $label was not actionable: $(cat "$output")"
  }

  assert_child_peer_refused agent-call "$ROOT/scripts/agent-call.sh" \
    --to codex --repo "$project" --prompt child
  assert_child_peer_refused agent-run-read "$ROOT/scripts/agent-run.sh" \
    --to codex --repo "$project" --prompt child --mode read --dry-run
  assert_child_peer_refused agent-run-write "$ROOT/scripts/agent-run.sh" \
    --to codex --repo "$project" --prompt child --mode write --no-verify \
    --apply --dry-run
  assert_child_peer_refused peer-ask "$ROOT/scripts/peer-ask.sh" \
    --repo "$project" --providers codex --prompt child --dry-run
  assert_child_peer_refused peer-review "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --providers codex --prompt child --no-diff --gate \
    --verify 'touch reviewer-verify-ran'
  assert_child_peer_refused peer-delegate env OMS_DELEGATE_MAX_DEPTH=999 \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --prompt child --no-verify --apply --dry-run
  assert_child_peer_refused consult "$ROOT/scripts/consult.sh" \
    --to codex --repo "$project" --prompt child --dry-run
  assert_child_peer_refused advise "$ROOT/scripts/advise.sh" \
    --to codex --repo "$project" --prompt child --no-failures \
    --no-strategy --dry-run

  # The public guards prevent ordinary callers reaching the common router.
  # Exercise that defense directly so a future front door cannot bypass it.
  rc=0
  (
    # shellcheck source=scripts/lib/peer-common.sh
    . "$ROOT/scripts/lib/peer-common.sh"
    ma_run_routed_provider_inner() {
      printf 'called\n' >> "$router_counter"
    }
    ma_resolve_seat_recovery() { return 0; }
    OMS_HARNESS_CHILD=1 ma_run_routed_provider codex read /dev/null \
      "$project/router-artifact" "$project" router-test "" router-test
  ) >"$router_output" 2>&1 || rc=$?
  [ "$rc" = 2 ] ||
    fail "common provider router let a harness child through: $(cat "$router_output")"
  [ ! -e "$router_counter" ] ||
    fail "common provider router dispatched a child-marked call"

  (
    # shellcheck source=scripts/lib/peer-common.sh
    . "$ROOT/scripts/lib/peer-common.sh"
    ma_run_routed_provider_inner() {
      printf 'called\n' >> "$router_counter"
    }
    ma_resolve_seat_recovery() { return 0; }
    ma_run_routed_provider codex read /dev/null "$project/router-artifact" \
      "$project" router-test "" router-test
  ) >/dev/null 2>&1 || fail "an unmarked owner could not use the common provider router"
  [ -s "$router_counter" ] ||
    fail "the common provider router regression never reached its provider stub"

  [ ! -e "$counter" ] || fail "a refused child peer start reached a provider"
  [ ! -e "$verify_sentinel" ] ||
    fail "a refused child peer-review executed its verifier"
  [ ! -e "$project/.oms" ] ||
    fail "a refused child peer start wrote project authority state"

  # Verdict extraction is observation, not a new peer call.
  printf '# codex review\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$verdicts/codex-child-20260611T000000Z-1.md"
  OMS_HARNESS_CHILD=1 "$ROOT/scripts/peer-review.sh" verdicts "$verdicts" \
    >/dev/null || fail "a harness child should be able to inspect review verdicts"
  OMS_HARNESS_CHILD=1 "$ROOT/scripts/agent-call.sh" --help >/dev/null ||
    fail "peer help should remain available to a harness child"
}

test_delegate_refuses_to_nest_beyond_the_depth_cap() {
  local project="$TMP/delegate-depth"
  local bin="$project/bin"
  local home_dir="$project/home"
  local rc=0
  local out

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir"
  printf '#!/usr/bin/env bash\ncat > /dev/null\necho worked\n' > "$bin/codex"
  chmod +x "$bin/codex"

  # Nesting multiplies: a worker that delegates can spawn workers that delegate.
  # The project rules already said a worker does not do this; nothing enforced
  # it, and a worker that tried simply succeeded.
  out="$(HOME="$home_dir" PATH="$bin:/usr/bin:/bin" OMS_HARNESS_DELEGATE_DEPTH=1 \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --prompt "spawn from inside a worker" --no-verify 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "a worker must not spawn its own worker: $out"
  printf '%s' "$out" | grep -Fq 'does not spawn its own workers' ||
    fail "the refusal should say what to do instead: $out"
  printf '%s' "$out" | grep -Fq 'let the parent fan out' ||
    fail "the refusal should return recursive work to the parent: $out"

  # A two-stage job can raise the cap on purpose, in one place.
  rc=0
  HOME="$home_dir" PATH="$bin:/usr/bin:/bin" OMS_HARNESS_DELEGATE_DEPTH=1 \
    OMS_DELEGATE_MAX_DEPTH=2 "$ROOT/scripts/peer-delegate.sh" --to codex \
    --repo "$project" --prompt "explicitly nested" --no-verify >/dev/null 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "an explicitly raised cap should allow one more level"

  # And the top level is unaffected.
  rc=0
  HOME="$home_dir" PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --prompt "top level" --no-verify >/dev/null 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "an ordinary delegation must still run"
}

test_delegate_reports_a_worker_that_could_not_act() {
  local project="$TMP/delegate-blocked"
  local bin="$project/bin"
  local home_dir="$project/home"
  local rc=0
  local out

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir"
  # A CLI that exits 0 having printed only its reason for doing nothing. The
  # empty patch that follows is indistinguishable from honest work on an
  # already-correct tree, which is how a permission problem reads as success.
  cat > "$bin/codex" <<'EOF'
#!/usr/bin/env bash
cat > /dev/null
echo 'jetski: no output produced — a tool required the "unsandboxed" permission that headless mode cannot prompt for, so it was auto-denied.'
exit 0
EOF
  chmod +x "$bin/codex"

  out="$(HOME="$home_dir" PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --prompt "add a thing" --no-verify --repair 2 2>&1)" || rc=$?

  # The script keeps its one failure code; the distinct 126 rides on the worker
  # status, where a caller reading the run can tell "could not act" from "acted
  # and failed".
  [ "$rc" != 0 ] || fail "a blocked worker must not report success: $out"
  printf '%s' "$out" | grep -Fq 'could not run' ||
    fail "the operator needs to be told the worker never acted: $out"
  printf '%s' "$out" | grep -Fq 'exit 126' ||
    fail "a blocked worker should be distinguishable from a failed one: $out"
  # No rewording of the brief grants a permission, so repair must not burn calls.
  if printf '%s' "$out" | grep -Fq 'repair 1'; then
    fail "a blocked worker is not repairable: $out"
  fi
}

test_landing_refuses_while_another_landing_holds_the_repo() {
  local project="$TMP/landing-serialized"
  local patch="$TMP/landing-serialized.patch"
  local holder_pid
  local waited=0
  local rc=0
  local out

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )
  mkdir -p "$project/.oms"
  printf '*\n' > "$project/.oms/.gitignore"

  # Stand in for a landing already in flight. Two landers can both see a clean
  # tree and both pass admission against the same base, so the second must be
  # turned away rather than applying into the first one's half-landed tree.
  (
    . "$ROOT/scripts/lib/file-lock.sh"
    oms_hold_file_lock "$project/.oms/landings.jsonl" 7 || exit 1
    : > "$project/held"
    while [ -f "$project/held" ]; do sleep 1; done
    # A real holder releases on exit the way patch-land does; only an flock fd
    # is dropped for free by the kernel.
    oms_release_held_file_lock
  ) &
  holder_pid=$!
  while [ ! -f "$project/held" ]; do
    waited=$((waited + 1))
    [ "$waited" -lt 50 ] || fail "the stand-in landing never took the lock"
    sleep 1
  done

  out="$("$ROOT/scripts/patch-land.sh" --patch "$patch" --repo "$project" 2>&1)" || rc=$?
  rm -f "$project/held"
  wait "$holder_pid" 2>/dev/null || true

  [ "$rc" != 0 ] || fail "a concurrent landing should be refused: $out"
  printf '%s' "$out" | grep -Fq 'another landing or recovery is in progress' ||
    fail "the refusal should name the reason: $out"
  [ -z "$(git -C "$project" status --porcelain -- file.txt)" ] ||
    fail "the refused landing must not have applied anything"

  # The lock is not sticky: once the holder is gone the same landing proceeds.
  rc=0
  out="$("$ROOT/scripts/patch-land.sh" --patch "$patch" --repo "$project" 2>&1)" || rc=$?
  [ "$rc" = 0 ] || fail "landing should succeed once the lock is free: $out"
}

test_landing_recovery_refuses_a_changed_patch() {
  local project="$TMP/landing-patchbound"
  local patch="$project/change.patch"
  local rc=0
  local out

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )
  mkdir -p "$project/.oms"
  printf '*\n' > "$project/.oms/.gitignore"
  # The intent names a patch whose content no longer matches: recovery cannot
  # tell whether THIS patch landed, and guessing writes a false record.
  printf '{"schema":1,"ts":"2026-07-27T00:00:00Z","landing_id":"l1","event":"intent","patch":"%s","patch_sha":"deadbeef","task":"","lease":""}\n' \
    "$patch" > "$project/.oms/landings.jsonl"

  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "a changed patch should make recovery exit nonzero: $out"
  printf '%s' "$out" | grep -Fq 'recover this one by hand' ||
    fail "recovery should hand it to a human: $out"
  # Neither outcome may be recorded: the transaction stays outstanding.
  if grep -Eq '"event": ?"(complete|abandoned)"' "$project/.oms/landings.jsonl"; then
    fail "recovery must not guess an outcome for a changed patch"
  fi
}

test_provider_contract_check_passes_without_providers() {
  local home="$TMP/pc-home"
  local out

  mkdir -p "$home"
  # A machine with no provider CLIs and no registrations is healthy: loader
  # parity and fail-open still verify, MCP checks become notes.
  out="$(HOME="$home" CODEX_HOME="$home/.codex" PATH="/usr/bin:/bin" \
    bash "$ROOT/scripts/doctor.sh" --contract 2>&1)" ||
    fail "provider-contract should pass with no providers: $out"
  printf '%s\n' "$out" | grep -q 'ok: loader parity (general)' ||
    fail "general loader parity not verified: $out"
  printf '%s\n' "$out" | grep -q 'ok: loader parity (ml)' ||
    fail "ml loader parity (GEMINI adoption + style retire) not verified: $out"
  printf '%s\n' "$out" | grep -q 'ok: fail-open' ||
    fail "fail-open hook contract not verified: $out"
  printf '%s\n' "$out" | grep -q 'note: mcp (claude): CLI not installed' ||
    fail "missing CLI must be a note, not a failure: $out"
  printf '%s\n' "$out" | grep -q 'provider-contract: ok' ||
    fail "missing ok summary: $out"
}

test_provider_contract_flags_mcp_drift() {
  local home="$TMP/pc-drift-home"
  local bin="$TMP/pc-drift-bin"
  local srv1="$TMP/pc-drift-srv1"
  local srv2="$TMP/pc-drift-srv2"
  local out rc

  mkdir -p "$home" "$home/.codex" "$bin" "$srv1" "$srv2"
  printf '#!/bin/sh\nexit 0\n' > "$bin/claude"
  chmod +x "$bin/claude"
  : > "$srv1/oms-mcp-server.py"
  : > "$srv2/oms-mcp-server.py"
  cat > "$home/.claude.json" <<EOF
{"mcpServers":{"oh-my-setting":{"type":"stdio","command":"python3","args":["$srv1/oms-mcp-server.py"]}}}
EOF
  cat > "$home/.codex/config.toml" <<EOF
[mcp_servers.oh-my-setting]
command = "python3"
args = ["$srv2/oms-mcp-server.py"]
EOF

  # Two providers reading two different servers is the drift this gate exists
  # to catch, even when each registration is individually valid.
  rc=0
  out="$(HOME="$home" CODEX_HOME="$home/.codex" PATH="$bin:/usr/bin:/bin" \
    bash "$ROOT/scripts/doctor.sh" --contract 2>&1)" || rc=$?
  [ "$rc" = 1 ] || fail "drifted registrations should exit 1 (rc=$rc): $out"
  printf '%s\n' "$out" | grep -q 'fail: mcp parity' ||
    fail "parity drift not reported: $out"

  cat > "$home/.codex/config.toml" <<EOF
[mcp_servers.oh-my-setting]
command = "python3"
args = ["$srv1/oms-mcp-server.py"]
EOF
  out="$(HOME="$home" CODEX_HOME="$home/.codex" PATH="$bin:/usr/bin:/bin" \
    bash "$ROOT/scripts/doctor.sh" --contract 2>&1)" ||
    fail "aligned registrations should pass: $out"
  printf '%s\n' "$out" | grep -q 'ok: mcp parity' ||
    fail "parity ok line missing: $out"
}

